E["item:cenarion-moondust"] = {t="item",n="Cenarion Moondust",z="darnassus",s="At the Moonkin Stone east of Auberdine, Cenarion Moondust calls forth Lunaclaw. Night elf druids use the sacred powder in their trial to become Druids of the Claw.",h="At the Moonkin Stone east of Auberdine, Cenarion Moondust calls forth Lunaclaw.",sec={{t="A Rite of the Claw",b="Mathrengyl Bearwalker gives Cenarion Moondust to young druids in Darnassus for their final trial of heart and body. To face Lunaclaw, the guardian, an initiate travels to the moonkin dens east of Auberdine in Darkshore. Scattered on the ancient Moonkin Stone, the powder summons Lunaclaw to test the druid in combat. Through the trial, the initiate takes in the enduring strength needed to channel the bear form.",sp=0}},faq={{q="What is Cenarion Moondust used for?",a="Night elf druid initiates scatter Cenarion Moondust on the Moonkin Stone in Darkshore to summon Lunaclaw and prove their strength and resolve in the trial for bear form.",al={"moondust use","what does cenarion moondust do","cenarion moondust purpose"},it="purpose",gp=true},{q="Where do I use the Cenarion Moondust?",a="Scatter the Cenarion Moondust over the Moonkin Stone in a moonkin cave in the hills directly east of Auberdine in Darkshore.",al={"where to use moondust","moonkin stone location","where is lunaclaw stone"},it="place",gp=true},{q="Who provides Cenarion Moondust?",a="Mathrengyl Bearwalker, a druid trainer at the Cenarion Enclave in Darnassus, gives Cenarion Moondust to initiates ready for the trial of body and heart.",al={"who gives moondust","where to get cenarion moondust","mathrengyl moondust"},it="origin",gp=true},{q="What happens if I lose the moondust?",a="If the moondust is lost or spent in a failed attempt against Lunaclaw, return to Darnassus and ask Mathrengyl Bearwalker to renew the trial.",al={"lost cenarion moondust","lost moondust","get moondust back"},gp=true},{q="What is Cenarion Moondust?",a="Cenarion Moondust is a sacred powder bestowed by the Cenarion Circle upon night elf druids who seek the mantle of the Druid of the Claw. It carries the blessing of the wild and is used as a ritual reagent to honor and call forth ancient guardian spirits.",al={"what is cenarion moondust","cenarion moondust lore","moondust purpose"},it="identity",add="d9963f3d"},{q="Where does Cenarion Moondust come from, and who made it?",a="The dust is prepared and kept by the Cenarion Circle in Darnassus. It is granted specifically by druid trainers such as Mathrengyl Bearwalker to initiates who have demonstrated reverence and earned the right to undertake their sacred trials.",al={"who made cenarion moondust","origin of cenarion moondust","where did moondust come from"},it="origin",add="34087882"},{q="Why is Cenarion Moondust needed?",a="The moondust is required to awaken Lunaclaw, the ancient beast who guards the Moonkin Stone in Darkshore. Lunaclaw will only heed the challenge of an initiate who applies this sacred dust to the stone, allowing the druid to prove their strength of body and heart.",al={"why do i need cenarion moondust","why use moondust","what is the purpose of cenarion moondust"},it="why_wanted",add="1f04d9d3"}},ang={["class:Druid"]="As a night elf druid, using Cenarion Moondust begins the final step toward becoming a Druid of the Claw and mastering bear form.",["race:NightElf"]="As a night elf, you encounter the ancient traditions of the Cenarion Circle in the dust, which joins nature worship with lunar ritual to honor Darkshore's beasts."},kw={"auberdine","body and heart","cenarion moondust","druid of the claw","lunaclaw","mathrengyl bearwalker","moondust","moonkin stone"},rel={"quest:6001","npc:mathrengyl-bearwalker","topic:druid","zone:darkshore","subzone:auberdine","zone:darnassus","quest:2561","topic:alliance"},src={"Cenarion Moondust","Body and Heart (Alliance)"}}
E["item:fandral-s-message"] = {t="item",n="Fandral's Message",z="darnassus",s="In Darnassus, Fandral Staghelm sends a message across the sea to Onu in Darkshore. The sealed dispatch carries news about Oracle Glade in Teldrassil.",h="In Darnassus, Fandral Staghelm sends a message across the sea to Onu in Darkshore.",sec={{t="A Dispatch from the Archdruid",b="Arch Druid Fandral Staghelm writes from the Cenarion Enclave in Darnassus. His sealed dispatch is addressed to Onu, the Ancient of Lore who dwells in the Grove of the Ancients. Reports have reached Fandral about the state of Oracle Glade in Teldrassil, and he sends a courier south of Auberdine with word for Onu. The journey crosses the waters to Darkshore, carrying a message from the heart of the new World Tree to Kalimdor’s older, shadowed mainland.",sp=0},{t="Contrasting Tempos",b="Onu remarks that Fandral is always in a hurry. The Ancient of Lore says affairs should unfold at nature’s own pace, as the ancients believe. To the slow-living treants of Darkshore, Fandral’s haste differs sharply from the patient wisdom once shown by Archdruid Malfurion Stormrage.",sp=1}},faq={{q="What is Fandral's Message?",a="Fandral’s Message is a sealed dispatch from Arch Druid Fandral Staghelm to Onu, the Ancient of Lore in the Grove of the Ancients in Darkshore.",al={"fandrals message item","fandral message","archdruids letter"},it="identity"},{q="Who sends this message and why?",a="Arch Druid Fandral Staghelm writes from Darnassus after receiving reports about Oracle Glade in Teldrassil. He sends word to Onu in Darkshore.",al={"who wrote this","why fandral send message"},it="origin"},{q="Where does this message need to go?",a="Carry the message to Onu in the Grove of the Ancients in Darkshore, directly south of Auberdine.",al={"who gets the message","where to deliver message","fandrals message destination"},it="target"},{q="What does Onu think of the letter?",a="Onu says Fandral is always in a hurry. The Ancient observes that nature moves at its own pace, a truth Shan'do Malfurion Stormrage understood better.",al={"onu reaction","what does onu say"}},{q="Why does Onu want Fandral's Message?",a="Onu, an ancient of lore resting in Darkshore's Grove of the Ancients, has been awaiting word from Archdruid Fandral Staghelm regarding the state of Teldrassil. After receiving news from the Oracle Glade, Fandral immediately sent you across the sea with this dispatch. Onu patiently takes the correspondence, though the ancient quietly reflects that the restless Archdruid always appears in far too much of a hurry compared to the patient wisdom Shan'do Stormrage once showed.",al={"why does onu want the message","why does onu need fandral's letter","why deliver fandral's message"},it="why_wanted",add="22d06606"}},ang={["class:Druid"]="As a druid, carrying a message between the Cenarion Enclave in Darnassus and the Ancients of Lore in Darkshore shows the divide between Fandral Staghelm’s drive and the older guardians’ patience.",["race:NightElf"]="As a night elf, this dispatch takes you from the crown of Teldrassil toward the ancestral forests of Kalimdor’s mainland."},kw={"ancient of lore","auberdine","darkshore","darnassus","fandral staghelm","fandral's message","grove of the ancients","onu","oracle glade"},rel={"quest:952","quest:940","quest:937","zone:darkshore","subzone:auberdine","subzone:oracle-glade","topic:shan-do","topic:druid"},src={"Fandral's Message","Grove of the Ancients (quest)"}}
E["item:mossy-tumor"] = {t="item",n="Mossy Tumor",z="darnassus",s="Around Wellspring Lake, mossy tumors mark Teldrassil's spreading corruption. Carved from the bark and flesh of corrupted timberlings, these poisonous growths show the malevolence taking hold in the young World Tree.",h="Around Wellspring Lake, mossy tumors mark Teldrassil's spreading corruption.",sec={{t="A Symptom of Teldrassil's Malaise",b="Teldrassil's timberlings were made to nurture and tend the great tree's boughs, but many have grown hostile and diseased. Mossy tumors are signs of that sickness made flesh. Thick with toxins, they spread across the Mire Beasts, Tramplers, and Elder Timberlings around Wellspring Lake. Rellian Greenspyre and the keepers in Darnassus send travelers to cut away the tumors and burn them thoroughly, so their poison cannot take deeper root in the island's soil.",sp=0}},faq={{q="What is a Mossy Tumor?",a="A Mossy Tumor is a diseased growth taken from a tainted timberling. Its foul poison shows that Teldrassil's nature spirits suffer from an unnatural corruption.",al={"mossy tumor","what is this tumor","timberling tumor"},it="identity"},{q="Where do you find Mossy Tumors?",a="You find Mossy Tumors on corrupted timberlings around Wellspring Lake in northern Teldrassil, including Timberling Tramplers, Mire Beasts, and Elder Timberlings.",al={"where to get tumors","mossy tumor drop","timberling location"},gp=true},{q="Why does Rellian Greenspyre want these tumors?",a="Rellian Greenspyre wants the tumors to contain the corruption afflicting Teldrassil. He has them gathered and burned to ash so their concentrated poison cannot leach back into the soil and water.",al={"rellian greenspyre tumors","why burn tumors"},it="why_wanted"},{q="Why are the timberlings becoming diseased?",a="A malevolence is taking hold across Teldrassil, warping its caretakers and wild creatures. The night elves are investigating the sickness's true source, while timberlings with visible tumors are considered beyond saving.",al={"why are timberlings sick","timberling corruption"},it="origin"}},ang={["class:Druid"]="As a druid devoted to nature's balance, you may find toxic tumors on plant guardians like timberlings a distressing sign that something is profoundly wrong with Teldrassil.",["race:NightElf"]="As a night elf, you know your people planted Teldrassil to restore their lost connection to nature. Diseased growths appearing so quickly on your new home are a troubling omen."},kw={"corruption","darnassus","mossy tumor","rellian greenspyre","teldrassil","timberling","wellspring lake"},rel={"quest:923","quest:922","subzone:wellspring-lake","zone:darnassus","quest:940"},src={"Mossy Tumor","Tumors"}}
E["item:sathrah-s-sacrifice"] = {t="item",n="Sathrah's Sacrifice",z="darnassus",s="At the Temple of the Moon, Sathrah's Sacrifice offers Lady Sathrah's spirit a chance at peace. Her silvery spinnerets come from the mighty spider who dwells in Teldrassil.",h="At the Temple of the Moon, Sathrah's Sacrifice offers Lady Sathrah's spirit a chance at peace.",sec={{t="Purification in the Holy Waters",b="Lady Sathrah was a venerable creature of Teldrassil, until creeping madness and corruption spread through the great tree's boughs and took hold of her. The Sisterhood of Elune asks you to bring back her silvery spinnerets as a consecrated offering, not a trophy. At the fountain in the Temple of the Moon, the remains are bathed in holy water. The rite washes away the taint that poisoned Sathrah's mind and frees her troubled soul. Her spirit then appears peacefully within the sanctuary, with the promise of rebirth under Elune's grace.",sp=0}},faq={{q="What is Sathrah's Sacrifice?",a="Sathrah's Sacrifice is an offering of silvery spinnerets taken from Lady Sathrah, a mighty spider corrupted in Teldrassil. The Sisterhood of Elune uses them in a rite to cleanse her soul.",al={"what are the spinnerets","sathrah sacrifice item","lady sathrah offering"},it="identity"},{q="Why must the spinnerets be placed in the fountain?",a="The fountain in Darnassus's Temple of the Moon holds holy water consecrated to Elune. Submerging Sathrah's remains washes away the corruption that drove her mad and releases her spirit from agony.",al={"why temple fountain","why sacrifice sathrah","what does the fountain do"},it="purpose"},{q="What happens when the offering is presented?",a="When you place the offering in the sacred waters, the corruption is purged and Lady Sathrah's spectral form appears. She walks serenely around the pool, showing that her soul is at peace.",al={"what happens at the fountain","spirit of sathrah appear","fountain event"},sp=1},{q="Who oversees this ritual?",a="Priestess A'moora oversees the rite. A servant of the Sisterhood of Elune stationed in the Temple of the Moon, she directs you to lay Sathrah to rest and offer her remains to the goddess.",al={"who gives sathrahs sacrifice","priestess a'moora quest","who cleanses sathrah"}},{q="Where does Sathrah's Sacrifice come from?",a="Priestess A'moora prepared this offering directly from the silvery spinnerets taken from Lady Sathrah, a great spider felled in Teldrassil after falling into madness and corruption.",al={"sathrahs sacrifice origin","where did sathrahs sacrifice come from","who made sathrahs sacrifice"},it="origin",add="c7289e92"},{q="Why does Priestess A'moora want Sathrah's Sacrifice?",a="Priestess A'moora requires the sacrifice so it can be laid in the holy waters of the Temple of the Moon. Through this offering to Elune, the corruption that twisted Lady Sathrah in life can finally be cleansed, laying the great beast to rest and allowing her spirit to be reborn renewed.",al={"why is sathrahs sacrifice wanted","why offer sathrahs sacrifice","what is sathrahs sacrifice for"},it="why_wanted",add="b18748b3"}},ang={["race:NightElf"]="As a night elf, you know that putting down corrupted wildlife is a somber duty. Returning Lady Sathrah's spirit to Elune's grace honors that duty.",["class:Priest"]="As a priest, you can see the rite as an act of divine mercy. The Sisterhood of Elune uses holy waters to cleanse taint, rather than merely discarding the slain beast."},kw={"darnassus","elune","lady sathrah","priestess a'moora","sathrah's sacrifice","silvery spinnerets","spider","teldrassil","temple of the moon"},rel={"quest:2520","npc:priestess-a-moora","subzone:temple-of-the-moon","item:silvery-spinnerets","topic:elune","quest:2518","quest:2519"},src={"Sathrah's Sacrifice","Sathrah's Sacrifice (quest)"}}
E["item:sethir-s-journal"] = {t="item",n="Sethir's Journal",z="darnassus",s="On Teldrassil, Sethir's Journal was recovered through stealth. Its pages confirm that corruption from mainland Kalimdor has reached the World Tree.",h="On Teldrassil, Sethir's Journal was recovered through stealth.",sec={{t="A Clue to the Taint",b="Teldrassil was raised in the hope of reclaiming elven immortality, yet an unseen sickness has taken root across its boughs. In Darnassus, Syurna suspected that Sethir the Ancient held answers. The solitary satyr lurks on an outlying branch near the Oracle Glade. Past scouts who tried diplomacy or open force met only death, so stealthy pickpocketing yielded Sethir's journal. Its writings reveal that the mysterious blight poisoning the woods and waters across the sea in Darkshore has crossed into Teldrassil itself.",sp=1}},faq={{q="What is Sethir's Journal?",a="Sethir's Journal is carried by Sethir the Ancient, a hostile satyr living along the outer branches near the Oracle Glade on Teldrassil. Its notes detail the corruption spreading through the region.",al={"what is sethirs journal","sethir journal lore","who owns sethirs journal"},it="identity"},{q="How is the journal obtained?",a="Past attempts to bargain with or fight Sethir ended in failure and death. The journal must be lifted from his packs through stealth.",al={"how do i get sethirs journal","where to get sethir journal","pickpocket sethir"},gp=true},{q="What does the journal reveal?",a="Rogue trainer Syurna says the journal proves that the strange sickness blighting Darkshore's forests and waters has reached Teldrassil.",al={"what does sethir journal say","what is in sethir journal"},it="why_wanted"},{q="Who is Sethir the Ancient?",a="Sethir the Ancient is a solitary satyr on a secluded branch along the outskirts of the Oracle Glade. He deals violently with interlopers and holds information on the corruption creeping across the World Tree.",al={"who is sethir","sethir the ancient"}},{q="Where does Sethir's Journal come from, and who made it?",a="The journal belongs to Sethir the Ancient, a hostile satyr lurking on a high bough on the fringes of the Oracle Glade in Teldrassil. Carrying his personal writings and records among his belongings, he kept the journal until rogues in Darnassus sought to quietly lift it from his possession to uncover what corruption is spreading across the world tree.",al={"who wrote sethir's journal","origin of sethirs journal","sethir journal origin"},it="origin",add="3d18c972"}},ang={["class:Rogue"]="As a Rogue, you can use stealth and pickpocketing to uncover vital intelligence where warriors and diplomats failed.",["race:NightElf"]="As a Night Elf, you face evidence that Teldrassil is not immune to the ancient demonic taint creeping across mainland Kalimdor."},kw={"darkshore","destiny calls","oracle glade","satyr","sethir the ancient","sethir's journal","syurna","teldrassil"},rel={"quest:2242","npc:syurna","subzone:oracle-glade","zone:darkshore","topic:satyr","quest:940","quest:397"},src={"Sethir's Journal","Destiny Calls"}}
E["item:silvery-spinnerets"] = {t="item",n="Silvery Spinnerets",z="darnassus",s="Near Wellspring Lake, Silvery Spinnerets are harvested from Lady Sathrah in northern Teldrassil. Her silver webs once gathered healing evening dew for the Temple of the Moon. The Sisterhood of Elune seeks the spinnerets for a sacred rite honoring her soul.",h="Near Wellspring Lake, Silvery Spinnerets are harvested from Lady Sathrah in northern Teldrassil.",sec={{t="Sacred Webbing and Corruption",b="Lady Sathrah once spun shimmering webs by moonlight near Wellspring Lake. Her silver silk gathered evening mist into healing dew prized by the Sisterhood of Elune in Darnassus. But corruption reached her in Teldrassil, driving her into violent madness. Sathrah threatened her brood and the surrounding forest. Priestess A'moora asks travelers to end her suffering and recover her spinnerets, bringing mercy to a once-revered creature of the great boughs.",sp=0},{t="A Sacrifice for Rebirth",b="The Sisterhood offers the recovered spinnerets to Elune at the central fountain inside the Temple of the Moon. In a rite called Sathrah's Sacrifice, the priestesses pray that the Moon Goddess will receive the creature's spirit, cleanse the madness that claimed her mortal body, and grant her peace in rebirth.",sp=1}},faq={{q="Where do you get the Silvery Spinnerets?",a="Retrieve them from Lady Sathrah, a large spider along Teldrassil's northern borders near Wellspring Lake.",al={"where to find silvery spinnerets","silvery spinnerets drop","who drops silvery spinnerets"},it="place",gp=true},{q="Why does Priestess A'moora want the spinnerets?",a="Priestess A'moora seeks to offer the spinnerets to Elune as a sacred sacrifice. The rite honors Lady Sathrah's former purity and asks the goddess to cleanse her spirit and grant her peace and rebirth.",al={"why amoora wants spinnerets","tears of the moon purpose"},it="why_wanted"},{q="Why were Lady Sathrah's webs special?",a="Lady Sathrah spun luminous silver silk that caught evening mist beneath the moonlight. The gathered dew held potent restorative magic and was prized by the Sisterhood of Elune, who stored it in the Temple of the Moon for healing.",al={"lady sathrah webs","what did lady sathrah do"},it="power"},{q="Why was Lady Sathrah killed if she was sacred?",a="Corruption drove Lady Sathrah into incurable madness alongside other wildlife in Teldrassil. Her aggression endangered the forest and threatened her brood, so the priestesses judged slaying her a sorrowful act of mercy.",al={"why kill lady sathrah","why did sathrah go crazy"},it="motive"},{q="What are the Silvery Spinnerets?",a="The Silvery Spinnerets are the silk-producing organs taken from the sacred spider Lady Sathrah in northern Teldrassil. In healthier times, she used them to weave shimmering silver threads through the moonlight. These webs captured the evening mist, yielding a miraculous dew with potent healing properties cherished by the Priestesses of Elune.",al={"what are silvery spinnerets","silvery spinnerets info","lady sathrah spinnerets"},it="identity",add="6e94bdc8"},{q="Where do the Silvery Spinnerets come from?",a="They are harvested from Lady Sathrah, a giant spider dwelling near Wellspring Lake along Teldrassil's northern borders. Once revered as a graceful and pure creature blessed by Elune, Sathrah recently succumbed to madness, requiring the night elves to end her misery and reclaim her sacred remains.",al={"silvery spinnerets origin","who made silvery spinnerets","where to get silvery spinnerets"},it="origin",add="48fdca9c"}},ang={["race:NightElf"]="Lady Sathrah's tragic end reminds the Kaldorei that even creatures beloved by Elune can fall to the affliction sickening Teldrassil.",["class:Priest"]="For servants of Elune, retrieving the spinnerets is a sacred funeral rite. It asks the Mother Moon to redeem a creature, rather than treating her death as mere extermination."},kw={"lady sathrah","priestess a'moora","sathrah's sacrifice","silvery spinnerets","tears of the moon","temple of the moon","wellspring lake"},rel={"quest:2518","quest:2520","npc:priestess-a-moora","subzone:temple-of-the-moon","subzone:wellspring-lake","topic:elune","zone:darnassus","quest:2519"},src={"Silvery Spinnerets","Tears of the Moon (Classic)"}}
E["item:sunscorched-shell"] = {t="item",n="Sunscorched Shell",z="darnassus",s="Beneath Highperch, wyvern eggs leave shells hardened by Thousand Needles' desert heat. Armorer Mathiel in Darnassus uses them to make lacquer for mail links.",h="Beneath Highperch, wyvern eggs leave shells hardened by Thousand Needles' desert heat.",sec={{t="Desert Clutches",b="Highperch wyverns lay eggs on the mesa needles of southern Kalimdor. Beneath their roosts, discarded shell fragments bake in the desert sun and searing winds. Their brittle remains hold a natural resilience that draws the attention of skilled artisans.",sp=0},{t="A Craftsman's Lacquer",b="In Darnassus, armorer Mathiel studies methods pioneered by his colleague, the dwarf smith Furen Longbeard. Mathiel processes the shells into a fine lacquer for mail armor. Applied to the metal links, the coating strengthens them without burdening the wearer.",sp=0}},faq={{q="Where are Sunscorched Shells found?",a="You can find them beneath wyvern nests across Highperch, a high mesa rising from the canyon floor in western Thousand Needles.",al={"sunscorched shell location","where to find shells","highperch shells"},it="place",gp=true},{q="What creature do these shells come from?",a="They are broken eggshells from the Highperch wyverns that roost atop the plateaus in Thousand Needles.",al={"what laid these eggs","wyvern eggs","shell origin"},it="origin"},{q="Why does Mathiel want Sunscorched Shells?",a="Mathiel wants to test armorsmithing methods discovered by Furen Longbeard. He renders the hardened shells into a tough lacquer to reinforce mail links.",al={"mathiel shells","what are shells for","armor lacquer"},it="why_wanted"},{q="Who is Furen Longbeard and how is he involved?",a="Furen Longbeard is an iron-working colleague of Mathiel, based in Stormwind's Dwarven District. His experiments with unusual reagents and hardening methods inspired Mathiel to try lacquer made from wyvern shells.",al={"furen connection","furen longbeard shells"},it="ties"},{q="What is a Sunscorched Shell?",a="A Sunscorched Shell is the durable, discarded egg shell of a Highperch wyvern. Found baked under the harsh sun of Thousand Needles below the creatures' soaring nests, these resilient shells possess remarkable natural strength that makes them prized by skilled armorers.",al={"what is sunscorched shell","sunscorched shell item","sunscorched egg shell"},it="identity",add="f589915a"}},ang={["class:Warrior"]="As a warrior seeking mail protection, you can help Mathiel gather durable eggshells for reinforced armor.",["profession:Blacksmithing"]="As a blacksmith, you can see how skilled smiths use natural mineral coatings to make protective lacquer for linked armor."},kw={"darnassus","furen longbeard","highperch","mail armor","mathiel","sunscorched shell","thousand needles","wyvern"},rel={"quest:1710","subzone:highperch","quest:1703","npc:furen-longbeard","zone:thousandneedles","zone:darnassus"},src={"Sunscorched Shell","Sunscorched Shells"}}
E["item:velinde-s-journal"] = {t="item",n="Velinde's Journal",z="darnassus",s="Velinde Starsong's personal journal records her duties and the mystery of her departure from Darnassus. The Night Elf priestess's journal is stored in the Sentinel bunkhouse.",h="Velinde Starsong's personal journal records her duties and the mystery of her departure from Darnassus.",sec={{t="A Priestess's Record",b="When Night Elf priestess Velinde Starsong left Darnassus, her belongings were locked in a footlocker at the Sentinels' bunkhouse in the Tradesmen's Terrace. Among them was her personal journal, a record of her responsibilities and duties. The Sentinels respected Velinde and believed she had left to attend to private matters. Her journal's contents suggest her unexplained absence is more troubling than they first believed.",sp=0}},faq={{q="Where is Velinde's Journal found?",a="Velinde's Journal is inside her chest in the Sentinel bunkhouse, in Darnassus's Tradesmen's Terrace. Cross the upper bridge connected to the mail armor shop to reach the building.",al={"journal location","where is velinde journal","velindes locker location"},gp=true},{q="Who was Velinde Starsong?",a="Velinde Starsong was a respected Night Elf priestess, deeply trusted by the Sentinels. She left Darnassus suddenly and quietly, leaving her locker and belongings behind.",al={"who is velinde","velinde lore"},it="people"},{q="Why do the Sentinels care about her journal?",a="The Sentinels believed Velinde had left Darnassus for valid personal reasons and expected her to return. Her writings reveal darker implications behind her disappearance, and the Sentinels need to investigate further.",al={"why sentinels want journal","what is in the journal"},it="why_wanted"},{q="Who asks you to retrieve the journal?",a="Sentinel Thyn'tel Bladeweaver in Darnassus grants permission and gives you the key to Velinde's chest after you approach with knowledge learned from the Tome of Mel'Thandris.",al={"who gives quest","who is thyntel bladeweaver"},gp=true},{q="What is Velinde's Journal?",a="Velinde's Journal is a written record of duties and personal accounts kept by the night elf priestess Velinde Starsong. Stored among her belongings in the Sentinel bunkhouse in Darnassus after her sudden departure, it holds the only surviving record of her activities before she vanished.",al={"what is velindes journal","velinde journal","who wrote the journal"},it="identity",add="654b265d"},{q="Where does Velinde's Journal come from, and who made it?",a="The journal was penned by Priestess Velinde Starsong herself during her service to the night elves. Following her mysterious absence, her effects were gathered and locked away in a chest within the Sentinels' quarters in Darnassus, waiting for any clue that might explain her departure.",al={"who wrote velindes journal","origin of velindes journal","where did velindes journal come from"},it="origin",add="07b3d22b"}},ang={["race:NightElf"]="As a Night Elf, Velinde's mysterious departure touches Darnassus's leadership. The Sentinels guarding the Kaldorei capital are concerned.",["class:Priest"]="As a priest, Velinde's hidden duty and disappearance reveal troubling trials facing the Sisterhood of Elune."},kw={"darnassus","sentinels","thyn'tel bladeweaver","tradesmen's terrace","velinde starsong","velinde's journal","velinde's key","velinde's locker"},rel={"quest:1038","item:velinde-s-key","npc:thyn-tel-bladeweaver","zone:darnassus","topic:sentinels"},src={"Velinde's Journal","Velinde's Effects"}}
E["item:velinde-s-key"] = {t="item",n="Velinde's Key",z="darnassus",s="In Darnassus, Velinde's Key guards the writings of a vanished priestess. Thyn'tel Bladeweaver entrusts it to those who bring proof of their interest in Velinde Starsong's fate.",h="In Darnassus, Velinde's Key guards the writings of a vanished priestess.",sec={{t="A Trusted Token",b="Thyn'tel Bladeweaver keeps Velinde's Key in Darnassus. The simple key secures Priestess Velinde Starsong's personal belongings in a footlocker in the Sentinel bunkhouse above the Tradesmen's Terrace. Velinde left night elf lands without warning, and her possessions were set aside. Bladeweaver gives the key only to those who bring genuine evidence of their interest in learning her fate, such as revelations found in the Tome of Mel'Thandris.",sp=0},{t="Unlocking the Past",b="Velinde Starsong's key opens her storage chest, where her journal records her duties and troubled thoughts. The Sentinels long believed she had left for personal matters and would someday return. Her writings begin to reveal a darker, more perplexing mystery around the expedition that took her away.",sp=1}},faq={{q="What does Velinde's Key open?",a="Velinde's Key opens Velinde's Locker, a chest in the Sentinel bunkhouse in Darnassus. It is on the upper floor, across a bridge in the Tradesmen's Terrace.",al={"where do i use velinde's key","velinde locker","what chest does this open"},it="purpose",gp=true},{q="Who gives you the key?",a="Thyn'tel Bladeweaver, a Sentinel stationed in Darnassus, entrusts you with the key during the investigation into Velinde's disappearance.",al={"who has velindes key","where to get velinde key"},it="origin",gp=true},{q="Who is Velinde Starsong?",a="Velinde Starsong was a respected night elf priestess trusted by the Sentinels. She left suddenly on her own business, leaving her belongings behind in Darnassus.",al={"who is velinde","velinde backstory"},it="identity"},{q="What is found inside her locked chest?",a="Velinde's Journal rests inside the locker. It records her duties and sheds light on what compelled her to leave night elf lands.",al={"what is in velindes locker","velinde locker contents"},it="next_step",gp=true},{q="What is Velinde's Key?",a="Velinde's Key is the key to the footlocker holding the personal belongings of Priestess Velinde Starsong. Entrusted to the Darnassus Sentinels after her abrupt departure, it is kept by Thyn'tel Bladeweaver to safeguard the missing priestess's private possessions in the Sentinels' bunkhouse.",al={"velindes key","what is velinde's key","key to velindes chest"},it="identity",add="7f8c7b68"},{q="Why is Velinde's Key needed?",a="You need the key to open Velinde's storage chest in the Sentinels' bunkhouse. After learning of her from the Tome of Mel'Thandris, inspecting her belongings—specifically her personal journal—offers the best chance of uncovering why the revered priestess vanished and where her duties led her.",al={"why do i need velindes key","why want velindes key","purpose of velinde key"},it="why_wanted",add="927d5f5e"}},ang={["race:NightElf"]="As a night elf, you handle the belongings of a respected priestess whose loyalty to Elune and her people was beyond question.",["class:Priest"]="As a priest, you follow the traces of a devoted sister of Elune whose path took a solitary and troubling turn."},kw={"darnassus","locker","sentinel bunkhouse","thyn'tel bladeweaver","velinde starsong","velinde's effects","velinde's journal","velinde's key"},rel={"quest:1038","item:velinde-s-journal","npc:thyn-tel-bladeweaver","zone:darnassus","topic:sentinels"},src={"Velinde's Key","Velinde's Effects"}}
E["npc:chief-archaeologist-greywhisker"] = {t="npc",n="Chief Archaeologist Greywhisker",z="darnassus",s="In Darnassus, Chief Archaeologist Greywhisker gathers reports from the coast. The Ironforge dwarf works outside the Temple of the Moon, where he coordinates the Explorers' League's research and tracks colleagues in Darkshore.",h="In Darnassus, Chief Archaeologist Greywhisker gathers reports from the coast.",sec={{t="A Dwarven Scholar in Darnassus",b="Chief Archaeologist Greywhisker works outside the Temple of the Moon in Darnassus, far from his home in Ironforge. He represents the Explorers' League, which sent him across the sea to Kalimdor for fieldwork. There, he speaks with night elf scholars such as Tarelvir and seeks knowledge of the ancient lands. In Ironforge, his lectures covered ancient lore and primordial beings, including the Wild God Agamaggan. Now he hopes to learn what the night elves' ancestral lands hold.",sp=0},{t="Eyes on Darkshore",b="In Kalimdor, Greywhisker oversees dwarven excavations and follows expeditions searching ancient coastal ruins. He depends on travelers to carry messages to prospectors across the sea in Darkshore. Field research in unexplored lands is perilous, and he waits anxiously for reports from the dig sites, hoping his colleagues are safe among the ruins.",sp=0}},faq={{q="Who is Chief Archaeologist Greywhisker?",a="Chief Archaeologist Greywhisker is a dwarven scholar from Ironforge and a representative of the Explorers' League. Outside the Temple of the Moon in Darnassus, he coordinates the League's research in northern Kalimdor and speaks with night elf scholars.",al={"who is greywhisker","greywhisker lore","chief archaeologist"},it="identity"},{q="What is an Ironforge dwarf doing in Darnassus?",a="The Explorers' League sent Greywhisker across the sea to uncover forgotten history and ancient artifacts. He makes scholarly contacts in the night elf capital and oversees dwarven expeditions along Kalimdor's ancient coasts.",al={"why is a dwarf in darnassus","dwarf temple of the moon"},it="why_here"},{q="What is his connection to Agamaggan?",a="In Ironforge, Greywhisker lectured on ancient history, including the Wild God Agamaggan, a giant boar. His teachings inspired younger prospectors such as Lonebrow to study ancient beast folklore.",al={"greywhisker agamaggan","agamaggan lectures"}},{q="Who is Greywhisker talking to outside the temple?",a="Outside the Temple of the Moon in Darnassus, Greywhisker speaks with Tarelvir, a night elf scholar. They exchange ideas and coordinate historical research between their peoples.",al={"greywhisker tarelvir","who is with greywhisker"},it="ties"},{q="What trouble is he dealing with in Darkshore?",a="Greywhisker's fellow dwarven researchers are excavating ancient ruins in Darkshore, but isolated expeditions are hard to reach. He seeks couriers to check on absent-minded prospectors and recover their research journals.",al={"greywhisker darkshore","darkshore prospectors"},it="wants"},{q="Which faction does Greywhisker belong to?",a="Greywhisker belongs to the Explorers' League, an Ironforge archaeological organization devoted to discovering dwarven origins and ancient history. The League is aligned with the Alliance.",al={"greywhisker faction","explorers league darnassus"},it="side"}},ang={["race:Dwarf"]="As a dwarf, seeing one of Ironforge's leading scholars outside the Temple of the Moon recalls your people's drive to uncover ancient history across Kalimdor.",["race:NightElf"]="As a night elf, Greywhisker brings the Eastern Kingdoms' new alliance to your city. He speaks with scholars outside Elune's temple about the continent's past.",["faction:Alliance"]="As an Alliance member, Greywhisker connects Ironforge's Explorers' League with expeditions across northern Kalimdor."},kw={"agamaggan","chief archaeologist","darkshore","darnassus","explorers' league","greywhisker","ironforge","tarelvir","temple of the moon"},rel={"topic:explorers-league","zone:darnassus","subzone:temple-of-the-moon","zone:darkshore","zone:ironforge","quest:730","quest:729","topic:agamaggan"},src={"Chief Archaeologist Greywhisker"}}
E["npc:elanaria"] = {t="npc",n="Elanaria",z="darnassus",s="Elanaria is a night elf warrior mentor and coordinator stationed on the Warrior's Terrace in Darnassus. She directs developing fighters across Kalimdor, testing their mettle against dangerous threats such as the satyr Vorlus Vilehoof and spiritual entities like the Shade of Elura. Her guidance serves as a crucial bridge for Alliance soldiers honing their martial prowess in the night elven capital.",h="Elanaria is a night elf warrior mentor and coordinator stationed on the Warrior's Terrace in Darnassus.",sec={{t="A Sentinel of the Terrace",b="Standing proudly on the Warrior's Terrace within the boughs of Darnassus, Elanaria serves as an instructor and point of contact for martial champions. In an era where the night elves have formally aligned with the Grand Alliance, her role extends beyond mentoring local Sentinels to preparing warriors of all backgrounds for the harsh challenges facing their lands.",sp=0},{t="Trials of Iron and Spirit",b="Elanaria does not offer easy praise; she expects discipline, resilience, and proven strength. She assigns seasoned adventurers to strike down formidable adversaries plaguing Teldrassil and Darkshore, including the corrupt satyr Vorlus Vilehoof and troubled spirits like the Shade of Elura. She also liaises with skilled craftsmen like Smith Mathiel to ensure that deserving warriors are properly armed for war.",sp=0}},faq={{q="Who is Elanaria?",a="Elanaria is a night elf located on the Warrior's Terrace in Darnassus. She serves as a martial quest giver who tasks rising warriors with combat trials throughout northern Kalimdor.",al={"elanaria darnassus","who is elanaria","elanaria npc"},it="identity"},{q="Where can I find Elanaria?",a="She is located on the Warrior's Terrace, the elevated northern district of Darnassus dedicated to the city's military training grounds and defenses.",al={"elanaria location","where is elanaria","elanaria spot"},it="place",gp=true},{q="What quests does Elanaria offer?",a="Elanaria is a key figure in intermediate warrior progression, offering assignments such as hunting down the satyr Vorlus Vilehoof, confronting the Shade of Elura, and coordinating with local armorers like Smith Mathiel.",al={"elanaria quests","quests from elanaria","elanaria warrior quest"},gp=true},{q="Why does Elanaria send fighters against Vorlus Vilehoof?",a="Vorlus Vilehoof is a dangerous satyr whose demonic corruption threatens the northern wilds. Elanaria tasks capable warriors with slaying him to both safeguard the forests and prove their battlefield prowess.",al={"elanaria vorlus","vorlus vilehoof quest","why kill vorlus vilehoof"},it="target"},{q="Who is Smith Mathiel?",a="Smith Mathiel is a master armorer stationed in Darnassus. Elanaria directs warriors to Mathiel so they may craft or receive specialized martial equipment suitable for frontline combat.",al={"mathiel connection","smith mathiel warrior","elanaria and mathiel"},it="ties"},{q="Does Elanaria interact with non-night elves?",a="Yes. As part of the Alliance, Elanaria assists all eligible Alliance warriors who arrive on the Warrior's Terrace seeking guidance and specialized training.",al={"can humans talk to elanaria","alliance warrior elanaria"},gp=true},{q="Whose side is Elanaria on?",a="Elanaria stands firmly with the night elves of Darnassus and the wider Alliance. Residing in the capital's Warrior's Terrace, she serves her people by guiding and directing capable warriors to defend their lands against looming threats.",al={"elanaria faction","who does elanaria serve","elanaria allegiance"},it="side",add="de8f39db"},{q="What does Elanaria want?",a="Elanaria seeks seasoned fighters willing to protect Kalimdor and purge corrupting evils. She dispatches brave warriors to strike down dangerous foes, including the satyr Vorlus Vilehoof, and directs promising recruits to skilled artisans like Smith Mathiel to ensure they are properly equipped for battle.",al={"what does elanaria need","elanaria purpose","elanaria motive"},it="wants",add="d7c0e558"},{q="Why is Elanaria in Darnassus?",a="Elanaria is stationed at the Warrior's Terrace in Darnassus to act as a mentor and coordinator for fighters within the night elf capital. From this martial hub, she can easily assess the strength of visiting adventurers and dispatch them where their blades are needed most.",al={"why is elanaria here","why is elanaria in warriors terrace","elanaria location reason"},it="why_here",add="16a563e6"}},ang={["class:Warrior"]="Elanaria is an essential contact on the Warrior's Terrace, assigning level-appropriate martial trials that reward sturdy equipment and refine tactical combat skills.",["race:NightElf"]="Representing the martial traditions of Darnassus, Elanaria works to purge corrupted entities like satyrs and restless shades from the ancestral lands of the kaldorei.",["faction:Alliance"]="From the capital of Teldrassil, Elanaria helps maintain military readiness and arms soldiers who defend Alliance interests across northern Kalimdor."},kw={"darnassus","elanaria","shade of elura","smith mathiel","teldrassil","vorlus vilehoof","warrior quests","warrior's terrace"},rel={"subzone:warrior-s-terrace","zone:darnassus","quest:1683","quest:1686","quest:1692","quest:1703","quest:940","topic:night-elf"},src={"Elanaria"}}
E["npc:lelanai"] = {t="npc",n="Lelanai",z="darnassus",s="In Darnassus, Lelanai cares for the night elves’ saber mounts in the Cenarion Enclave. She offers nightsabers and swift war beasts to her kin and trusted allies of the city.",h="In Darnassus, Lelanai cares for the night elves’ saber mounts in the Cenarion Enclave.",sec={{t="Breeder of the Cenarion Enclave",b="Lelanai tends the great cats of Kalimdor in the Cenarion Enclave, beside riding instructor Jartsam. Night elves have long bonded with the fierce predators of northern forests. They train nightsabers and frostsabers to carry sentinels and scouts across rugged ground with a predator’s grace. In the capital, Lelanai provides these mounts to riders.",sp=0},{t="Bonds Beyond Kinship",b="Lelanai offers saber mounts to night elves with the proper skill, while outsiders face a higher bar. The cats are sacred to the kaldorei, who keep their distance from strangers. She entrusts a mount to a non-night elf only when they have earned the highest respect and renown with Darnassus.",sp=0}},faq={{q="Where can I find Lelanai?",a="Lelanai is in the Cenarion Enclave in Darnassus, beside Jartsam, the tiger riding trainer.",al={"lelanai location","where is lelanai","lelanai map"},it="place",gp=true},{q="What does Lelanai sell?",a="Lelanai sells reins for several breeds of frostsaber and nightsaber, including swift armored mounts for veteran riders.",al={"lelanai wares","what mounts does she have","night elf mounts"},it="item",gp=true},{q="Can non-night elves buy mounts from Lelanai?",a="Yes. Non-night elves can buy from Lelanai after earning exalted reputation with Darnassus. Without it, she refuses to sell them a mount.",al={"can humans buy sabers","can dwarfs ride nightsabers","reputation required for sabers"},gp=true},{q="Can Horde players interact with Lelanai?",a="No. Lelanai is loyal to the Alliance in Darnassus. She and the nearby enclave guards treat Horde members as hostile invaders.",al={"can horde buy sabers","is lelanai friendly to horde"},gp=true},{q="Who is Lelanai?",a="Lelanai is a night elf mount breeder and vendor residing in Darnassus. Stationed in the lush Cenarion Enclave, she tends to the majestic sabers bred for the kaldorei and offers them to trusted champions capable of handling these fierce feline predators.",al={"who is lelanai","lelanai identity","lelanai lore"},it="identity",add="8575cac4"},{q="Whose side is Lelanai on?",a="Lelanai is loyal to Darnassus and the greater Alliance. She freely entrusts her trained sabers to her fellow night elves, though she will only consider offering them to other Alliance members if they have earned the highest renown and trust among her people.",al={"lelanai faction","is lelanai alliance","who does lelanai serve"},it="side",add="4b3049f5"},{q="Why is Lelanai here in Darnassus?",a="She makes her home in the Cenarion Enclave of Darnassus alongside Jartsam, the riding trainer. There, amidst the tranquil boughs of Teldrassil, she raises and cares for the frostsaber and nightsaber mounts essential to kaldorei sentinels and travelers.",al={"why is lelanai in darnassus","lelanai cenarion enclave purpose","why is lelanai here"},it="why_here",add="18fb2d04"},{q="What does Lelanai want?",a="Lelanai seeks to ensure that her prized nightsabers and frostsaber mounts find worthy riders. She insists that anyone who wishes to ride one of her beasts possesses proper training and shows true dedication and reverence toward Darnassus.",al={"what does lelanai want","lelanai goal","lelanai motivation"},it="wants",add="14c3da8f"},{q="Who is Lelanai tied to?",a="Lelanai works closely with Jartsam, the night elf riding instructor in the Cenarion Enclave. While Jartsam teaches aspiring riders the delicate art of tiger riding, Lelanai provides the bonded sabers ready to carry them across Kalimdor.",al={"lelanai ties","who does lelanai work with","lelanai jartsam"},it="ties",add="ec77c23e"}},ang={["race:NightElf"]="As a night elf, you can seek Lelanai when you are ready to ride your people’s traditional feline steeds.",["faction:Alliance"]="As an Alliance hero, you can earn exalted standing with Darnassus and seek Lelanai’s sabers to ride beside your kaldorei allies."},kw={"cenarion enclave","darnassus","frostsaber","jartsam","lelanai","mount vendor","nightsaber"},rel={"zone:darnassus","subzone:cenarion-enclave","topic:night-elf"},src={"Lelanai"}}
E["npc:malfurion-stormrage"] = {t="npc",n="Malfurion Stormrage",z="darnassus",s="Malfurion Stormrage lies in a coma within the Emerald Dream, beyond the reach of his people. The first mortal druid and revered leader of the night elves beside High Priestess Tyrande Whisperwind, he helped defeat the Burning Legion in the War of the Ancients and the Third War. The kaldorei honor him as Shan'do, or honored teacher, and await his waking guidance.",h="Malfurion Stormrage lies in a coma within the Emerald Dream, beyond the reach of his people.",sec={{t="The First Druid",b="Malfurion Stormrage turned from the arcane to nature ten thousand years ago. Before the Great Sundering broke ancient Kalimdor, he studied under the demigod Cenarius. As Queen Azshara and her Highborne delved into the Well of Eternity's arcane power, Malfurion became Azeroth's first mortal druid. His fears proved true when Azshara's sorcery tore open a way for Sargeras and the Burning Legion, beginning the War of the Ancients.",sp=0},{t="Savior of Kalimdor",b="Malfurion Stormrage helped drive the demons back and close the portal above the Well of Eternity. He fought beside Cenarius, Tyrande Whisperwind, and his twin brother Illidan. After the world shattered, Malfurion led the druids into the Emerald Dream to rebuild and protect Azeroth's living world. Ten thousand years later, Tyrande woke him to face Archimonde in the Third War. At Mount Hyjal, he rallied the forest spirits and shattered the Burning Legion once more.",sp=0},{t="Lost to the Dream",b="Malfurion Stormrage returned to sleep in Moonglade after the Third War, seeking the Emerald Dream and strength for his spent power. His spirit never returned to his body, leaving him in an unnatural coma. In Darnassus, Archdruid Fandral Staghelm carries the Cenarion Circle's duties of leadership. Tyrande and the sisterhood watch for their Shan'do to wake.",sp=0}},faq={{q="Where is Malfurion Stormrage right now?",a="Malfurion Stormrage lies asleep in Moonglade's barrow dens, while his consciousness remains deep in the Emerald Dream. His body is comatose and inaccessible to most adventurers.",al={"where is malfurion","where to find malfurion","malfurion location","is malfurion in game"},it="place"},{q="Why is Malfurion asleep?",a="Druids hibernate in the Emerald Dream to commune with nature, sustain the world's flora and fauna, and restore their spiritual strength. After the immense magical strain of defeating Archimonde at Mount Hyjal, Malfurion entered the Dream to recover, but an unnatural malaise severed his spirit from his body.",al={"why is malfurion sleeping","why is he comatose","what happened to malfurion"},it="motive"},{q="Who rules the night elves while Malfurion sleeps?",a="High Priestess Tyrande Whisperwind rules the kaldorei from the Temple of the Moon in Darnassus, leading the Sentinels and the Sisterhood of Elune. Archdruid Fandral Staghelm oversees the Cenarion Circle and druidic affairs.",al={"who leads night elves","who is the night elf leader","night elf ruler"},it="leader"},{q="What does 'Shan'do' mean?",a="In Darnassian, Shan'do means honored teacher. It is a title of deep reverence for master druids, especially Malfurion Stormrage, who first brought druidism to mortals under Cenarius's tutelage.",al={"shando meaning","what is shando","shan'do"},it="name"},{q="Who is Malfurion's brother?",a="Malfurion's twin brother is Illidan Stormrage. They shared their youth in Suramar, but Illidan's obsession with arcane magic and pursuit of demonic power drove a bitter rift between them during the War of the Ancients. Malfurion imprisoned him for millennia.",al={"malfurion brother","who is illidan to malfurion","stormrage brothers"},it="ties"},{q="What did Malfurion do at the Battle of Mount Hyjal?",a="At the climax of the Third War, Malfurion blew the Horn of Cenarius at the World Tree Nordrassil and summoned thousands of ancestral forest spirits, called wisps. They swarmed Archimonde and detonated, destroying the demon and immolating the World Tree to save Kalimdor.",al={"malfurion hyjal","battle of mount hyjal malfurion","how did malfurion defeat archimonde"},it="fame"},{q="Who is Malfurion Stormrage?",a="Malfurion Stormrage is the first mortal druid on Azeroth and the supreme archdruid of the night elves. Trained ten thousand years ago by the demigod Cenarius, he guided his people through the cataclysmic War of the Ancients against Queen Azshara and the Burning Legion. Alongside his beloved, High Priestess Tyrande Whisperwind, he has led the kaldorei for millennia, serving as both their spiritual guide and greatest defender of the natural world.",al={"who is malfurion","who is furion","malfurion stormrage lore"},it="identity",add="65d9a7b2"},{q="Whose side is Malfurion Stormrage on?",a="Malfurion stands foremost with his people, the kaldorei, and the Cenarion Circle dedicated to preserving Azeroth's natural order. Through the night elves' recent pacts, his people stand aligned with the Grand Alliance, though Malfurion's ultimate devotion transcends petty political squabbles—his lifelong duty is to protect the balance of nature and safeguard the Emerald Dream from corruption.",al={"malfurion faction","is malfurion alliance","what faction is malfurion"},it="side",add="af86ea6f"},{q="What does Malfurion Stormrage want?",a="Above all else, Malfurion seeks to protect Azeroth's delicate natural balance and keep the Emerald Dream safe from dark forces. Having sacrificed so much across ten thousand years to heal the scarred earth and vanquish demonic incursions, his life is bound to safeguarding the wilderness, tending the World Tree, and guiding the night elves along a path harmonious with nature.",al={"malfurion goal","what are malfurions goals","malfurion purpose"},it="wants",add="1592db0d"}},ang={["class:Druid"]="As a druid, your teachings trace back to Malfurion, who learned directly from Cenarius. His absence in the Emerald Dream weighs on the Cenarion Circle.",["race:NightElf"]="As a night elf, you revere Malfurion as your people's ancient protector and savior. While he sleeps, Tyrande and Archdruid Fandral Staghelm govern.",["class:Priest"]="As a priest, you know Malfurion as the beloved partner of High Priestess Tyrande Whisperwind, joining devotion to Elune with nature's sacred guardianship."},kw={"archdruid","cenarius","emerald dream","furion","hyjal","illidan","malfurion","shan'do","stormrage","tyrande"},rel={"npc:tyrande-whisperwind","topic:cenarius","topic:emerald-dream","topic:shan-do","topic:druid","topic:war-of-the-ancients","topic:third-war","topic:burning-legion"},src={"Malfurion Stormrage"}}
E["npc:mathrengyl-bearwalker"] = {t="npc",n="Mathrengyl Bearwalker",z="darnassus",s="In Darnassus, Mathrengyl Bearwalker guides Alliance druids from the Cenarion Enclave. Once Fandral Staghelm's direct assistant, he helps young druids face spiritual trials, learn shapeshifting, and serve across Kalimdor.",h="In Darnassus, Mathrengyl Bearwalker guides Alliance druids from the Cenarion Enclave.",sec={{t="Mentor of the Cenarion Enclave",b="In Darnassus's Cenarion Enclave, Mathrengyl Bearwalker guides Alliance druids through their first rites. A respected elder of the Cenarion Circle, he sends initiates to commune with Moonglade and judges whether they are ready to take animal forms. Mathrengyl remembers his own bewildering communion with the Great Bear Spirit. He asks each initiate to test their spirit against Lunaclaw, the sacred moonkin, before entering the path of the Druid of the Claw.",sp=0},{t="Service to the Archdruid",b="For many years, Mathrengyl has served as Fandral Staghelm's second, tending the Cenarion Circle's daily affairs and finding recruits for the Archdruid's plans. When Fandral sought great stores of morrowgrain, Mathrengyl arranged for returning adventurers to gather it. In private, he admitted unease about the plant's unnatural essence. He also coordinates Alliance responses to calls from Moonglade and handles the Circle's delicate politics while Fandral turns his attention to southern Kalimdor.",sp=0},{t="A Broader Perspective",b="Mathrengyl thinks more openly than Fandral Staghelm, whose pride and disdain for other races are well known. Relics from Mulgris Deepriver reached Darnassus after the druid died fighting the Scourge in the Western Plaguelands. Mathrengyl was moved to learn that the investigator was a tauren. The Cenarion Circle shares a mission, he reflected, and tauren may not have strayed as far from Cenarius's teachings as Fandral claims.",sp=0}},faq={{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker guides druids in the Cenarion Enclave in Darnassus. A veteran night elf druid and respected elder, he teaches shapeshifting, poison cleansing, and service to the Cenarion Circle.",al={"who is mathrengyl","mathrengyl role","bearwalker"},it="identity"},{q="What is his relationship with Fandral Staghelm?",a="Mathrengyl served as Fandral Staghelm's direct assistant and second. He manages Fandral's requests, including gathering morrowgrain and delegating missions, while quietly doubting some of the Archdruid's views and projects.",al={"fandral assistant","staghelm and mathrengyl"},it="ties"},{q="What forms does Mathrengyl help druids learn?",a="Mathrengyl guides young druids through their Moonglade pilgrimage and communion with Lunaclaw to earn Bear Form. He also oversees their trials in Darkshore and Westfall to master Aquatic Form.",al={"bear form quest darnassus","aquatic form quest darnassus","druid forms mathrengyl"},gp=true},{q="Why is Mathrengyl gathering morrowgrain?",a="Mathrengyl gathers morrowgrain cultivated by adventurers to help Archdruid Fandral Staghelm with botanical research on Teldrassil. He has admitted to feeling uneasy in the plant's presence.",al={"morrowgrain quest","why morrowgrain darnassus"},it="wants"},{q="How does Mathrengyl feel about tauren druids?",a="Mathrengyl considers tauren druids more thoughtfully than Fandral Staghelm, who views them with skepticism. After considering a tauren druid's sacrifice against the Scourge in the Western Plaguelands, Mathrengyl said tauren may follow Cenarius's teachings more closely than Fandral allows.",al={"tauren druids","mathrengyl tauren"}},{q="What does he do with the Nightmare Shard?",a="When adventurers bring a corrupted Nightmare Shard to Falla Sagewind, she sends them to Mathrengyl. He examines the shard with alarm and senses corruption creeping toward the Emerald Dream.",al={"nightmare shard mathrengyl","in nightmares quest"}},{q="Whose side is Mathrengyl Bearwalker on?",a="Mathrengyl is loyal to the Cenarion Circle and the night elves of Darnassus. As a prominent druid of the Claw residing within the Cenarion Enclave, he serves both the Kaldorei and the broader druidic order, striving to uphold the balance of nature across Kalimdor.",al={"mathrengyl faction","who does mathrengyl serve","is mathrengyl alliance"},it="side",add="d00fa4f6"},{q="Why is Mathrengyl Bearwalker in Darnassus?",a="Mathrengyl resides in the Cenarion Enclave to guide and instruct young night elf druids in their sacred duties. Standing at the heart of Kaldorei society on Teldrassil, he helps initiates learn animal forms, connect with the spirits of the wild, and address natural crises threatening the realm.",al={"why is mathrengyl here","mathrengyl darnassus reason","what brings mathrengyl to darnassus"},it="why_here",add="88f66b3d"}},ang={["class:Druid"]="As an Alliance druid, you can turn to Mathrengyl for guidance between Darnassus and Moonglade. He teaches Bear Form, Aquatic Form, and herbal cures for deadly poisons.",["faction:Alliance"]="In Darnassus, Mathrengyl offers the Cenarion Circle's steady, traditional leadership. His temperate manner contrasts with Fandral Staghelm's aggressive posturing.",["race:NightElf"]="As a night elf, you can look to Mathrengyl as an example of Kaldorei devotion to nature and balance after the Third War, as Teldrassil grows."},kw={"aquatic form","bear form","bearwalker","cenarion circle","cenarion enclave","darnassus","druid of the claw","druid trainer","fandral staghelm","mathrengyl bearwalker","morrowgrain","teldrassil"},rel={"npc:fandral-staghelm","subzone:cenarion-enclave","zone:darnassus","npc:dendrite-starblaze","quest:6001","quest:31","quest:3369","topic:cenarion-circle"},src={"Mathrengyl Bearwalker"}}
E["npc:mydrannul"] = {t="npc",n="Mydrannul",z="darnassus",s="At the Warrior's Terrace in Darnassus, Mydrannul keeps basic supplies ready for sentinels, soldiers, and visitors.",h="At the Warrior's Terrace in Darnassus, Mydrannul keeps basic supplies ready for sentinels, soldiers, and...",sec={{t="Supplies of the Warrior's Terrace",b="Mydrannul keeps a supply stall among the Warrior's Terrace military pavilions and training grounds. Darnassus's defenders and travelers can find everyday field gear there, including ammunition for archers and gunners, throwing blades, flint, pouches, and simple rations. His stall helps sentinels and trainees preparing for duty on Teldrassil find the basic sundries they need.",sp=0}},faq={{q="Where can Mydrannul be found?",a="Mydrannul can be found in the Warrior's Terrace, Darnassus's southeastern martial district on the crown of Teldrassil.",al={"mydrannul location","where is mydrannul","mydrannul map"},it="place",gp=true},{q="What goods does Mydrannul sell?",a="Mydrannul sells containers, simple rations, drink, flint and tinder, throwing weapons, arrows, and bullets.",al={"mydrannul wares","what does mydrannul sell","mydrannul vendor items"},it="item",gp=true},{q="Does Mydrannul offer any quests?",a="Yes. Mydrannul sends adventurers to his friend Nessa Shadowsong, a fishing merchant in Rut'theran Village, who needs a parcel carried to Darkshore.",al={"mydrannul quest","quests from mydrannul"},gp=true},{q="Who is Mydrannul?",a="Mydrannul is a night elf merchant residing in Darnassus, found operating within the Warrior's Terrace. He serves as a general goods vendor for the night elven capital, supplying travelers, locals, and soldiers alike with vital everyday wares, provisions, and ammunition.",al={"who is mydrannul","mydrannul identity","mydrannul darnassus"},it="identity",add="cca0dfd1"},{q="Whose side is Mydrannul on?",a="Mydrannul stands firmly loyal to Darnassus and the Alliance. As a night elf dwelling in the heart of their sacred world tree, he gladly serves his kin and any Alliance adventurer passing through the city.",al={"mydrannul faction","mydrannul allegiance","is mydrannul alliance"},it="side",add="34e3a734"},{q="Why is Mydrannul here?",a="Stationed within Darnassus's Warrior's Terrace, Mydrannul maintains a shop to equip those preparing for patrol or distant travel. His presence ensures that defenders and wayfarers have ready access to necessary supplies right near the city's training grounds.",al={"why is mydrannul here","mydrannul purpose darnassus","what does mydrannul do here"},it="why_here",add="6cf1b6fe"},{q="What does Mydrannul want?",a="Mydrannul seeks honest commerce, providing reliable sundries, sustenance, and munitions to anyone in Darnassus willing to trade with him.",al={"what does mydrannul want","mydrannul goals","mydrannul motive"},it="wants",add="a5485425"}},ang={["race:NightElf"]="As a night elf training in Darnassus, you can find everyday equipment and arrows from Mydrannul to keep Sentinels supplied.",["faction:Alliance"]="As an Alliance traveler arriving on Teldrassil, you can rely on vendors like Mydrannul in the Warrior's Terrace for basic packs, ammunition, and field rations."},kw={"ammunition","darnassus","general goods","mydrannul","teldrassil","vendor","warrior's terrace"},rel={"zone:darnassus","subzone:warrior-s-terrace","quest:6344","topic:night-elf"},src={"Mydrannul"}}
E["npc:priestess-a-moora"] = {t="npc",n="Priestess A'moora",z="darnassus",s="Priestess A'moora is a devout night elf servant of the Moon Goddess residing within the Temple of the Moon in Darnassus. Working closely under the guidance of High Priestess Tyrande Whisperwind's priesthood, she attends to rituals of spiritual purification and communion with Elune. Travelers exploring Teldrassil are often directed to her when matters involve sacred offerings and the mystical wildlife of the boughs.",h="Priestess A'moora is a devout night elf servant of the Moon Goddess residing within the Temple of the Moon in...",sec={{t="A Servant of Elune",b="Within the serene marble halls of the Temple of the Moon, Priestess A'moora spends her days in contemplation and service. As an ordained priestess of Elune, she assists in tending the spiritual needs of Darnassus and preserving the delicate rituals passed down through millennia. While much of the Sisterhood oversees military defenses or diplomacy, A'moora focuses on traditional devotions and sacred matters concerning the natural spirits of Teldrassil.",sp=0},{t="Tears of the Moon",b="A'moora is tied to the sad fate of Lady Sathrah, a great spider once beloved of Elune whose silvery dew was kept in the temple for its healing powers. When Sathrah descended into madness, A'moora sent young adventurers to the northern borders of Teldrassil near Wellspring Lake to end her suffering and bring back her silvery spinnerets. Offered at the temple's fountain, the spinnerets become a sacrifice to Elune so that Sathrah might be reborn at peace.",sp=0}},faq={{q="Where can I find Priestess A'moora?",a="Priestess A'moora is located inside the Temple of the Moon in Darnassus, the capital city resting in the canopy of Teldrassil. She stands among the priestesses serving the altar of Elune.",al={"a'moora location","where is priestess amoora","amoora darnassus"},it="place",gp=true},{q="What is Priestess A'moora's role in Darnassus?",a="She is a member of the Sisterhood of Elune who oversees specific religious ceremonies and sacred offerings. She acts as a quest giver and guide for travelers seeking to perform ancient rites of cleansing and sacrifice on Teldrassil.",al={"what does amoora do","priestess amoora purpose"},it="purpose"},{q="What quests does Priestess A'moora offer?",a="She gives the Tears of the Moon quest chain, sending adventurers to slay the maddened spider Lady Sathrah near Wellspring Lake and then offer her silvery spinnerets as a sacrifice at the temple's fountain.",al={"amoora quests","priestess amoora questline"},gp=true},{q="How is Priestess A'moora related to the Temple of the Moon?",a="She is an active attendant in the Temple of the Moon, the spiritual heart of night elf culture ruled by High Priestess Tyrande Whisperwind. A'moora facilitates the spiritual instruction and ritual duties conducted under the temple's roof.",al={"is amoora a temple priestess","sisterhood of elune amoora"},it="ties"},{q="Who is Sathrah, and why does A'moora speak of her?",a="Lady Sathrah is a great spider once beloved of Elune, who dwells along Teldrassil's northern borders near Wellspring Lake. She has descended into madness, so A'moora asks adventurers to end her suffering and offer her spinnerets to Elune so she may be reborn at peace.",al={"sathrah sacrifice","who is sathrah"}},{q="Does A'moora belong to the Alliance?",a="Yes. As a night elf priestess stationed within the capital city of Darnassus, she is fully aligned with the Alliance and will not offer assistance or quests to members of the Horde.",al={"is amoora alliance","can horde talk to amoora"},it="side"},{q="Who is Priestess A'moora?",a="Priestess A'moora is a devout night elf servant of Elune stationed within the grand Temple of the Moon in Darnassus. As one of the temple's dedicated priestesses, she ministers to the spiritual needs of her people, offering prayers, counsel, and guidance under the grace of the Moon Goddess.",al={"who is priestess amoora","who is a'moora","priestess amoora lore"},it="identity",add="05fd0978"},{q="What does Priestess A'moora want?",a="Priestess A'moora seeks to preserve the sacred rituals and sanctity of the Temple of the Moon. She looks to worthy adventurers to aid her in matters of faith and ritual, calling upon you to assist with sacred offerings such as the Tears of the Moon to honor Elune and sustain the temple's holy rites.",al={"priestess amoora goal","what does amoora want","amoora motive"},it="wants",add="4daa0bfc"},{q="Why is Priestess A'moora in Darnassus?",a="A'moora resides in the Temple of the Moon because it stands as the heart of Elune's worship for the night elven people. She tends to the sanctuary's daily devotionals, assists High Priestess Tyrande Whisperwind's priesthood, and ensures the spiritual harmony of the capital remains untarnished.",al={"why is amoora in darnassus","priestess amoora temple of the moon","why is amoora here"},it="why_here",add="e929c23e"}},ang={["race:NightElf"]="For night elves, Priestess A'moora represents the timeless traditions of Elune worship, anchoring the young boughs of Teldrassil to the ancient spiritual heritage of their people.",["class:Priest"]="Priests walking the halls of the Temple of the Moon can see in A'moora an example of dedicated devotion, bridging the gap between temple ritual and the natural world outside the city gates.",["faction:Alliance"]="Priestess A'moora assists Alliance travelers exploring the holy heart of Darnassus, introducing them to the Sisterhood of Elune's sacred customs."},kw={"a'moora","darnassus","elune","priestess","sathrah","tears of the moon","teldrassil","temple of the moon"},rel={"subzone:temple-of-the-moon","quest:2518","quest:2519","quest:2520","zone:darnassus","subzone:oracle-glade","quest:940","topic:night-elf"},src={"Priestess A'moora"}}
E["npc:priestess-alathea"] = {t="npc",n="Priestess Alathea",z="darnassus",s="Within Darnassus, Priestess Alathea guides night elf priests in the Temple of the Moon. Devoted to Elune, she teaches sacred rites and helps acolytes prepare for healing, protection, and celestial magic.",h="Within Darnassus, Priestess Alathea guides night elf priests in the Temple of the Moon.",sec={{t="Devotion in the Temple of the Moon",b="Priestess Alathea teaches and guides the Sisterhood of Elune within Darnassus's Temple of the Moon. After leaving Shadowglen, night elf initiates come to the temple to deepen their bond with the Goddess. Alathea shares sacred knowledge with those who devote themselves to healing, protection, and divine light.",sp=0},{t="Blessings of the White Lady",b="Night elf priests draw on Elune's grace, while human and dwarven priests follow the traditions of the Holy Light. Alathea teaches night elf blessings such as Stars of Elune and Elune's Grace. Under her guidance, acolytes learn to shape starlight into swift, protective shields against the dangers facing Kalimdor.",sp=0}},faq={{q="Who is Priestess Alathea?",a="Priestess Alathea trains kaldorei priests in the Temple of the Moon in Darnassus, guiding acolytes through their sacred trials.",al={"who is alathea","alathea darnassus","alathea priest trainer"},it="identity"},{q="What abilities does she teach?",a="Alathea teaches standard priest spells and night elf trials, including Starshards and Elune's Grace, which channel the Moon Goddess's power and protection.",al={"alathea abilities","alathea spells","priest spells darnassus"},gp=true},{q="Where can I find Priestess Alathea?",a="Priestess Alathea is on the ground floor of the Temple of the Moon in southern Darnassus, among the sanctuary's luminous waters and fellow priestesses.",al={"where is alathea","alathea location"},gp=true},{q="Why do night elf priests visit her specifically?",a="As kaldorei priests advance, novice instructors across Teldrassil send them to Alathea for rites such as Stars of Elune and Elune's Grace, marking their passage into mature service to the goddess.",al={"priest quests alathea","stars of elune quest"},it="purpose"},{q="Does she train races other than night elves?",a="Yes. Any Alliance priest visiting Darnassus can learn general spells from Alathea, though she gives kaldorei racial trials only to night elves. Human and dwarven priests belong to the Church of the Holy Light.",al={"can humans train with alathea","alathea dwarf priest"},gp=true},{q="How does her faith differ from human and dwarven priests?",a="Priests in Stormwind and Ironforge invoke the Holy Light, while Alathea and her sisters worship Elune as a living deity. They wield starlight and moonlit wards alongside curative magic.",al={"elune vs holy light","night elf priest lore"}},{q="Whose side is Priestess Alathea on?",a="Priestess Alathea stands firmly with the Sisterhood of Elune, the night elf people, and the Grand Alliance. She serves High Priestess Tyrande Whisperwind within the sacred Temple of the Moon, dedicating herself entirely to the service of Elune and the guidance of faithful night elves.",al={"priestess alathea faction","alathea alliance","who does alathea serve"},it="side",add="d359d229"},{q="Why is Priestess Alathea in the Temple of the Moon?",a="Alathea resides in Darnassus to train and mentor nascent night elf priests. As a dedicated servant of Elune stationed within the capital's grandest sanctuary, she instructs novices in weaving the Moon Goddess's blessing into warding prayers and martial starfire.",al={"why is priestess alathea here","alathea location darnassus","what does alathea do here"},it="why_here",add="58a787d3"},{q="What does Priestess Alathea want?",a="Alathea seeks to foster spiritual devotion among night elf initiates and strengthen their connection to Elune. She wants young priests to carry the Moon Goddess's wisdom, grace, and martial light across Kalimdor to protect their ancestral lands.",al={"alathea goals","what is alathea seeking","priestess alathea purpose"},it="wants",add="f062e3c8"},{q="Who is Priestess Alathea tied to?",a="She is directly tied to the Sisterhood of Elune and serves under High Priestess Tyrande Whisperwind. Stationed among the senior priestesses in Darnassus, she coordinates training with other acolytes throughout the Temple of the Moon.",al={"priestess alathea connections","alathea relationships","who does alathea work with"},it="ties",add="a22ea658"}},ang={["class:Priest"]="As an Alliance priest in Darnassus, you can turn to Priestess Alathea for rank advancements and guidance in kaldorei celestial powers.",["race:NightElf"]="As a night elf, you find the Sisterhood of Elune's living traditions in Priestess Alathea, within Darnassus.",["faction:Alliance"]="As an Alliance member who studies the clerical arts, you can learn at the Temple of the Moon from Priestess Alathea."},kw={"alathea","darnassus","elune","elune's grace","priest trainer","priestess alathea","stars of elune","temple of the moon"},rel={"subzone:temple-of-the-moon","quest:2519","quest:5627","quest:5672","topic:elune","zone:darnassus","topic:night-elf","quest:940"},src={"Priestess Alathea"}}
E["npc:renzik-the-shiv"] = {t="npc",n="Renzik \"The Shiv\"",z="darnassus",s="In Stormwind's Old Town, Renzik \"The Shiv\" directs SI:7's new rogue recruits. The goblin is Spymaster Mathias Shaw's trusted second-in-command, receiving promising agents sent from across the Alliance.",h="In Stormwind's Old Town, Renzik \"The Shiv\" directs SI:7's new rogue recruits.",sec={{t="A Goblin in SI:7",b="Renzik keeps his past to himself. In Stormwind, he is known as a goblin who rose to become Spymaster Mathias Shaw's second-in-command in SI:7. He has little patience for pleasantries. When new recruits arrive, he asks whether they are ready to work or need a nap first.",sp=0},{t="Right Hand of Mathias Shaw",b="Renzik works inside SI:7's secretive fortress in Old Town, second-in-command to Mathias Shaw. Rogue mentors across the Alliance, from Ironforge to Darnassus, send their most promising agents to him. He sends them to field instructors such as Lucius in Redridge, where they can hone the skills needed to survive in the field.",sp=0}},faq={{q="Why is a goblin working for Stormwind's SI:7?",a="Renzik keeps the story of how he came to Stormwind to himself. The goblin has risen to become Mathias Shaw's second-in-command at SI:7.",al={"why is renzik alliance","goblin in stormwind","why is there a goblin in si7"},it="side"},{q="Why is he called 'The Shiv'?",a="Renzik has never told Stormwind how he got his nickname. In Old Town, the name is all anyone gets, and for a spy that may be the point.",al={"why the shiv","renzik nickname","renzik the shiv meaning"},it="name"},{q="What does Renzik do for player rogues?",a="When Alliance rogues prove their skill, their trainers send them to Renzik in Stormwind. He handles their entry into SI:7 and sends recruits to instructors such as Lucius in the Redridge Mountains to learn how to survive in the field.",al={"renzik rogue quest","what does renzik give","talk to renzik the shiv"},it="purpose",gp=true},{q="Where does Renzik usually operate?",a="Renzik is stationed inside SI:7 headquarters in Old Town, Stormwind City, where Alliance rogue recruits report to him.",al={"renzik location","where to find renzik","where is renzik"},it="place"},{q="Does Renzik maintain ties outside Stormwind?",a="Yes. Rogue trainers in Ironforge and Darnassus send promising students to Renzik, who passes recruits on to Lucius, an SI:7 associate in Lakeshire in the Redridge Mountains.",al={"renzik network","renzik connections","renzik allies"},it="ties"},{q="Who is Renzik \"The Shiv\"?",a="Renzik \"The Shiv\" is a goblin operative and the second-in-command of Stormwind's intelligence service, SI:7, serving directly under Master Mathias Shaw. He keeps the story of his past to himself; what Stormwind knows is that he vets the promising rogues sent to him from across the Alliance and passes them on for field training.",al={"who is the shiv","who is renzik the shiv","who is renzik"},it="identity",add="4d248edd"},{q="What does Renzik \"The Shiv\" want?",a="Renzik wants recruits who can work and survive. As Mathias Shaw's second in command at SI:7, he sizes up the rogues sent to him and passes the promising ones on to Lucius in Lakeshire for field training, rather than sending them out to die.",al={"renzik goal","what does renzik want","renzik motivation"},it="wants",add="68226031"},{q="Why is Renzik \"The Shiv\" here?",a="Although Renzik is based out of the SI:7 headquarters in Stormwind's Old Town, his intelligence duties require maintaining working connections with operatives across the Alliance, including the shadowy rogue circles of Darnassus and Ironforge's Hidden Circle. He liaises between distant cells to ensure covert communications and tradecraft remain tightly coordinated.",al={"why is renzik here","why is renzik in darnassus","renzik darnassus reason"},it="why_here",add="0d7f210c"},{q="Why is Renzik \"The Shiv\" famous or feared?",a="Renzik is known as Mathias Shaw's second in command at SI:7, a rare goblin in the kingdom's service. He keeps the story behind his nickname to himself.",al={"why is renzik feared","why is renzik famous","renzik the shiv reputation"},it="fame",add="0f5f7694"}},ang={["class:Rogue"]="As an Alliance rogue, you pass through Renzik's hands on your way from street-level knifework into SI:7. He sends recruits to Lucius in Redridge to learn fieldcraft and survive.",["faction:Alliance"]="Though he is a goblin, Renzik is one of Stormwind's most capable intelligence officers, second only to Mathias Shaw within SI:7.",["race:Human"]="Beside Spymaster Shaw in Old Town, Renzik is a rare goblin in the kingdom's military elite. His place there shows that loyalty and skill matter in the shadow wars."},kw={"goblin","lucius","mathias shaw","old town","renzik","rogue","si:7","stormwind","the shiv"},rel={"npc:mathias-shaw","quest:2300","quest:2260","subzone:old-town","zone:stormwind","npc:lucius","topic:goblin","topic:alliance"},src={"Renzik \"The Shiv\""}}
E["npc:saelienne"] = {t="npc",n="Saelienne",z="darnassus",s="On the Craftsmen's Terrace in Darnassus, Saelienne keeps an inn for travelers and artisans. She offers food, drink, and a place to bind a Hearthstone in the night elven capital.",h="On the Craftsmen's Terrace in Darnassus, Saelienne keeps an inn for travelers and artisans.",sec={{t="Hospitality on the Terrace",b="Innkeeper Saelienne welcomes residents and visitors to her inn on Darnassus's Craftsmen's Terrace. She gives travelers a calm place to rest and serves night elven refreshments and goods brought through the city port. Tradesfolk come in after long hours at the forge or loom. Saelienne's inn gives them a place to gather and recover.",sp=0}},faq={{q="Where can I find Innkeeper Saelienne?",a="You can find Saelienne on the Craftsmen's Terrace in Darnassus, among the trade trainers and crafting shops.",al={"saelienne location","where is saelienne","darnassus innkeeper location","craftsmens terrace inn"},it="place",gp=true},{q="What services does Saelienne provide?",a="Saelienne offers food and drink, and lets you bind your Hearthstone to Darnassus.",al={"what does saelienne do","saelienne vendor","bind hearthstone darnassus"},it="purpose",gp=true},{q="Does Saelienne offer any seasonal tasks?",a="During Hallow's End, Saelienne offers Alliance adventurers Dancing for Marzipan in exchange for holiday treats.",al={"saelienne quests","hallows end saelienne","dancing for marzipan"},gp=true},{q="Who is Saelienne?",a="Saelienne is a night elf innkeeper residing in the Craftsmen's Terrace within Darnassus. She manages hospitality for travelers and locals alike, offering food, refreshing drink, and a restful place to bind your hearthstone beneath the boughs of Teldrassil.",al={"who is saelienne","saelienne identity","innkeeper saelienne"},it="identity",add="023ad64a"},{q="Whose side is Saelienne on?",a="She stands firmly with Darnassus and the greater Alliance. As an innkeeper in the heart of the night elven capital, she welcomes all allied adventurers who arrive on the world tree in need of respite and provisions.",al={"saelienne faction","is saelienne alliance","saelienne loyalty"},it="side",add="bc46f8f9"},{q="What does Saelienne want?",a="Saelienne desires nothing more than to tend her inn and ensure that travelers visiting the Craftsmen's Terrace find shelter, nourishment, and a comfortable bed. Beyond providing hospitality and trade, she stays clear of politics and conflict.",al={"what does saelienne want","saelienne motive","saelienne goals"},it="wants",add="a41cab7b"},{q="Why is Saelienne in Darnassus?",a="She makes her living running the inn in the Craftsmen's Terrace, tending to the artisans, merchants, and voyagers passing through the district. Her post places her right in the bustling heart of Teldrassil's daily commerce.",al={"why is saelienne here","saelienne craftsmen terrace","why is saelienne in darnassus"},it="why_here",add="28654c22"}},ang={["race:NightElf"]="As a night elf adventurer returning from Teldrassil's wild reaches, you can find a familiar hearth among Darnassus's artisans at Saelienne's inn.",["faction:Alliance"]="As an Alliance envoy or tradesfolk traveling to Teldrassil, you can find food, drink, and a warm hearthstone refuge at Saelienne's inn."},kw={"craftsmen's terrace","darnassus","hallow's end","hearthstone","innkeeper","saelienne","teldrassil"},rel={"zone:darnassus","subzone:craftsmen-s-terrace","zone:teldrassil","topic:night-elf","quest:8357","topic:alliance"},src={"Saelienne"}}
E["npc:sister-aquinne"] = {t="npc",n="Sister Aquinne",z="darnassus",s="In Darnassus, Sister Aquinne studies beneath the Priesthood of Elune at the Temple of the Moon. The novice acolyte serves in the Temple Gardens.",h="In Darnassus, Sister Aquinne studies beneath the Priesthood of Elune at the Temple of the Moon.",sec={{t="Acolyte in Darnassus",b="Sister Aquinne studies with the Priesthood of Elune in the night elf capital. She is stationed in the Temple Gardens, beneath the Temple of the Moon, learning from the High Priestess and elder sisters. When a once-great creature of the forest needed help, Aquinne sent willing travelers to Priestess A'moora inside the temple to learn what had to be done.",sp=0}},faq={{q="Where can Sister Aquinne be found?",a="Sister Aquinne can be found in the Temple Gardens of Darnassus, just outside the Temple of the Moon.",al={"aquinne location","where is sister aquinne","sister aquinne coords"},it="place",gp=true},{q="What is Sister Aquinne's background?",a="Sister Aquinne is a novice priestess of Elune, studying at the Temple of the Moon in Darnassus. Little is known of her life before she entered the temple's service.",al={"aquinne lore","who is sister aquinne","aquinne backstory"},it="identity"},{q="Whose side is Sister Aquinne on?",a="Sister Aquinne serves the Sisterhood of Elune and stands firmly with the Darnassus night elves and the broader Alliance. Devoted to the Moon Goddess, she studies peaceably within the Temple Gardens under the guidance of the high priestesses, holding no allegiance beyond her sacred order and her people.",al={"aquinne faction","sister aquinne alliance","who does sister aquinne serve"},it="side",add="f961feee"},{q="What does Sister Aquinne want?",a="Sister Aquinne is focused on her spiritual training as a novice priestess within the Temple of the Moon. When a once-great creature of the forest needs help, she sends willing travelers to Priestess A'moora inside the temple.",al={"sister aquinne goals","what does aquinne want","aquinne motivation"},it="wants",add="5bcdc1db"},{q="Why is Sister Aquinne in Darnassus?",a="Aquinne came to the capital to pursue her calling in the Sisterhood of Elune. She resides by the tranquil pools of the Temple Gardens, where novitiates and priestesses meditate and study the teachings of Elune.",al={"why is sister aquinne here","why is aquinne in darnassus","why did aquinne come to darnassus"},it="why_here",add="119c78e2"}},ang={["class:Priest"]="As a priest, you can recognize Aquinne's devotion as she undertakes the foundational training required of acolytes serving the Temple of the Moon.",["race:NightElf"]="As a night elf arriving in Darnassus, you can meet Sister Aquinne in the Temple Gardens and see a first glimpse of the temple priesthood."},kw={"aquinne","darnassus","sister aquinne","temple gardens","temple of the moon"},rel={"subzone:temple-gardens","subzone:temple-of-the-moon","zone:darnassus","quest:2519","topic:night-elf","quest:940"},src={"Sister Aquinne"}}
E["npc:syurna"] = {t="npc",n="Syurna",z="darnassus",s="In Darnassus, Syurna trains night elf rogues in the Cenarion Enclave. She guides aspiring scouts, spies, and covert operatives, then sends new rogues on trials of stealth and cunning.",h="In Darnassus, Syurna trains night elf rogues in the Cenarion Enclave.",sec={{t="A Scout Among the Grove",b="Syurna trains those who move unseen through Darnassus. In the Cenarion Enclave, she teaches rogues evasion, lockpicking, and lethal strikes. The Sentinels display the Kaldorei’s martial strength, while the Sisterhood of Elune holds its spiritual wisdom. The Kaldorei also depend on shadows and stealth, and Syurna sharpens the eyes and blades that guard Teldrassil.",sp=0},{t="Tests of Cunning",b="Syurna tests young operatives beyond the lessons taught in the enclave. She sends promising initiates into deeper fieldwork to see whether they have the instincts to survive beyond the World Tree’s boughs and serve the Alliance in perilous frontier lands.",sp=0}},faq={{q="Who is Syurna?",a="Syurna trains night elf rogues in the Cenarion Enclave in Darnassus. She teaches combat skills and guides rogues serving the Alliance.",al={"syurna darnassus","who is syurna","night elf rogue trainer"},it="identity"},{q="Where exactly can I find Syurna in Darnassus?",a="Find Syurna in Darnassus’s Cenarion Enclave, among the trees and pavilions beside other mentors of the shadows.",al={"where is syurna","syurna location","darnassus rogue trainer location"},it="place",gp=true},{q="Why is a rogue trainer in the Cenarion Enclave?",a="The Cenarion Enclave is known chiefly for druidism and nature, but night elf scouts and covert pathfinders train along its wooded edges, away from the public pageantry of the Temple of Elune and the Warrior's Terrace.",al={"why is rogue trainer in enclave","cenarion enclave rogue"},it="why_here"},{q="What quests does Syurna offer?",a="Syurna guides novice operatives who have proven themselves in Shadowglen as they hone their talents in the wider world, including through Destiny Calls.",al={"syurna quests","destiny calls quest"},it="purpose",gp=true},{q="Whose side is Syurna on?",a="Syurna stands firmly with Darnassus and the Alliance. As a night elf rogue operating within the capital, she offers her expertise to those loyal to the Kaldorei cause, guiding aspiring scouts, thieves, and assassins in honing their subtle craft.",al={"syurna faction","who does syurna serve","syurna alliance"},it="side",add="4fb7093b"},{q="What does Syurna want?",a="Syurna's role is to instruct and guide promising rogues who arrive in Darnassus. She watches for those with keen instincts and stealth, directing them through training and assignments to ensure the shadows of Kalimdor serve the safety of the night elves.",al={"syurna goal","what is syurna trying to do","syurna purpose"},it="wants",add="d409bc2a"}},ang={["class:Rogue"]="As a night elf rogue, you can learn stealth, poison, and martial precision from Syurna, one of Darnassus’s principal instructors.",["race:NightElf"]="As a night elf, you share the Kaldorei scouts’ quiet tradition of protecting woodland sanctuaries from the shadows instead of open battle."},kw={"cenarion enclave","darnassus","destiny calls","kaldorei","rogue trainer","syurna","teldrassil"},rel={"zone:darnassus","subzone:cenarion-enclave","topic:night-elf","quest:2242","quest:940"},src={"Syurna"}}
E["npc:tyrande-whisperwind"] = {t="npc",n="Tyrande Whisperwind",z="darnassus",s="Tyrande Whisperwind keeps watch over the night elves from Teldrassil. She is Elune’s High Priestess and the supreme leader of her people, who endured the War of the Ancients and the ten millennia of the Long Vigil under her guidance alongside Malfurion Stormrage. Now she commands the Sisterhood of Elune and directs the Sentinel army in Kalimdor’s defense.",h="Tyrande Whisperwind keeps watch over the night elves from Teldrassil.",sec={{t="Chosen of the Moon Goddess",b="Born in the ancient kaldorei empire, Tyrande grew up with the twin brothers Malfurion and Illidan Stormrage. The brothers turned to druidism and sorcery, while she became a priestess of Elune. When the Burning Legion first invaded Azeroth in the War of the Ancients, Tyrande stood against it beside Malfurion. The Moon Goddess granted her direct favor, and Tyrande shaped the Sisterhood into a fighting force. Her priestesses wielded divine healing and lunar wrath as the kaldorei faced annihilation.",sp=0},{t="The Long Vigil and the Sentinels",b="After the Great Sundering and the sealing of the Well of Eternity, Malfurion and the druids entered the Emerald Dream for long hibernations. Tyrande took on the lonely task of defending their recovering realm. She formed the Sentinels, an elite cadre of warrior-women who patrolled Kalimdor’s forests through ten thousand years. During the Long Vigil, they kept watch over ancient evils and lingering demonic remnants. Tyrande held to her faith in Elune while centuries passed between brief reunions with Malfurion.",sp=0},{t="The Third War and a New Haven",b="When the Burning Legion returned during the Third War, Tyrande woke the sleeping druids to face the danger. Though she mistrusted the newly arrived orcs and humans, she helped forge a desperate coalition at Mount Hyjal. The night elves gave up their immortality at Nordrassil to destroy Archimonde. Mount Hyjal now bears the scars of that battle, and Malfurion is again occupied with guarding the Emerald Dream. From the grand Temple of the Moon in Darnassus, Tyrande governs the kaldorei and watches for Horde incursions as her people take their place in the Alliance.",sp=0}},faq={{q="Who is Tyrande Whisperwind?",a="Tyrande Whisperwind is the High Priestess of Elune and the supreme spiritual and political leader of the night elves. For over ten thousand years, she has guided her people from the War of the Ancients through the Third War. She now leads the kaldorei from the Temple of the Moon in Darnassus.",al={"who is tyrande","tyrande whisperwind lore","night elf leader"},it="identity"},{q="Where does Tyrande reside right now?",a="Tyrande resides in Darnassus, high in the branches of Teldrassil. She presides from the upper sanctuary of the Temple of the Moon, among the Priestesses of Elune and Sentinel guards.",al={"where is tyrande","tyrande location","where to find tyrande"},it="place"},{q="What is the relationship between Tyrande and Malfurion?",a="Tyrande and Malfurion Stormrage are lifelong partners who have guided night elf civilization together for ten millennia. In their youth, Malfurion and his twin brother Illidan both sought her love. Tyrande chose Malfurion, whose devotion to balance and nature reflected her faith in Elune.",al={"tyrande malfurion","is tyrande married","tyrande and illidan"},it="ties"},{q="What is the Sisterhood of Elune?",a="The Sisterhood of Elune is an ancient order of night elf priestesses devoted to the Moon Goddess. Under Tyrande, its members heal, serve as spiritual guides, and take fierce roles as martial commanders and combatants.",al={"sisterhood of elune","priestesses of elune","tyrande priests"}},{q="What role did Tyrande play in the Long Vigil?",a="During the ten thousand years after the Sundering, while Malfurion and the male druids slept in the Emerald Dream, Tyrande established and commanded the Sentinels. She patrolled Kalimdor’s wilds, hunted remaining satyrs and demons, and kept her people safe in isolation.",al={"what was the long vigil","tyrande long vigil","sentinel leader"},it="history"},{q="Why is Tyrande wary of the Horde?",a="Tyrande is wary of the Horde because orcs entered Ashenvale during the Third War, cut sacred forests, and slew the demigod Cenarius under the influence of demon blood. An uneasy truce was made at Mount Hyjal, but the Horde’s ongoing logging in Ashenvale keeps her Sentinels on high alert.",al={"tyrande horde","why does tyrande hate orcs","night elves vs horde"},it="hostile"},{q="Whose side is Tyrande Whisperwind on?",a="Tyrande stands as the supreme leader of the night elves and a core pillar of the Grand Alliance. She leads the Sisterhood of Elune and guides her people from the Temple of the Moon in Darnassus, committed utterly to protecting Kalimdor and her kin from external threats.",al={"what faction is tyrande","is tyrande alliance","tyrande loyalty"},it="side",add="0754c2cc"},{q="What does Tyrande Whisperwind want?",a="Her primary duty is safeguarding the kaldorei and the sacred forests of Kalimdor from corrupting forces, whether demonic remains or foreign invaders. With Malfurion slumbering in the Emerald Dream, she also shoulders the burden of guiding and defending their newly founded home on Teldrassil.",al={"what are tyrande goals","tyrande motivation","what is tyrande trying to do"},it="wants",add="68f13d2e"},{q="Why is Tyrande Whisperwind famous?",a="Tyrande is revered as Elune's chosen High Priestess who helped defeat the Burning Legion in the War of the Ancients ten thousand years ago. For millennia during the Long Vigil, she commanded the Sentinels to defend Kalimdor, later standing firm alongside mortal races at the Battle of Mount Hyjal.",al={"why is tyrande revered","tyrande legends","tyrande reputation"},it="fame",add="ade9ee47"}},ang={["race:NightElf"]="As a night elf, Tyrande is your supreme leader and High Priestess. For over ten thousand years, she has kept vigil over your people and championed the light of Elune through every trial.",["class:Priest"]="As a priest, see Tyrande as a living vessel of Elune’s divine favor. She embodies the height of kaldorei priesthood, calling down lunar stars and mending wounds through faith.",["faction:Alliance"]="Though your people have long been reclusive and fiercely independent, Tyrande leads the night elves within the Alliance for mutual defense against Kalimdor’s growing perils.",["class:Druid"]="As a druid, know that while Malfurion sleeps in the Emerald Dream, Tyrande works closely with the Cenarion Circle to protect sacred groves and nurture Teldrassil.",["faction:Horde"]="To the Horde, Tyrande is a formidable and uncompromising adversary. She has commanded the Sentinels to violently resist resource harvesting across Ashenvale."},kw={"darnassus","elune","kaldorei","malfurion","priestess","sentinels","teldrassil","tyrande","whisperwind"},rel={"npc:malfurion-stormrage","npc:shandris-feathermoon","quest:940","topic:night-elf","topic:elune","topic:sentinels","topic:war-of-the-ancients","zone:ashenvale"},src={"Tyrande Whisperwind"}}
E["quest:1038"] = {t="quest",n="Velinde's Effects",z="darnassus",s="In Darnassus, Velinde's Effects draw the Sentinels into an inquiry. The search concerns Sentinel Velinde Starsong, who vanished after years of service, and the journal Thyn'tel Bladeweaver asks you to retrieve from the Sentinels' quarters.",h="In Darnassus, Velinde's Effects draw the Sentinels into an inquiry.",sec={{t="A Trusted Sentinel",b="Priestess Velinde Starsong served the night elves for many years and earned their deep trust. When she quietly vanished from her duties, the Sentinels believed she had left for personal reasons and expected her to return. Outsiders later found clues tied to the Tome of Mel'Thandris. Only then did Sentinel leaders allow an inquiry into Velinde's private belongings.",sp=0},{t="The Chest in the Bunkhouse",b="Thyn'tel Bladeweaver is stationed on Darnassus's Warrior's Terrace and gives you the key to Velinde's locked trunk. The trunk is kept in the Sentinels' bunkhouse on the Tradesmen's Terrace. Inside lies Velinde's personal journal, with accounts of her assignments and thoughts. Its pages trouble the Sentinels: they hint at secret affairs that drove Velinde to leave Teldrassil alone.",sp=1}},faq={{q="Who is Velinde Starsong?",a="Velinde Starsong is a respected night elf priestess and Sentinel commander. Her devoted service earned deep respect from her peers before she vanished on an unexplained mission.",al={"velinde starsong lore","who is velinde","velinde backstory"},it="identity"},{q="Where is Velinde's chest located?",a="Velinde's chest is in the Sentinels' bunkhouse, on the upper floor of a building in Darnassus's Tradesmen's Terrace. Cross the elevated bridge from the neighboring mail armor shop to reach it.",al={"velinde chest location","where is velindes effects","sentinel bunkhouse darnassus"},it="place",gp=true},{q="Why didn't the Sentinels search for her earlier?",a="The Sentinels trusted Velinde's spotless reputation. Her commanders believed she had sound private reasons to leave and expected her to return when her business was done.",al={"why did sentinels ignore velinde","why wasn't velinde reported missing"}},{q="What is discovered inside the journal?",a="Velinde's journal shows her absence was more troubling than an ordinary leave. Thyn'tel Bladeweaver immediately seeks outside help to trace her route.",al={"velindes journal contents","what did velinde write"},it="item"},{q="How was Velinde connected to the Tome of Mel'Thandris?",a="The ancient elven text contained references to Velinde's past inquiries and activities. Those references first drew researchers and adventurers to investigate where she had gone.",al={"tome of melthandris velinde","why the tome of mel'thandris"},it="ties"},{q="Where does the investigation lead after finding her effects?",a="The journal's clues lead toward the Barrens, following Velinde's steps south toward Kalimdor's transit hubs and ports.",al={"where to go after velindes effects","velindes effects next quest"},sp=1,it="next_step"},{q="Why does Thyn'tel Bladeweaver want Velinde's effects searched?",a="The Sentinels long assumed Velinde Starsong departed Darnassus on her own accord and would return in due time, trusting her dedicated service. However, the revelation you uncovered from the Tome of Mel'Thandris suggests her disappearance may be far more complicated. Bladeweaver allows you access to her personal chest in hopes that Velinde's duty journal will provide crucial clues regarding her sudden departure and current whereabouts.",al={"why does thyntel want this","thyntel bladeweaver motive","why search velinde effects"},it="motive",add="c0fc6707"}},ang={["race:NightElf"]="As a night elf, Velinde Starsong's story recalls the quiet sacrifices of the Sisterhood of Elune and the Sentinels. Her sudden disappearance unsettles her kin in Darnassus.",["faction:Alliance"]="As an Alliance member, you can see how threats across Kalimdor challenge the fledgling Alliance leadership in Darnassus when high-ranking night elf officers need investigating.",["class:Priest"]="As a priest, you can recognize Velinde as a revered priestess devoted to sacred duties. You have reason to trace what led her astray."},kw={"bladeweaver","bunkhouse","darnassus","journal","mel'thandris","sentinels","starsong","thyn'tel","tradesmen's terrace","velinde"},rel={"zone:darnassus","npc:thyn-tel-bladeweaver","quest:1039","topic:sentinels"},m={start="Thyn'tel Bladeweaver",level="30",faction="Alliance",id=1038,ri={"Velinde's Journal"}},src={"Velinde's Effects"}}
E["quest:1039"] = {t="quest",n="The Barrens Port",z="darnassus",s="Thyn'tel Bladeweaver sends you from Darnassus to Ratchet to search for Velinde Starsong. The Sentinels believe she took a ship across the Great Sea to the Eastern Kingdoms, and her trail leads through dangerous Horde lands.",h="Thyn'tel Bladeweaver sends you from Darnassus to Ratchet to search for Velinde Starsong.",sec={{t="Tracking the Priestess",b="Clues among Velinde Starsong's personal effects suggest she sought passage across the sea to the Eastern Kingdoms. Ratchet is the Barrens' only working harbor, where travelers from northern Kalimdor can arrange passage south or east without sailing from night elf lands. Thyn'tel Bladeweaver sends you south to search the harbor master's ledgers for Velinde's name.",sp=0},{t="A Dangerous Crossing",b="The road to Ratchet crosses the heart of Horde lands. South of Ashenvale, orc outriders and Tauren patrols range across the Mor'shan Rampart and the dry Barrens. Ratchet is governed by the neutral Steamwheedle Cartel, whose goblin law puts trade ahead of faction rivalries. At the docks, Wharfmaster Dizzywig records every passenger and cargo crate.",sp=0}},faq={{q="Why do the Sentinels send me into the Barrens?",a="Ratchet is the main neutral trading port in central Kalimdor. Since Velinde Starsong vanished while seeking passage to the Eastern Kingdoms, the night elves believe she may have booked travel aboard a goblin trading vessel instead of using official military channels.",al={"why go to ratchet","why the barrens port"},it="motive"},{q="Who is Wharfmaster Dizzywig?",a="Wharfmaster Dizzywig oversees departures and cargo records at Ratchet's docks. He works for the Steamwheedle Cartel and keeps ledgers of vessels, passengers, and shipments entering and leaving the harbor.",al={"who is dizzywig","ratchet wharfmaster"},it="identity"},{q="Why would an Alliance member be safe in Ratchet?",a="The neutral Steamwheedle Cartel runs Ratchet instead of the Horde. Its goblins put commerce and profit first, and their bruisers keep the peace, allowing Alliance travelers to do business so long as they do not draw weapons inside town.",al={"is ratchet safe for alliance","will guards attack me in ratchet"},it="place"},{q="What happens after finding Wharfmaster Dizzywig?",a="After checking his records, Dizzywig confirms Velinde left aboard a vessel bound for the Eastern Kingdoms. He sends you to Booty Bay in Stranglethorn Vale to pick up her trail across the Great Sea.",al={"what next after barrens port","velinde quest continuation"},sp=1,it="next_step"},{q="How does an Alliance traveler reach Ratchet safely?",a="From Ashenvale, Alliance travelers can go south past Silverwing Grove, then skirt the guarded Mor'shan Rampart through the hills just east of the main road. In the Barrens, follow the paths toward the eastern coast to reach Ratchet's docks.",al={"safest way to ratchet alliance","how to get to ratchet alliance"},gp=true},{q="Who is Velinde Starsong?",a="Velinde Starsong was a night elf priestess and Melyria Frostshadow's predecessor in Ashenvale. Charged with cleansing the forest of demons, she made little headway before she disappeared. Her trail now seems to cross the sea.",al={"who is velinde","velinde starsong lore"},it="target"},{q="Why does Thyn'tel Bladeweaver need me instead of sending a Sentinel to Ratchet?",a="The Barrens are firmly controlled by the Horde, and armed night elf Sentinels marching south from Ashenvale would provoke an immediate and bloody skirmish. While the neutral port of Ratchet welcomes peaceful travelers, an official Kaldorei military presence would disrupt the fragile truce and draw intense suspicion. A lone adventurer can slip past Horde borders unnoticed and deal with the goblins without igniting open warfare.",al={"why send me","why not send a sentinel","why me barrens port"},it="why_me",add="1c038d53"}},ang={["race:NightElf"]="As a night elf, Velinde Starsong's loss weighs heavily on Darnassus's leadership. Retracing her desperate journey is a matter of kaldorei duty.",["faction:Alliance"]="As an Alliance scout, you cross Horde-patrolled lands in the Barrens before reaching the neutral goblin docks, so caution matters."},kw={"ashenvale","ratchet","scythe of elune","steamwheedle cartel","the barrens","thyn'tel bladeweaver","velinde starsong","wharfmaster dizzywig"},rel={"quest:1038","quest:1040","subzone:ratchet","npc:thyn-tel-bladeweaver","zone:barrens","zone:ashenvale","subzone:mor-shan-rampart","topic:goblin"},m={start="Thyn'tel Bladeweaver",["end"]="Wharfmaster Dizzywig",level="30",faction="Alliance",id=1039},src={"The Barrens Port"}}
E["quest:1582"] = {t="quest",n="Moonglow Vest",z="darnassus",s="In Darnassus, Lotherias needs leather gear for young adventurers setting out across Kalimdor. She offers the pattern for a Moonglow Vest in return for shipments of embossed leather goods.",h="In Darnassus, Lotherias needs leather gear for young adventurers setting out across Kalimdor.",sec={{t="Equipping the Kaldorei",b="In Darnassus, leatherworkers work to outfit sentinels and young scouts. Night elves and allied wanderers leave Teldrassil for the wilds of Kalimdor, where sturdy armor is in demand. Lotherias is among the master leatherworkers supplying them with gear.",sp=0},{t="Mastering the Craft",b="Lotherias asks apprentices to bring matched embossed gloves, boots, and cloaks as proof of their skill. Those who meet her order earn her trust, and she teaches them a night elf pattern for the Moonglow Vest, made to protect while allowing free movement.",sp=0}},faq={{q="Who is Lotherias?",a="Lotherias is a night elf leatherworking trainer in Darnassus. She teaches the craft and offers advanced patterns to leatherworkers who prove their skill.",al={"lotherias darnassus","who gives moonglow vest"},it="identity"},{q="Why does Lotherias need so many leather items?",a="Lotherias needs embossed leather gear to outfit young adventurers preparing to travel beyond Darnassus. She asks apprentices to supply the standard garments.",al={"why need so many boots","why craft embossed leather"},it="motive"},{q="What is the Moonglow Vest?",a="The Moonglow Vest is a leather armor pattern Lotherias teaches after you prove you can craft embossed goods in quantity.",al={"moonglow vest recipe","what do i get"},it="item"},{q="What materials are required to complete this task?",a="Bring Lotherias one pair of Embossed Leather Gloves, five pairs of Embossed Leather Boots, and five Embossed Leather Cloaks. You must craft each piece and deliver it to her.",al={"what do i need","moonglow vest items"},it="item",gp=true},{q="Can Horde leatherworkers learn this pattern here?",a="No. Lotherias trains Alliance craftspeople in Darnassus. Horde leatherworkers need to find trainers of their own across Kalimdor and the Eastern Kingdoms.",al={"can horde do this","is moonglow vest alliance only"},gp=true},{q="Does this quest require a specific trade skill level?",a="Yes. You need leatherworking proficiency of at least seventy before Lotherias will consider you skilled enough for the order and the vest pattern.",al={"leatherworking level needed","when can i get moonglow vest"},gp=true},{q="What are the Embossed Leather Gloves for?",a="Lotherias and the other craftsmen in Darnassus are swamped trying to outfit the surge of young adventurers setting out into the wilds. She asks you to craft a pair of Embossed Leather Gloves to help fulfill her overflowing orders, testing your skill at fine detail before she shares advanced techniques with you.",al={"why embossed leather gloves","embossed leather gloves use","lotherias gloves"},it="item",add="304f0e76"},{q="What are the Embossed Leather Boots for?",a="Lotherias needs five pairs of Embossed Leather Boots to supply local adventurers preparing for dangerous expeditions across Kalimdor. Providing sturdy, reliable footwear in bulk proves your consistency as a leatherworker and eases the strain on Darnassus's busy artisan workshops.",al={"why embossed leather boots","embossed leather boots use","lotherias boots"},it="item",add="3d684782"},{q="What is the Embossed Leather Cloak for?",a="The five Embossed Leather Cloaks are meant to outfit new adventurers braving the elements in Teldrassil and beyond. Lotherias is inundated with supply demands, and crafting these durable cloaks proves you possess both the stamina and technical aptitude required for advanced leatherworking training.",al={"why embossed leather cloak","embossed leather cloaks use","lotherias cloaks"},it="item",add="83a79481"}},ang={["race:NightElf"]="As a night elf, you can see the fine leatherwork of Teldrassil in the Moonglow Vest, with its agile protection for scouts and sentinels beneath the forest canopy.",["faction:Alliance"]="As an Alliance artisan, you help outfit new recruits in Darnassus, where the Alliance holds a fragile foothold in northern Kalimdor amid growing wild and hostile threats."},kw={"crafting","darnassus","embossed leather","kaldorei","leatherworking","lotherias","moonglow vest","teldrassil"},rel={"zone:darnassus"},m={start="Lotherias",faction="Alliance",id=1582,ri={"Embossed Leather Boots","Embossed Leather Cloak","Embossed Leather Gloves"}},src={"Moonglow Vest (quest)"}}
E["quest:1683"] = {t="quest",n="Vorlus Vilehoof",z="darnassus",s="In Darnassus, young night elf warriors face a trial set by Elanaria. They must hunt a satyr who has defiled a hidden moonwell near the Ban'ethil Barrow Den.",h="In Darnassus, young night elf warriors face a trial set by Elanaria.",sec={{t="A Test of Resolve",b="Elanaria asks you to prove your dedication and discipline before she teaches advanced martial techniques. She needs more than words from those who defend Kalimdor. A guardian must face corruption and cleanse the sacred boughs of Teldrassil.",sp=0},{t="Defiling the Sacred Waters",b="Your trial leads to Vorlus Vilehoof, a satyr hiding at a moonwell in the mountains southeast of Ban'ethil Barrow Den. Satyrs were once ancient betrayers, twisted by demonic influence, and they hate sacred Kaldorei relics. Vorlus bathes in the moonwell, fouling its blessed waters and mocking the grace of Elune.",sp=0},{t="Claiming the Horn",b="Gnarlpine furbolgs guard a concealed mountain trail that leads to Vorlus. At the tainted spring, you face the satyr in combat. Bring his horn back to the Warrior's Terrace in Darnassus as proof of his death. The glade's sanctity can be restored, and the way opens to specialized martial weapons.",sp=1}},faq={{q="Who is Vorlus Vilehoof?",a="Vorlus Vilehoof is a corrupted satyr who dwells on Teldrassil. He found a secluded moonwell southeast of the Ban'ethil Barrow Den and began bathing in its consecrated waters, defiling them.",al={"vorlus vilehoof lore","who is vorlus","vorlus the satyr"},it="target"},{q="Why does Elanaria send warriors after Vorlus?",a="Elanaria sends you after Vorlus as a proving trial for promising warriors. Defeating this dangerous, corrupt fiend shows the focus, courage, and resolve needed before she teaches advanced martial skills or guides you in forging specialized weapons.",al={"why kill vorlus","elanaria quest reason","purpose of vorlus vilehoof quest"},it="why_me"},{q="Where is the hidden moonwell located?",a="The hidden moonwell lies in the ridges southeast of Ban'ethil Barrow Den. Find the subtle mountain path lined with torches just behind a Gnarlpine furbolg encampment east of the barrows.",al={"vorlus location","how to find vorlus","hidden moonwell path"},it="place",gp=true},{q="What is a moonwell, and why does his presence matter?",a="Moonwells are sacred basins of blessed water that channel the light of Elune and sustain nature's vitality. A demonic satyr bathing in one desecrates Kaldorei faith and brings a dangerous source of corruption to Teldrassil.",al={"why are moonwells important","moonwell desecration","night elf moonwells"},it="danger"},{q="What comes after defeating Vorlus Vilehoof?",a="After you return Vorlus's severed horn, Elanaria is satisfied and confirms your readiness. She directs you onward to pursue the legendary Weapons of Elunite, beginning with uncovering the Shade of Elura.",al={"next quest after vorlus","what happens next","shade of elura quest"},sp=1,it="next_step"},{q="Are there other satyrs on Teldrassil?",a="Yes. Satyrs lurk on Teldrassil, including at Fel Rock and in scattered corrupt hollows, seeking to infect the World Tree with demonic taint.",al={"satyrs on teldrassil","teldrassil satyr threat"},it="threat"},{q="Why does Elanaria want Vorlus Vilehoof killed?",a="To Elanaria and the night elves, moonwells are sacred sanctuaries filled with blessed waters. Vorlus Vilehoof has discovered a secluded moonwell southeast of the Ban'ethil Barrow Den and actively defiles it by splashing his corrupt satyr filth across its sacred pool. Elanaria cannot allow such desecration to persist on Teldrassil, and destroying the beast removes an immediate threat of corruption from the great bough.",al={"elanaria motive","why kill vorlus","elanaria reason vorlus"},it="motive",add="2a0bd33d"}},ang={["class:Warrior"]="As a warrior, hunting Vorlus begins your initiation into advanced martial training. It shows that your blade protects Kaldorei lands and the sanctity of the goddess.",["race:NightElf"]="As a night elf, you know moonwells reflect the purity of Elune and the lifeblood of Kaldorei spirituality. A satyr bathing in their waters insults all night elves.",["faction:Alliance"]="As an Alliance member, you help secure Teldrassil's interior from lurking demonic remnants, keeping Darnassus a steadfast redoubt for the Alliance in Northern Kalimdor."},kw={"ban'ethil","darnassus","elanaria","horn of vorlus","moonwell","satyr","teldrassil","vorlus vilehoof","warrior quest"},rel={"npc:elanaria","quest:1686","quest:1693","topic:satyr","subzone:ban-ethil-barrow-den","zone:darnassus","quest:940"},m={start="Elanaria",level="10",faction="Alliance",id=1683},src={"Vorlus Vilehoof (quest)"}}
E["quest:1686"] = {t="quest",n="The Shade of Elura",z="darnassus",s="At Auberdine, Elura's shade guards a sunken ship and its Elunite ore. Elanaria sends young night elf warriors into the waters to lay the captain to rest and recover her medallion and ore for a weapon forged by Smith Mathiel.",h="At Auberdine, Elura's shade guards a sunken ship and its Elunite ore.",sec={{t="A Captain's Eternal Guard",b="Long ago, a ship carrying rare Elunite ore struck jagged coastal rocks near the Auberdine lighthouse and sank. The captain, Elura, cursed her own soul in despair and out of unwavering duty. Bound to the wreck beneath the waves, her shade guards the lost cargo from anyone who would disturb it.",sp=0},{t="Weapons of Elunite",b="Elanaria sends young night elf warriors into Darkshore's surf to defeat Elura, recover her medallion, and salvage the ore. They need both the medallion and ore to put the captain to rest and bring the metal to Smith Mathiel's forge. The work tests their martial skill and respect for the fallen, and provides the ore for a crafted weapon.",sp=0}},faq={{q="Who is the Shade of Elura?",a="Elura was captain of an elven ship that wrecked on the shallows near the Auberdine lighthouse. She cursed herself to guard the sunken cargo of Elunite ore.",al={"shade of elura lore","who is elura","captain elura"},it="target"},{q="Why does Elanaria send warriors after Elura?",a="Elanaria sends warriors to defeat Elura, recover her medallion and ore, and put her spirit to rest. The trial tests their prowess and provides the material for a weapon.",al={"why do we kill elura","elanaria quest purpose"},it="motive"},{q="Where did the wreck happen?",a="The wreck lies underwater off Auberdine's coast in Darkshore, near the lighthouse and just south of the main harbor docks.",al={"where is the shipwreck","elura ship location"},it="place"},{q="What is Elunite ore used for?",a="Night elven smiths use rare Elunite ore to forge weapons. The salvaged crates go to Smith Mathiel in Darnassus, who makes a personalized martial weapon for promising warriors.",al={"what is elunite","elunite ore purpose"},it="item"},{q="Does defeating the shade harm Elura permanently?",a="Defeating Elura breaks the curse binding her spirit to the sea floor. Elanaria says that besting the captain in combat brings her peace after her long vigil.",al={"did elura die","is elura saved"}},{q="Who crafts the weapon once the ore is collected?",a="After Elanaria receives the ore and medallion, she sends the warrior to Smith Mathiel in Darnassus's Warrior's Terrace. He works the metal into an exceptional weapon.",al={"who makes the elunite weapon","next quest after elura"},it="next_step"},{q="Why does Elanaria send you rather than retrieving the ore herself?",a="As your warrior trainer, Elanaria is guiding your rite of passage into true martial mastery. Recovering the Elunite ore is not merely a supply errand for Darnassus; braving the treacherous depths off Auberdine and putting Captain Elura's restless spirit to rest proves you possess the courage and skill worthy of wielding a warrior's custom forged weapon.",al={"why me shade of elura","why elanaria sends warrior","why not send guards for elura"},it="why_me",add="522232db"}},ang={["class:Warrior"]="As a night elf warrior, you prove your aquatic grit and martial discipline in a trial that earns you a forged Elunite weapon.",["race:NightElf"]="As a night elf, you honor a fellow kaldorei by laying Elura's shade to rest after her sense of duty bound her beneath the waves for generations.",["profession:Blacksmithing"]="As a blacksmith, you see the night elves' metallurgical traditions in the potent armaments they craft from blessed Elunite materials."},kw={"auberdine","darkshore","darnassus","elanaria","elunite ore","elura","shade of elura","smith mathiel","weapons of elunite"},rel={"quest:1692","quest:1693","npc:elanaria","subzone:auberdine","zone:darkshore","zone:darnassus"},m={start="Elanaria",level="10",faction="Alliance",id=1686},src={"The Shade of Elura"}}
E["quest:1692"] = {t="quest",n="Smith Mathiel",z="darnassus",s="In Darnassus, sacred ore is on its way to the forge. After you recover elunite from the shipwreck off Auberdine, Elanaria sends you to Mathiel to have it shaped into a weapon for the Kaldorei.",h="In Darnassus, sacred ore is on its way to the forge.",sec={{t="A Sacred Delivery",b="Elanaria sends you across Darnassus's Warrior's Terrace with the elunite ore you recovered from the haunted shipwreck off Auberdine. The warrior trainer packs it in a sturdy case and directs you to Mathiel, one of the capital's finest smiths. He can shape the metal into a weapon worthy of your calling.",sp=0},{t="The Blessing of Elunite",b="Mathiel treats smithing as a craft of devotion. Elunite bears the sacred blessing of Elune, the Moon Goddess, and he accepts the case as an honor. He will shape the holy metal into arms to defend the young boughs of Teldrassil.",sp=0}},faq={{q="Who is Smith Mathiel?",a="Mathiel is a skilled night elf blacksmith who works in Darnassus's Warrior's Terrace. He makes specialty arms and accepts custom work for the city's defenders.",al={"who is mathiel","blacksmith mathiel","where is mathiel"},it="identity"},{q="What is special about elunite ore?",a="Night elves revere elunite as a rare metal blessed by Elune. Mathiel considers shaping it into potent weapons a high honor.",al={"what is elunite","is elunite magical","elunite lore"},it="item"},{q="Who sends you to Mathiel?",a="Elanaria, the warrior trainer in Darnassus's Warrior's Terrace, packs your recovered ore and sends you to Mathiel across the terrace.",al={"who gives smith mathiel quest","quest giver smith mathiel"}},{q="Is this quest only available to warriors?",a="Yes. This is part of the level ten warrior class story, meant to arm young warriors with their first specialized weapon.",al={"warrior only","can other classes do smith mathiel"},gp=true},{q="Where in Darnassus can Mathiel be found?",a="Mathiel works in Darnassus's Warrior's Terrace, just south across the structure from Elanaria.",al={"mathiel location","find mathiel"},it="place",gp=true},{q="What happens after you deliver the ore to Mathiel?",a="After you deliver the ore, Mathiel begins shaping it and offers you a choice of which elunite weapon suits your fighting style.",al={"what comes after smith mathiel","next quest after smith mathiel"},it="next_step"},{q="Why does Elanaria send you to Smith Mathiel?",a="Elanaria is your warrior trainer in Darnassus, and her duty is to oversee your training and arm you for the challenges ahead. After you gathered the sacred elunite ore from Darkshore, she securely cased it so that Smith Mathiel, an artisan skilled in holy metalwork, could forge it into a proper weapon worthy of an elven warrior.",al={"elanaria motive","why send to mathiel","why elanaria mathiel"},it="motive",add="4e03f025"}},ang={["class:Warrior"]="As a young Kaldorei warrior, bringing elunite to Mathiel marks a passage from training blades to a custom weapon blessed by the Moon Goddess.",["race:NightElf"]="As a night elf, elunite work joins your people's craft with devotion to Elune, where martial strength and faith meet.",["profession:Blacksmithing"]="As a blacksmith, Mathiel's reverence for elunite shows how Kaldorei smiths bring sacred blessings into their craft alongside heat and hammer."},kw={"warrior's terrace","darnassus","elanaria","elunite","mathiel","smith","warrior"},rel={"quest:1693","quest:1686","npc:elanaria","topic:elune","quest:1703"},m={start="Elanaria",["end"]="Mathiel",level="10",faction="Alliance",id=1692},src={"Smith Mathiel"}}
E["quest:1693"] = {t="quest",n="Weapons of Elunite",z="darnassus",s="In Darnassus, Weapons of Elunite brings a young warrior's early rite of passage to its close. After recovering ore blessed by Elune, you bring it to Mathiel to forge arms for a defender of Kalimdor.",h="In Darnassus, Weapons of Elunite brings a young warrior's early rite of passage to its close.",sec={{t="A Sacred Forge",b="Night elf warriors defend Teldrassil and the kaldorei people. Promising young warriors gather elunite, a mineral blessed by the Moon Goddess, rather than relying on mundane steel alone. Its ore calls for a smith skilled in metalcraft and mindful of Elune's gift.",sp=0},{t="Mathiel's Craft",b="Smith Mathiel works in Darnassus, shaping blessed elunite into weapons of war. He considers the work an honor, not routine metalcraft. When you bring him the ore, he fashions arms to suit your style and rewards your service with weapons blessed by your goddess.",sp=0}},faq={{q="What is the purpose of this quest?",a="This rite of passage for a young warrior in Darnassus reaches its end when you bring elunite ore to Smith Mathiel. He forges weapons blessed by Elune to aid your journey across Kalimdor.",al={"weapons of elunite quest","why do this quest","warrior level 10 darnassus"},it="purpose"},{q="Who is Mathiel?",a="Mathiel is a skilled night elf smith who lives in Darnassus. He knows how to forge elunite into balanced arms for the city's defenders.",al={"smith mathiel","who is mathiel","darnassus smith"},it="identity"},{q="What is elunite?",a="Elunite is a rare mineral sacred to the night elves, believed to hold Elune's luminescence and favor. Shaping it into weapons is a solemn honor for a smith.",al={"what is elunite ore","elunite lore"},it="item"},{q="Who can undertake this quest?",a="This undertaking is for Alliance warriors training near Darnassus who have completed the earlier work of finding and gathering elunite for Smith Mathiel.",al={"who gets weapons of elunite","is this warrior only"},it="why_me",gp=true},{q="Where does this quest take place?",a="You bring the ore to Smith Mathiel in Darnassus, the night elf capital high in the boughs of Teldrassil.",al={"weapons of elunite location","where is mathiel"},it="place"},{q="Why does Mathiel thank the adventurer?",a="Mathiel thanks you because shaping elunite is both a sacred honor and a personal pleasure. Few smiths receive the privilege of working ore tied to Elune, so your delivery is a boon to him.",al={"why is mathiel honored","mathiel dialogue"},it="motive"},{q="Why does Mathiel ask you to do this rather than a guard?",a="This commission is a rite of passage for a promising young warrior rather than an official civic duty. Sentries and temple guards are sworn to defend Darnassus and Teldrassil from active threats, leaving them no leisure to gather rare smithing materials for personal armaments. By undertaking the labor to gather the ore yourself, you prove your dedication and discipline, earning a weapon forged specifically to match your martial path.",al={"why send me","why me mathiel","why warrior"},it="why_me",add="cb47846f"}},ang={["class:Warrior"]="As a young kaldorei warrior, you mark an early rite of martial service and receive dependable weapons blessed by Elune.",["race:NightElf"]="As a night elf, you see reverence for the Moon Goddess joined to the practical craft of war and defense.",["profession:Blacksmithing"]="As a blacksmith, you see Mathiel balance ordinary metalwork with the care needed to shape sacred elunite."},kw={"darnassus","elune","elunite","kaldorei","mathiel","teldrassil","warrior","weaponsmith"},rel={"quest:1692","zone:darnassus","quest:1703"},m={start="Mathiel",level="10",faction="Alliance",id=1693},src={"Weapons of Elunite"}}
E["quest:1703"] = {t="quest",n="Mathiel",z="darnassus",s="Furen Longbeard sends his crafting notes across the sea to Mathiel in Darnassus. The night elf smith works on the Warrior's Terrace, where dwarven mail forging may reach a new pair of hands.",h="Furen Longbeard sends his crafting notes across the sea to Mathiel in Darnassus.",sec={{t="A Courier Across the Sea",b="Furen Longbeard has mastered the forging of fire-hardened armor and chooses to share what he has learned with other Alliance craftsmen. He copies his technical diagrams and sends you across the continents to Mathiel, a smith on Teldrassil.",sp=0},{t="Kaldorei Steel and Dwarven Craft",b="On Darnassus's Warrior's Terrace, Mathiel tends a forge for the Sentinels and other fighters who defend the night elf capital. Furen's notes carry dwarven methods from the underground forges of Khaz Modan to kaldorei armorers, whose craft is shaped by their bond with nature.",sp=0}},faq={{q="Who is Mathiel?",a="Mathiel is a night elf blacksmith on the Warrior's Terrace in Darnassus. He makes equipment for the capital's defenders and corresponds with smiths across the Alliance.",al={"mathiel lore","who is mathiel darnassus"},it="identity"},{q="Why does Furen send you to Darnassus?",a="Furen Longbeard wants other Alliance craftsmen to benefit from his work on fire-hardened armor. He sends you to carry his crafting notes to Mathiel, a colleague able to study the techniques.",al={"why send notes to mathiel","furen notes reason"},it="motive"},{q="Where can I find Mathiel in Darnassus?",a="Mathiel works at the forge on Darnassus's Warrior's Terrace, in the eastern district by the main gate, where warriors and Sentinels train.",al={"mathiel location","where is mathiel"},it="place",gp=true},{q="What happens after giving Mathiel the notes?",a="After receiving Furen's notes, Mathiel is impressed by the discoveries and sets out to build on the dwarven techniques. He sends you into Kalimdor's wilderness to gather rare materials, including sunscorched shells.",al={"next quest after mathiel","mathiel followup"},sp=1,it="next_step"},{q="What kind of notes are being delivered?",a="The notes hold Furen's observations and forging methods from experiments with scorched spider fangs, chimaera horns, and phlogiston to make reinforced mail.",al={"furen notes contents","what are furen's notes"},it="item"},{q="Is this quest restricted to warriors?",a="Yes. The delivery is part of the trials and training for Alliance warriors building their martial skill and knowledge of armorcraft.",al={"warrior quest mathiel","can other classes do mathiel"},gp=true},{q="Why does Furen Longbeard trust you to deliver his notes to Mathiel?",a="You proved your dedication and strength by gathering the rare reagents Furen needed to forge your fire-hardened armor in the first place. Having witnessed your reliability firsthand, he knows you are more than capable of traversing the long road across the sea to Darnassus to deliver his hard-won techniques into Mathiel's hands.",al={"why send me mathiel","why me furen notes","why does furen need me"},it="why_me",add="c109af9e"}},ang={["class:Warrior"]="As a warrior, carrying Furen's notes takes you from the smithies of the Eastern Kingdoms to Darnassus's proving grounds, where your knowledge of armorcraft grows.",["race:Dwarf"]="As a dwarf, sharing Furen's discovery with the night elves carries your people's pride in the forge across the sea.",["race:NightElf"]="As a night elf, you can see Mathiel's interest in dwarven smithing and its place beside kaldorei armorcraft.",["profession:Blacksmithing"]="As a blacksmith, you see master smiths share their craft as diagrams and heat tempering methods travel between distant forges."},kw={"blacksmith","darnassus","fire hardened mail","furen longbeard","furen's notes","mathiel","teldrassil","warrior's terrace"},rel={"quest:1701","quest:1710","npc:furen-longbeard","subzone:warrior-s-terrace","zone:darnassus"},m={start="Furen Longbeard",["end"]="Mathiel",level="28",faction="Alliance",id=1703},src={"Mathiel (quest)"}}
E["quest:1710"] = {t="quest",n="Sunscorched Shells",z="darnassus",s="In Darnassus, Mathiel seeks wyvern eggshells to strengthen a new mailcrafting technique. The armorer works with the dwarven smith Furen Longbeard and sends warriors to gather shells from Highperch in Thousand Needles.",h="In Darnassus, Mathiel seeks wyvern eggshells to strengthen a new mailcrafting technique.",sec={{t="A Cross-Faction Crafting Alliance",b="Mathiel works from the Warrior's Terrace in Darnassus and looks beyond night elven methods. He corresponds with Furen Longbeard, a skilled dwarven armorer in Stormwind, and draws on Furen's discoveries in metalwork and armor-smithing. Mathiel hopes to make mail reinforced with natural materials that can withstand great strain. To test the idea, he needs materials found nowhere near Teldrassil.",sp=0},{t="The Perils of Highperch",b="Mathiel's experiment calls for shells from Highperch, far south across the sea in the canyon gorges of Thousand Needles. Wyverns nest high above the salt flats and red stone mesas, beneath Kalimdor's blazing sun. Constant exposure to heat and altitude hardens their eggshells. Mathiel plans to grind the sun-baked fragments into a resilient lacquer and coat chainmail links, making armor that bends while enduring exceptional strain.",sp=0}},faq={{q="Who is Mathiel?",a="Mathiel is a night elf armorer on the Warrior's Terrace in Darnassus. He works with dwarven methods and Furen Longbeard to develop advanced mail armor for proven warriors.",al={"mathiel","who gives sunscorched shells","mathiel darnassus"},it="identity"},{q="Why does Mathiel need wyvern shells?",a="Highperch wyvern shells harden beneath the harsh sun of Thousand Needles. Mathiel plans to grind and render them into lacquer for mail links, strengthening the armor.",al={"why wyvern shells","sunscorched shell purpose","what are shells for"},it="motive"},{q="Where is Highperch located?",a="Highperch is a steep mesa in western Thousand Needles, near the Feralas border. Wyverns nest across its cliffs and plateau.",al={"highperch location","where is highperch","how to find highperch"},it="place",gp=true},{q="How does Furen Longbeard relate to this quest?",a="Furen Longbeard is a master dwarven armorer in Stormwind. Mathiel respects him as a colleague and draws inspiration from his armor-crafting discoveries.",al={"furen longbeard connection","who is furen"},it="ties"},{q="Why is an elf in Darnassus asking for materials from Thousand Needles?",a="Mathiel needs a resilience found in wyvern eggs exposed to the dry heat of the southern canyon mesas. That heat cannot be recreated in Teldrassil's misty boughs.",al={"why thousand needles","darnassus to thousand needles"},it="why_here"},{q="What happens after bringing the shells to Mathiel?",a="After Mathiel receives twenty sunscorched shells, he begins rendering the lacquer and forging a bespoke mail suit for you in return for your field efforts.",al={"what next mathiel","after sunscorched shells","mathiel follow up"},it="next_step"},{q="What is the Sunscorched Shell for?",a="These resilient egg shells from the Highperch wyverns are surprisingly tough. Mathiel intends to break them down and render them into a protective lacquer, which he will use to coat the individual links of his experimental mail armor to increase its durability.",al={"sunscorched shell use","why sunscorched shell","what are the egg shells for"},it="item",add="dd37f0b8"}},ang={["class:Warrior"]="As an Alliance warrior, you can help Mathiel test a way to make resilient mail armor.",["profession:Blacksmithing"]="You can see an unusual smithing method at work: beast materials become a protective lacquer for metal chain links.",["faction:Alliance"]="You can see night elf craftsmen in Darnassus exchanging techniques with dwarven armorers in Stormwind."},kw={"eggshells","furen longbeard","highperch","lacquer","mail armor","mathiel","thousand needles","wyvern"},rel={"quest:1703","quest:1711","npc:furen-longbeard","subzone:highperch","zone:thousandneedles","zone:darnassus"},m={start="Mathiel",level="30",faction="Alliance",id=1710,ri={"Sunscorched Shell"}},src={"Sunscorched Shells"}}
E["quest:1711"] = {t="quest",n="Mathiel's Armor",z="darnassus",s="At the forge in Darnassus, Mathiel's Armor brings night elf and dwarven craft together. Mathiel works in the Warrior's Terrace, using methods devised by Furen Longbeard to shape exotic materials into armor for Alliance warriors.",h="At the forge in Darnassus, Mathiel's Armor brings night elf and dwarven craft together.",sec={{t="A Blend of Crafts",b="Night elf armorers have favored methods honed over millennia, with work shaped by nature, supple leathers, and carefully worked metals. Trade with the Eastern Kingdoms has led smiths such as Mathiel to try new ways. He brings the dwarven techniques devised by Furen Longbeard together with elven craft.",sp=0},{t="Exotic Components",b="Mathiel needs sunscorched eggshells from the Highperch wyvern nests in Thousand Needles. He renders the sun-hardened shells into lacquer and uses Furen's heat-treatment formulas to forge resilient leggings for the front lines.",sp=0}},faq={{q="Who is Mathiel?",a="Mathiel is a skilled night elf armorsmith in Darnassus's Warrior's Terrace. He works with fellow Alliance craftsmen and tests ideas from allies such as Furen Longbeard.",al={"mathiel","who is mathiel","darnassus armorer"},it="identity"},{q="Who is Furen Longbeard?",a="Furen Longbeard is a master dwarven armorsmith who lives in Stormwind City. He devised methods for tempering and forging specialized armor plates, and shares instructions and designs with allied smiths.",al={"furen","furen longbeard"},it="people"},{q="What materials were used to forge the armor?",a="The armor uses sunscorched eggshells gathered below the Highperch wyvern nests in Thousand Needles. Mathiel reinforces and shapes them with Furen Longbeard's smithing methods.",al={"armor materials","what is mathiel's armor made of"},it="item"},{q="Why is an elf using dwarven techniques?",a="Alliance smiths share knowledge to equip their fighters against growing threats. Mathiel uses dwarven hardening methods alongside the finesse and durability of night elf smithing.",al={"why dwarven smithing","night elf dwarf collaboration"},it="ties"},{q="Where does this quest take place?",a="The work begins and ends at the forge in Darnassus's Warrior's Terrace, on the island of Teldrassil.",al={"mathiel location","where is mathiel"},it="place",gp=true},{q="What is the previous quest in this chain?",a="The chain follows 'Sunscorched Shells', in which an adventurer travels to a distant part of Kalimdor to gather tough eggshells for Mathiel's craft.",al={"previous quest","mathiels armor prereq"},it="history",gp=true},{q="Why does Mathiel forge this armor for you?",a="Mathiel wants to test and prove the craft shared by Furen Longbeard. By blending dwarven armorsmithing techniques with elven traditions, he is able to craft exceptionally resilient mail leggings to bolster warriors fighting on behalf of the Alliance.",al={"why does mathiel make armor","mathiel motivation","why craft mathiel's armor"},it="motive",add="5fea36e4"}},ang={["class:Warrior"]="For Alliance warriors, this chain yields sturdy leggings made with night elf and dwarven smithing knowledge.",["profession:Blacksmithing"]="Dwarven tempering and night elf forge craft come together in this work.",["faction:Alliance"]="Mathiel and Furen's partnership shows how the Alliance unites distant peoples through trade and mutual defense to serve its military needs."},kw={"craftsmen's terrace","darnassus","furen longbeard","mathiel","mathiel's armor","sunscorched shells","warrior armor"},rel={"quest:1710","quest:1703"},m={start="Mathiel",level="30",faction="Alliance",id=1711},src={"Mathiel's Armor"}}
E["quest:2242"] = {t="quest",n="Destiny Calls",z="darnassus",s="Syurna sends you to learn what Sethir the Ancient knows of Teldrassil's corruption. The satyr waits near the Oracle Glade, beyond the reach of those who tried force or diplomacy.",h="Syurna sends you to learn what Sethir the Ancient knows of Teldrassil's corruption.",sec={{t="A Silent Reconnaissance",b="Teldrassil's growing sickness troubles the night elf leaders in Darnassus. Syurna, the rogue trainer, needs someone subtle; armed patrols have died trying to reach Sethir the Ancient. The satyr roosts on a remote bough near the Oracle Glade and has turned away force and diplomacy alike. To learn what he knows, you need to enter his lair and take his personal possessions.",sp=0},{t="A Looming Shadow from Darkshore",b="Sethir the Ancient's journal links Teldrassil's taint to the rot and corruption consuming Darkshore's forests and waterways across the misty sea. The sickness is not confined to the soil beneath the World Tree. Its reach points to a deliberate malice threatening the kaldorei heartland.",sp=1}},faq={{q="Who is Sethir the Ancient?",a="Sethir the Ancient is a satyr hiding on a bough near the northern edge of Teldrassil's Oracle Glade. He has defeated armed attackers and turned away peaceful inquiries from those seeking what he knows about the island's corruption.",al={"sethir","who is sethir","satyr in oracle glade"},it="target"},{q="Why does Syurna want Sethir's journal?",a="Syurna believes Sethir's journal holds clues to the unnatural sickness spreading through Teldrassil. Its pages describe his activities and the dark taint.",al={"why sethir journal","syurna objective","what is in the journal"},it="motive"},{q="What does the journal reveal upon completion?",a="Sethir's journal links the sickness in Teldrassil's boughs to the demonic blight gripping Darkshore's ancient forests and coastlines across the channel.",al={"journal lore","what did sethir find","darkshore connection"},sp=1,it="item"},{q="Where is this quest received?",a="Syurna, the rogue trainer in Darnassus, gives you this work after an initial assessment of your abilities.",al={"where do i get destiny calls","destiny calls questgiver","who gives destiny calls"},it="place",gp=true},{q="Where should adventurers go after completing this mission?",a="Syurna says nothing more can be done here about the matter. She rewards you with a blade for your service to Teldrassil.",al={"what comes next","next step after destiny calls","after sethir"},sp=1,it="next_step",gp=true},{q="Why is a rogue trainer handling forest corruption instead of druids?",a="Force and druidic diplomacy have both failed against Sethir, with deadly results. Syurna turns to stealth and infiltration after open efforts end in bloodshed.",al={"why rogue quest","why syurna","why not cenarion circle"},it="why_me"}},ang={["class:Rogue"]="As a rogue, you test your skill at taking sensitive intelligence from under a dangerous satyr's nose, at the direction of Darnassus's stealth trainers.",["race:NightElf"]="As a kaldorei defender, you learn that Darkshore's ancient curse has crossed the sea into Teldrassil, threatening your sacred refuge.",["faction:Alliance"]="As an Alliance defender, you learn that corruption in Teldrassil's woods reaches beyond the island, toward the northern lands of Kalimdor."},kw={"darkshore","darnassus","destiny calls","journal","oracle glade","satyr","sethir the ancient","syurna","teldrassil"},rel={"npc:syurna","subzone:oracle-glade","zone:darkshore","topic:satyr","quest:940","quest:397"},m={start="Syurna",level="10",faction="Alliance",id=2242,ri={"Sethir's Journal"}},src={"Destiny Calls"}}
E["quest:2259"] = {t="quest",n="Erion Shadewhisper",z="darnassus",s="Jannok Breezesong sends promising rogues from Teldrassil to Darnassus. At the Cenarion Enclave, Erion Shadewhisper points them toward work beyond the forests.",h="Jannok Breezesong sends promising rogues from Teldrassil to Darnassus.",sec={{t="A Summons to the Enclave",b="Jannok Breezesong sends you from Teldrassil to find Erion Shadewhisper in Darnassus. You need not worry about being sent to the exacting trainer Syurna. Erion waits in the Cenarion Enclave, where he handles work that calls for a quieter touch.",sp=0},{t="Eyes on the Horizon",b="Erion Shadewhisper marks a change for rogues in night elf lands. Teldrassil's forests can no longer contain your duties. Erion sends capable hands into a wider, more dangerous world, toward work across the sea.",sp=0}},faq={{q="Who sends you to find Erion Shadewhisper?",a="Jannok Breezesong sends you to Darnassus to speak with Erion Shadewhisper at the Cenarion Enclave.",al={"quest giver","who starts erion shadewhisper","jannok breezesong quest"},it="people"},{q="Where is Erion Shadewhisper located?",a="Erion Shadewhisper is in the Cenarion Enclave in Darnassus, among the trees on the enclave's upper tiers.",al={"erion location","where is erion","where to find erion shadewhisper"},it="place",gp=true},{q="Why does Jannok mention Syurna?",a="Syurna is a prominent rogue trainer in Darnassus, known for stern and demanding lessons. Jannok reassures you with a lighthearted quip that you are not in trouble or being sent to her for training.",al={"who is syurna","why not syurna","jannok syurna line"}},{q="What happens after reporting to Erion?",a="After your report, Erion gives you his next task, Erion's Behest, and sends you beyond Teldrassil to broaden your reach in Kalimdor.",al={"what next","erion follow up","quest after erion shadewhisper"},it="next_step"},{q="What kind of work does Erion oversee?",a="Erion directs new rogues in Darnassus and connects local agents with wider Alliance operations.",al={"is erion a rogue trainer","erion shadewhisper role","what does erion do"},it="purpose"},{q="Why is a rogue handler stationed in the Cenarion Enclave?",a="The Cenarion Enclave is known for druids and nature worship. Its trees offer secluded places for stealthy agents to meet and conduct business away from the Temple of the Moon.",al={"cenarion enclave rogue","why druid area for rogue"},it="why_here"},{q="Why does Jannok Breezesong send you to Erion?",a="Jannok Breezesong is not assigning you a task of his own, but acting as a messenger. Erion Shadewhisper specifically requested your presence at the Cenarion Enclave to test your abilities and dispatch you beyond Teldrassil as your training advances.",al={"why does jannok send you","jannok breezesong motive","why see erion shadewhisper"},it="motive",add="8fe8a3c2"}},ang={["class:Rogue"]="As a rogue, you leave novice work on Teldrassil and report to Erion Shadewhisper for work that calls for finesse beyond the starting forests.",["race:NightElf"]="As a night elf shadow-stalker, you report to Erion in Darnassus as you move from local warding to wider duties across the continent.",["faction:Alliance"]="As an Alliance operative in northern Kalimdor, you coordinate with Darnassus handlers before venturing into contested territory."},kw={"cenarion enclave","darnassus","erion shadewhisper","erion's behest","jannok breezesong","rogue breadcrumb","syurna"},rel={"quest:2260","npc:jannok-breezesong","subzone:cenarion-enclave","zone:darnassus","npc:syurna"},m={start="Jannok Breezesong",["end"]="Erion Shadewhisper",level="16",faction="Alliance",id=2259},src={"Erion Shadewhisper (quest)"}}
E["quest:2260"] = {t="quest",n="Erion's Behest",z="darnassus",s="Across the Great Sea, Erion's Behest carries a summons to promising night elf rogues in Darnassus. Erion Shadewhisper sees their growing skill in stealth and sends them to Stormwind City to report to Stormwind Intelligence.",h="Across the Great Sea, Erion's Behest carries a summons to promising night elf rogues in Darnassus.",sec={{t="A Summons Across the Sea",b="Night elf rogues in Teldrassil's shadow train under mentors such as Erion Shadewhisper. When one shows exceptional talent, word reaches beyond the World Tree. Through Erion, Stormwind Intelligence, known as SI:7, invites the rogue across the Great Sea to the human capital.",sp=0},{t="Entering the Service of SI:7",b="The journey leads from northern Kalimdor through the docks of Darkshore or the Wetlands to Stormwind City. In the capital, you make your way to SI:7 headquarters in Old Town and report to Renzik \"The Shiv.\" He assesses newcomers and opens the way to advanced espionage, poison mastery, and covert operations for the Alliance.",sp=0}},faq={{q="Who sends me on this mission?",a="Erion Shadewhisper, the rogue trainer in Darnassus, sends you after your early deeds draw the attention of intelligence networks across the sea.",al={"quest giver","erion shadewhisper","who gave me this"},it="identity"},{q="Why is Stormwind Intelligence contacting a night elf?",a="The Alliance relies on SI:7 to coordinate covert intelligence and sabotage, alongside the night elves' own stealth traditions. Stormwind Intelligence seeks capable rogues of every Alliance race for its ranks.",al={"why si:7","why stormwind","why do humans care"},it="why_me"},{q="Where do I find Renzik 'The Shiv'?",a="Renzik \"The Shiv\" is inside SI:7 headquarters in Stormwind City's Old Town.",al={"renzik location","where is the shiv","find renzik"},it="target",gp=true},{q="Is this quest only for rogues?",a="Yes. This Alliance rogue assignment guides operatives from Kalimdor to Stormwind, the center of Alliance intelligence training.",al={"rogue only","can other classes do this","is this rogue quest"},gp=true},{q="What happens after meeting Renzik?",a="Reporting to Renzik brings you into SI:7's training operations in the Eastern Kingdoms, where specialized training and covert assignments await throughout the human lands.",al={"next quest","what do i get","after renzik"},it="next_step"},{q="How does a night elf get to Stormwind City at this stage?",a="You can sail from Auberdine in Darkshore straight across the sea to Stormwind Harbor.",al={"how to get to stormwind","travel to stormwind","path to stormwind"},it="arrival",gp=true},{q="Why does Erion Shadewhisper send you to Stormwind?",a="Erion Shadewhisper acts on a formal summons from Stormwind Intelligence. Your growing reputation as a rogue has reached human ears across the Great Sea, and SI:7 has asked for you specifically. Erion recognizes that the clandestine guild in Old Town offers specialized training and resources far beyond what Teldrassil's quiet shadows provide, urging you to seize the opportunity rather than remain isolated in Darnassus.",al={"why send to stormwind","erion shadewhisper motive","why erions behest"},it="motive",add="4c3449b0"}},ang={["class:Rogue"]="As a rogue, you leave local Kalimdor scuffles for continental espionage and lethal training under SI:7.",["race:NightElf"]="As a night elf, leaving Darnassus and Teldrassil to serve human intelligence in Stormwind's stone alleys can bring a sharp culture shock.",["faction:Alliance"]="As an Alliance member, you can see SI:7 gather covert operations and deploy talented scouts from every member race where the crown needs them."},kw={"darnassus","erion shadewhisper","erion's behest","old town","renzik the shiv","rogue","si:7","stormwind"},rel={"npc:renzik-the-shiv","quest:2259","quest:2300","subzone:old-town","zone:stormwind","topic:stormwind-kingdom"},m={start="Erion Shadewhisper",["end"]="Renzik \"The Shiv\"",level="16",faction="Alliance",id=2260},src={"Erion's Behest"}}
E["quest:2518"] = {t="quest",n="Tears of the Moon",z="darnassus",s="At the Temple of the Moon, Priestess A'moora mourns Lady Sathrah's madness. Once cherished by Elune, the great spider has become dangerous, and the Sisterhood seeks to end her suffering and recover her sacred spinnerets.",h="At the Temple of the Moon, Priestess A'moora mourns Lady Sathrah's madness.",sec={{t="A Beloved Creature's Fall",b="In Darnassus's Temple of the Moon, Priestess A'moora grieves for Lady Sathrah. Sathrah was once blessed by Elune. Beneath the night sky, she wove delicate silver webs that caught the evening mist on Teldrassil's boughs. The Sisterhood of Elune gathered and kept the shimmering dew from those webs, which held healing powers for their sacred ministrations.",sp=0},{t="Mercy for Sathrah",b="Like much of the wildlife on the young World Tree, Lady Sathrah has recently fallen into madness. Her corruption threatens travelers and her own unhatched broods near Wellspring Lake in the northern reaches. The Sisterhood cannot cleanse her while she roams in a violent frenzy, so they have decided that ending her suffering is the only compassionate path. They mean to retrieve her silvery spinnerets and dedicate her remains at Elune's altar, praying the Moon Goddess grants her peace and a pure rebirth.",sp=1}},faq={{q="Who is Lady Sathrah?",a="Lady Sathrah is an ancient spider native to Teldrassil, once beloved of Elune. Her silvery webs caught the night mist, whose dew was known for its healing power.",al={"lady sathrah lore","who is lady sathrah","sathrah backstory","sathrah spider"},it="target"},{q="Why does Lady Sathrah have to be killed?",a="Lady Sathrah has fallen into a madness that has spread through Teldrassil's wildlife. Violent and dangerous to her offspring and others, she is to be slain as an act of mercy.",al={"why kill sathrah","can sathrah be saved","why is sathrah aggressive"},it="motive"},{q="Where is Lady Sathrah found?",a="Lady Sathrah is found in northern Teldrassil, near the shores of Wellspring Lake.",al={"lady sathrah location","where is sathrah","find sathrah"},it="place",gp=true},{q="What were Lady Sathrah's webs used for?",a="Lady Sathrah's webs caught the evening mist, forming silvery dew with healing powers. The Sisterhood of Elune kept it in the Temple of the Moon.",al={"tears of the moon meaning","sathrah webs use","silvery dew lore"},it="history"},{q="Who gives the quest Tears of the Moon?",a="Priestess A'moora gives Tears of the Moon from the Temple of the Moon in Darnassus to trusted Alliance adventurers.",al={"who gives tears of the moon","tears of the moon quest giver","priestess amoora"},it="origin",gp=true},{q="What will the priestesses do with Sathrah's spinnerets?",a="The priestesses plan to offer Sathrah's spinnerets to Elune at the temple altar. They ask the goddess to accept Sathrah's spirit, bless her, and grant her a peaceful rebirth.",al={"what happens to the spinnerets","spinnerets purpose","sacrifice to elune"},it="item"}},ang={["race:NightElf"]="As a Kaldorei, you know corruption in Teldrassil's wilds spares neither humble beasts nor Elune's sacred companions.",["class:Priest"]="As a priest of the Sisterhood of Elune, you know mercy can call for a sorrowful strike and a ritual offering to return a corrupted soul to the Goddess's embrace.",["class:Druid"]="As a druid, you see Sathrah's sudden ferocity and torment as another troubling sign of Teldrassil's imbalance. Restoring her spirit is an ecological necessity."},kw={"darnassus","elune","lady sathrah","priestess a'moora","silvery spinnerets","tears of the moon","teldrassil","temple of the moon","wellspring lake"},rel={"npc:priestess-a-moora","subzone:temple-of-the-moon","quest:2520","quest:2519","subzone:wellspring-lake","topic:elune","zone:darnassus","quest:940"},m={start="Priestess A'moora",level="12",faction="Alliance",id=2518,ri={"Silvery Spinnerets"}},src={"Tears of the Moon (Classic)"}}
E["quest:2519"] = {t="quest",n="The Temple of the Moon",z="darnassus",s="In Darnassus, Sister Aquinne calls for aid to a suffering ancient creature in Teldrassil. The Sisterhood of Elune needs help, and this is the opening call to a solemn ritual of mercy.",h="In Darnassus, Sister Aquinne calls for aid to a suffering ancient creature in Teldrassil.",sec={{t="A Plea in the Gardens",b="Sister Aquinne asks for help in the Temple Gardens. As a devoted servant of Elune, she speaks for her order: a venerable forest creature is suffering, and the Sisters cannot attend to it alone.",sp=0},{t="Into the Moon Temple",b="Sister Aquinne sends you southeast to the Temple of the Moon. Priestess A'moora coordinates the rituals and practical duties needed to address Teldrassil's troubled wildlife, preparing allies to carry out a sorrowful act of mercy.",sp=0}},faq={{q="Who starts the quest The Temple of the Moon?",a="Sister Aquinne begins the call for help. She stands outside in Darnassus's Temple Gardens district.",al={"quest giver temple of the moon","where to get temple of the moon quest","who gives the temple of the moon"},gp=true},{q="Where is Priestess A'moora located?",a="Priestess A'moora is inside the Temple of the Moon, just southeast of the Temple Gardens in Darnassus.",al={"where is priestess amoora","find amoora","priestess a'moora location"},gp=true},{q="What is the creature in need of help?",a="The creature is Sathrah, a revered spider of Teldrassil. Her plight leads to a ritual of mercy overseen by the priesthood.",al={"what creature needs help","who is the forest creature","what is this quest chain about"},it="target"},{q="Is this quest mandatory to continue the chain?",a="No. The Temple of the Moon is an optional breadcrumb. You can speak directly with Priestess A'moora inside the temple to take up the ritual tasks without first visiting Sister Aquinne.",al={"is temple of the moon required","can i skip temple of the moon","temple of the moon breadcrumb"},gp=true},{q="What quest follows after this one?",a="Priestess A'moora offers Tears of the Moon. She asks you to end Lady Sathrah's suffering and bring back her silvery spinnerets.",al={"next quest after temple of the moon","temple of the moon follow up","what comes next"},it="next_step",gp=true},{q="Why is the Sisterhood of Elune asking outsiders for help?",a="Corruption lingers in Teldrassil's flora and fauna, stretching the Sisterhood thin. The priestesses seek capable travelers who respect nature and the Goddess.",al={"why ask outsiders","why does the priesthood need help","sister aquinne motive"},it="why_me"},{q="Why does Sister Aquinne send you to Priestess A'moora?",a="Sister Aquinne recognizes that a venerable creature of Teldrassil's forests is suffering and in dire need of aid, but the matter requires the direct guidance of the priesthood. Knowing that a delicate, difficult task lies ahead, she directs capable travelers to Priestess A'moora inside the Temple of the Moon so they can receive proper instructions on how to intervene.",al={"why sister aquinne wants this","temple of the moon why send","sister aquinne purpose"},it="motive",add="e3d31678"}},ang={["race:NightElf"]="As a night elf, answering Sister Aquinne helps protect Teldrassil's sacred ecosystem and uphold the guidance of Elune's priesthood.",["class:Priest"]="As a priest, you may feel drawn to the Sisterhood's work in Darnassus, helping fellow servants of the divine with rites of healing and mercy.",["class:Druid"]="As a druid, you care deeply when a great creature of the wild is in distress. The call from the Temple Gardens asks you to help restore natural harmony."},kw={"darnassus","elune","priestess a'moora","sathrah","sister aquinne","sisterhood of elune","temple gardens","temple of the moon"},rel={"quest:2518","quest:2520","npc:sister-aquinne","npc:priestess-a-moora","subzone:temple-of-the-moon","subzone:temple-gardens","zone:darnassus"},m={start="Sister Aquinne",["end"]="Priestess A'moora",level="10",faction="Alliance",id=2519},src={"The Temple of the Moon (Classic)"}}
E["quest:2520"] = {t="quest",n="Sathrah's Sacrifice",z="darnassus",s="At the Temple of the Moon, Sathrah's Sacrifice gives a fallen creature's spirit a final rite. You carry Lady Sathrah's spinnerets to Elune's sacred waters, where the Priesthood seeks to cleanse her soul of corruption.",h="At the Temple of the Moon, Sathrah's Sacrifice gives a fallen creature's spirit a final rite.",sec={{t="A Cleansing in Sacred Waters",b="Priestess A'moora asks you to perform a final rite after Lady Sathrah is slain. The great spider fell to the dark madness spreading across Teldrassil, which twisted her peaceful nature into mindless aggression. The Priesthood of Elune seeks to redeem her fallen essence, not treat her death as a simple culling. You place her silvery spinnerets in the fountain at the heart of the Temple of the Moon. Its consecrated waters wash away the corruption and grant her release.",sp=0},{t="The Renewal of Sathrah",b="When the spinnerets touch the moonlit pool, Lady Sathrah's peaceful spirit rises, cleansed of the affliction that drove her mad. The Sisterhood of Elune sees the rite as her salvation. Though the loss of the great creature is deeply felt, night elven belief holds that sacred purification can let her be reborn one day with an uncorrupted spirit.",sp=1}},faq={{q="Who was Lady Sathrah?",a="Lady Sathrah was a great spider who lived on Teldrassil and succumbed to the corruption spreading through the World Tree's wildlife. The taint drove her mad, and she had to be slain so her remains could be sanctified.",al={"lady sathrah","who is sathrah","what is sathrah"},it="target"},{q="Where is the sacrifice offered?",a="You offer the sacrifice in the holy fountain at the center of the Temple of the Moon, the Sisterhood of Elune's central sanctuary in Darnassus.",al={"where do i put the sacrifice","fountain location","temple fountain"},it="place",gp=true},{q="What happens when you place the spinnerets in the fountain?",a="When you place the silvery spinnerets in the blessed waters, Sathrah's purified spirit appears briefly in the pool and walks freely and peacefully, signaling Elune's acceptance.",al={"what happens at the fountain","spirit of sathrah fountain"},sp=1},{q="Why did Lady Sathrah have to die?",a="The corruption in Lady Sathrah's mind ran too deep to heal while she lived. Priestess A'moora and the Sisterhood believed they could save her soul only by ending her suffering and cleansing her remains in Elune's holy waters.",al={"why kill sathrah","could sathrah be saved","sathrah madness"}},{q="Who gives the quest Sathrah's Sacrifice?",a="Priestess A'moora gives and concludes Sathrah's Sacrifice from the Temple of the Moon in Darnassus, overlooking the central chamber.",al={"quest giver","where to turn in","amoora location"},it="identity",gp=true},{q="What belief underpins this ritual for the night elves?",a="Night elves believe souls purified by the Mother Moon can be reborn into the natural world, their spirits renewed and free of corruption.",al={"night elf reincarnation","elune purification","rebirth lore"}},{q="Why does Priestess A'moora want this done?",a="Priestess A'moora seeks to lay Lady Sathrah peacefully to rest and purge the corruption that tormented the once-noble creature. By placing Sathrah's spinnerets into the sacred waters of the Temple of the Moon, Elune's grace can cleanse the lingering taint that drove the great spider mad, allowing her spirit to be redeemed and eventually reborn renewed.",al={"amoora motive","why offer the sacrifice","why does amoora want sathrah sacrifice"},it="motive",add="f4be164d"}},ang={["race:NightElf"]="As a night elf, you honor the flora and fauna of Kalimdor through this solemn rite. Even when a creature must be slain, its spirit is honored and cleansed through Elune's grace.",["class:Priest"]="As a priest, you see how Elune's holy light and sacred waters can mend spirits afflicted by madness and corruption.",["class:Druid"]="As a druid, you can find solace in knowing fallen beasts can return to the natural cycle through purification, even as Teldrassil suffers from sickness."},kw={"a'moora","darnassus","elune","fountain","lady sathrah","purification","sathrah","spinnerets","teldrassil","temple of the moon"},rel={"quest:2518","quest:2519","subzone:temple-of-the-moon","npc:priestess-a-moora","topic:elune"},m={start="Priestess A'moora",level="12",faction="Alliance",id=2520},src={"Sathrah's Sacrifice (quest)"}}
E["quest:26"] = {t="quest",n="A Lesson to Learn",z="darnassus",s="Mathrengyl Bearwalker sends young druids from Darnassus to Moonglade to learn the ways of water. There, they meet an elder of the Cenarion Circle and begin training in their aquatic aspect.",h="Mathrengyl Bearwalker sends young druids from Darnassus to Moonglade to learn the ways of water.",sec={{t="The Call of the Wild",b="Mathrengyl Bearwalker guides young night elf druids as they practice among Darnassus’s boughs. When an initiate shows a firm bond with nature and readiness for greater responsibility, Mathrengyl sends them toward mastery of the waters. Cenarius’s gifts demand focus, and learning to cross the depths without drowning calls for guidance from the Cenarion Circle’s elders.",sp=0},{t="Journey to Nighthaven",b="The initiate leaves Darnassus for Moonglade, an ancient sanctuary beneath Mount Hyjal. In Nighthaven, Dendrite Starblaze waits as an elder mentor of the Cenarion Circle. Starblaze judges whether young shapeshifters are ready for the trials that lead to aquatic form. Mastering water takes both physical resilience and mental resolve.",sp=0}},faq={{q="Who sends me on this quest?",a="Mathrengyl Bearwalker, a druid trainer in Darnassus’s Cenarion Enclave, sends you once your early druidic training has advanced enough.",al={"quest giver","who gives a lesson to learn","who starts this"},it="identity"},{q="What is the purpose of this quest?",a="This begins a druid’s path toward aquatic form. You travel to Moonglade for instruction and trials from the elder Dendrite Starblaze.",al={"why do this quest","aquatic form intro","what do i get"},it="purpose"},{q="Where is Dendrite Starblaze located?",a="Dendrite Starblaze lives in Nighthaven, on the northern shores of Lake Elune'ara in Moonglade.",al={"dendrite location","where is dendrite starblaze","find dendrite"},it="place",gp=true},{q="How do druids reach Moonglade for this quest?",a="Druids can use Teleport: Moonglade to travel directly to the sacred grove, guided by their spiritual attunement.",al={"how to get to moonglade","getting to nighthaven"},gp=true},{q="What comes after speaking to Dendrite Starblaze?",a="After you speak with Dendrite Starblaze, he sends you to the Trial of the Lake, where your endurance and clarity beneath the water will be tested.",al={"next quest","what's next","after a lesson to learn"},it="next_step"},{q="Why does Mathrengyl Bearwalker send you to Moonglade?",a="Mathrengyl Bearwalker has watched your growth and believes you are ready to expand your connection to the wild. The animal aspects gifted by Cenarius require deeper instruction than standard training offers. To learn the secrets of aquatic mastery, he directs you to Dendrite Starblaze and the Cenarion Circle in Nighthaven, where ancient druidic trials are overseen.",al={"why does mathrengyl send you","mathrengyl bearwalker motive","why go to moonglade"},it="motive",add="67389e7a"}},ang={["class:Druid"]="As a druid, this marks a milestone in your training and opens the way to commune with Cenarius's gifts beneath the waves.",["race:NightElf"]="As a kaldorei of Darnassus, answering the Cenarion Circle’s call in Moonglade honors tradition and connects you with your ancient teachers."},kw={"a lesson to learn","aquatic form","darnassus","dendrite starblaze","druid quest","mathrengyl bearwalker","moonglade","nighthaven"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","subzone:nighthaven","quest:5921","quest:5061","topic:cenarion-circle","topic:cenarius","topic:druid"},m={start="Mathrengyl Bearwalker",["end"]="Dendrite Starblaze",level="16",faction="Alliance",id=26},src={"A Lesson to Learn (Alliance)"}}
E["quest:3370"] = {t="quest",n="In Nightmares",z="darnassus",s="Falla Sagewind sends a glowing shard to the elder druids in Darnassus. Its core holds the essence of the Emerald Dream, clouded by dark visions.",h="Falla Sagewind sends a glowing shard to the elder druids in Darnassus.",sec={{t="A Troubling Revelation",b="Falla Sagewind finds more than a simple crystal in the glowing shard recovered from the depths of Wailing Caverns. She recognizes the pure essence of the Emerald Dream within it, yet the shard shows fearful visions instead of the harmony of nature. Shaken by what she sees, Falla refuses to study it further. She sends you to carry the shard to the senior druids of the Cenarion Circle.",sp=0},{t="Whispers in the Cenarion Enclave",b="Mathrengyl Bearwalker, an experienced druid in Darnassus's Cenarion Enclave, examines the shard you bring. Calm curiosity gives way to unease as he looks into its core. Mathrengyl realizes the corruption in the Barrens is connected to disturbances deep in the Emerald Dream. He quiets further discussion, warning that such terrors are not for common ears, and takes custody of the shard to study the shadow spreading through the Dream.",sp=1}},faq={{q="What is the Nightmare Shard?",a="The Nightmare Shard is a crystal holding a piece of the Emerald Dream's essence, first found as a mysterious glowing shard. It shows dark visions instead of nature's harmony, revealing that a sinister presence has entered the Dream.",al={"what is nightmare shard","glowing shard lore","emerald dream shard"},sp=1,it="item"},{q="Who is Falla Sagewind?",a="Falla Sagewind is a tauren druid who studies the lore of nature and examines strange relics found in the wilds. After recognizing the shard's terrifying origin, she sends travelers to the senior druids in Darnassus.",al={"falla sagewind","who is falla"},it="identity"},{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is an elder druid trainer of the Cenarion Circle at the Cenarion Enclave in Darnassus. He mentors druids and investigates grave spiritual threats to nature and the Emerald Dream.",al={"mathrengyl bearwalker","bearwalker darnassus","who is mathrengyl"},it="identity"},{q="Why is Mathrengyl so secretive about the shard?",a="Mathrengyl is secretive because the shard shows corruption in the Emerald Dream, a sacred realm of nature guided by the Green Dragonflight and sleeping druids. Such a threat is a profound spiritual crisis, and the Cenarion Circle is reluctant to expose it to the public.",al={"why secret","what does mathrengyl hide","why won't mathrengyl talk"},sp=1,it="purpose"},{q="Where does this quest chain begin?",a="The story begins with The Glowing Shard, an item found on Mutanus the Devourer at the end of Wailing Caverns. Scholars eventually trace the shard's ominous origin toward Darnassus or Thunder Bluff.",al={"in nightmares prereq","where did this start","how to get in nightmares"},it="history",gp=true},{q="Do Horde players have an equivalent quest?",a="Yes. Alliance travelers bring their findings to Mathrengyl Bearwalker in Darnassus, while Horde travelers report to Hamuul Runetotem on the Elder Rise in Thunder Bluff. Both learn of the same troubling news about the Emerald Dream.",al={"horde version","is there a horde in nightmares","in nightmares horde"},gp=true},{q="Why does Falla Sagewind want the Nightmare Shard delivered?",a="Falla Sagewind recognized that the shard contains the essence of the Emerald Dream, but the vision she glimpsed within was deeply twisted into a nightmare. Alarmed by what she saw and knowing such ominous corruption lies far beyond her understanding, she insists that it be examined by a wise druid of the Cenarion Circle in Darnassus immediately.",al={"why send the shard to darnassus","why does falla want this done","falla sagewind motive"},it="motive",add="da5fa45e"}},ang={["class:Druid"]="As a druid, you learn that the sacred Emerald Dream is not the untouched sanctuary you were taught to commune with. The shard hints at danger within it.",["faction:Alliance"]="As an Alliance traveler, you carry the relic into Darnassus and bring the night elf leadership an early glimpse of corruption spreading beneath the world's surface.",["race:NightElf"]="As a night elf, you venerate the sleeping realm where Malfurion Stormrage resides. A waking nightmare within its essence strikes at the heart of your spiritual heritage."},kw={"cenarion circle","cenarion enclave","darnassus","emerald dream","falla sagewind","glowing shard","in nightmares","mathrengyl bearwalker","nightmare shard"},rel={"quest:6981","npc:mathrengyl-bearwalker","npc:falla-sagewind","topic:cenarion-circle","topic:emerald-dream","zone:darnassus","topic:druid","quest:3369"},m={start="Falla Sagewind",["end"]="Mathrengyl Bearwalker",level="25",faction="Alliance",id=3370},src={"In Nightmares (Alliance)"}}
E["quest:5061"] = {t="quest",n="Aquatic Form",z="darnassus",s="You return to Darnassus with the restored Pendant of the Sea Lion. The rite teaches Alliance druids to attune their spirits to deep waters.",h="You return to Darnassus with the restored Pendant of the Sea Lion.",sec={{t="A Sacred Bond with the Depths",b="For Cenarion Circle initiates, shapeshifting joins the druid’s spirit to the wild aspects of Azeroth. After enduring trials in the dark coastal depths and in Moonglade, young night elf druids receive the assembled Pendant of the Sea Lion from Dendrite Starblaze. They carry the sacred token back to Teldrassil as proof of their respect for the laws of air, water, and breath.",sp=0},{t="Return to Darnassus",b="Mathrengyl Bearwalker awaits your return in the Cenarion Enclave. The trials along the coasts of Darkshore and Westfall demand endurance and attunement. Presenting the completed pendant shows Bearwalker that your mind and body are ready to shed their mortal skin and take the swift, breathing form of the sea lion.",sp=0}},faq={{q="What is the purpose of this quest?",a="Presenting the restored Pendant of the Sea Lion to Mathrengyl Bearwalker in Darnassus completes an Alliance druid’s training in Aquatic Form. The pendant shows that the druid is ready to learn this aquatic shape.",al={"why do this quest","aquatic form purpose","what does this quest give"},it="purpose"},{q="Who sends you back to Darnassus?",a="Dendrite Starblaze sends you back to Teldrassil from Moonglade after you complete the Trial of the Sea Lion. Starblaze is an elder of the Cenarion Circle.",al={"who gives this quest","quest giver","dendrite starblaze"},it="identity"},{q="Who completes your training in Darnassus?",a="Mathrengyl Bearwalker, the druid trainer in Darnassus’s Cenarion Enclave, receives your pendant and teaches you the aquatic aspect.",al={"quest hand in","who turns in aquatic form","mathrengyl bearwalker"},it="identity"},{q="What is the Pendant of the Sea Lion?",a="The Pendant of the Sea Lion is a sacred talisman made by joining two trial pendants recovered from watery depths off Darkshore and Westfall. It proves a druid has mastered the endurance and patience required of sea creatures.",al={"what is the pendant","pendant of the sea lion lore"},it="item"},{q="Do Horde druids do this exact quest?",a="No. Tauren druids also face trials in Moonglade to earn their aquatic aspect, then return to Turak Runetotem on the mesas of Thunder Bluff instead of Darnassus.",al={"can tauren do this","is this quest alliance only","horde version"},gp=true},{q="Where in Darnassus is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is in the Cenarion Enclave, in Darnassus’s northwestern district atop the boughs of Teldrassil.",al={"where is mathrengyl","darnassus druid trainer location"},it="place",gp=true},{q="Why does Dendrite Starblaze send you back to Darnassus?",a="Dendrite Starblaze has guided you through the sacred trials of Moonglade, but it is the duty of your local mentor, Mathrengyl Bearwalker, to bestow the final lessons. By returning with the assembled Pendant of the Sea Lion, you provide proof of your readiness and discipline, allowing Mathrengyl to complete your training and grant you mastery over the aquatic aspect.",al={"why does dendrite send you back","dendrite starblaze motive","why go back to darnassus"},it="motive",add="d3754c26"}},ang={["class:Druid"]="As a druid, this rite marks a step in your communion with nature. Aquatic Form lets you move swiftly underwater and breathe beneath the surface indefinitely.",["race:NightElf"]="As a night elf, returning from Moonglade’s timeless woods to Teldrassil’s youthful crown affirms your duty to protect Azeroth’s wilderness amid shifting balance.",["faction:Alliance"]="As an Alliance druid, your trials prepare you to scout across lakes, rivers, and coastal shores with ease."},kw={"aquatic form","cenarion enclave","darnassus","dendrite starblaze","mathrengyl bearwalker","moonglade","pendant of the sea lion","sea lion"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","topic:druid","zone:darnassus","quest:5921","quest:31"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="16",faction="Alliance",id=5061},src={"Aquatic Form (Alliance)"}}
E["quest:5627"] = {t="quest",n="Stars of Elune",z="darnassus",s="In Darnassus, night elf acolytes are called to the Temple of the Moon after proving their devotion to their people. There, the Sisterhood of Elune teaches them sacred arts of their faith.",h="In Darnassus, night elf acolytes are called to the Temple of the Moon after proving their devotion to their...",sec={{t="A Rite of Devotion",b="Night elf priests draw their holy power from Elune, their goddess, while humans and dwarves turn to the Light. When an acolyte serves the realm with steadfast devotion, the Sisterhood in Darnassus takes notice. The acolyte is summoned to the Temple of the Moon and judged ready for deeper communion. There, the priest learns sacred spells passed down through thousands of years of worship.",sp=0},{t="Gifts of the Moon Goddess",b="Priestess Alathea calls the initiate to receive instruction in holy mysteries of the night elf faith, including Starshards. These spells channel the radiant wrath and grace of the White Lady. The teaching marks an acolyte's passage beyond basic training, ready to venture beyond Teldrassil's protective canopy in Elune's name.",sp=0}},faq={{q="What is the purpose of this quest?",a="The Sisterhood of Elune formally recognizes an initiate's devotion. Priestess Alathea teaches the young priest night elf spells such as Starshards.",al={"stars of elune quest","what do i get","why do this quest"},it="purpose"},{q="Who offers Stars of Elune?",a="Priestess Alathea, a leader of the Sisterhood of Elune, completes the rite at the Temple of the Moon in Darnassus.",al={"who gives stars of elune","quest giver stars of elune","where is alathea"},it="identity"},{q="Why is this quest restricted to night elves?",a="The rites belong to the Sisterhood of Elune, the ancient priesthood of night elf faith. Kaldorei priests draw their distinct magic from communion with Elune, while other Alliance priesthoods study the Holy Light.",al={"can humans do this","is this night elf only","who can do stars of elune"},it="people"},{q="Where does this quest lead within the priest storyline?",a="After 'Returning Home,' an aspiring priest who has helped across Teldrassil returns to the capital for further instruction at the Temple of the Moon.",al={"what comes before stars of elune","stars of elune prereq","returning home quest"},it="next_step"},{q="What kind of magic does Elune bestow on her priests?",a="Priests devoted to Elune weave moonlight, starlight, and shadow. Through rites such as Starshards, kaldorei worshippers call down celestial fire upon enemies, joining divine judgment with astral wrath.",al={"elune spells","night elf priest magic","starshards lore"},it="power"},{q="Where in Darnassus does this take place?",a="The rite takes place inside the Temple of the Moon, a marble sanctuary above Darnassus's southern quarter and the religious heart of the kaldorei nation.",al={"stars of elune location","where is priestess alathea","temple of the moon location"},it="place"},{q="Why does Priestess Alathea send for you?",a="Priestess Alathea watches over the growth of nascent night elf priests in Darnassus. Once you have established your devotion and returned from early service, she calls upon you to confirm that you are truly ready for deeper mysteries. Her aim is to bestow Starshards, a divine gift of celestial wrath granted by the Moon Goddess only to faithful kaldorei priests who have proven themselves worthy of her gaze.",al={"why does priestess alathea want this","alathea motive","why stars of elune"},it="motive",rc="Night Elf",add="b42d6b57"}},ang={["class:Priest"]="As a priest, this rite marks the path of kaldorei priests and brings you astral spells granted by the Moon Goddess.",["race:NightElf"]="As a kaldorei, your service to Elune is bound to civic and cultural life. Answering the Sisterhood's summons marks your coming of age in service to Teldrassil.",["faction:Alliance"]="As an Alliance member, you stand among human and dwarven priests of the Holy Light, while night elf devotion to Elune brings ancient celestial magic to the Alliance."},kw={"darnassus","priestess alathea","returning home","sisterhood of elune","stars of elune","starshards","temple of the moon"},rel={"npc:priestess-alathea","topic:elune","quest:5628"},m={start="Priestess Alathea",level="10",faction="Alliance",id=5627},src={"Stars of Elune"}}
E["quest:5628"] = {t="quest",n="Returning Home",z="darnassus",s="In Goldshire, a novice night elf priest receives a call to return home. The novice has wandered as far as Elwynn Forest, where Priestess Josetta relays an urgent message from Darnassus: return to the Temple of the Moon and continue spiritual training under Priestess Alathea.",h="In Goldshire, a novice night elf priest receives a call to return home.",sec={{t="A Word in Goldshire",b="Night elves are an unusual sight in Elwynn Forest, and a young acolyte among its human settlements draws attention. When you arrive in Goldshire, Priestess Josetta greets you warmly with news. A Sister of Elune has traveled across continents seeking you, bearing an urgent command from the Temple of the Moon. It is time to return to Kalimdor and advance your calling.",sp=0},{t="The Call of the Temple",b="At the heart of Darnassus stands the Temple of the Moon, center of night elf faith and leadership. Priestess Alathea and High Priestess Tyrande Whisperwind oversee the Sisterhood’s instruction, watching their disciples even when curiosity carries them overseas. When you return, the priestesses welcome you with motherly concern and immediately set you to deeper studies of the Moon Goddess’s celestial mysteries.",sp=0}},faq={{q="Why is a night elf priest being summoned from human lands?",a="Young night elf priests who travel to the Eastern Kingdoms remain bound to their sacred order in Teldrassil. Priestess Alathea tracks their progress and calls them back to the Temple of the Moon when they are ready to learn higher rites of Elune.",al={"why am i called back","why returning home","priest quest goldshire"},it="why_me"},{q="Who is Priestess Josetta?",a="Priestess Josetta is the human priest trainer at the Lion's Pride Inn in Goldshire. She serves the Holy Light and respects visiting kaldorei acolytes, acting as a liaison when emissaries from Darnassus seek their wayward kin.",al={"who gives returning home","goldshire priest trainer","priestess josetta"},it="identity"},{q="Who is Priestess Alathea?",a="Priestess Alathea is a senior Sister of Elune who trains acolytes at the Temple of the Moon in Darnassus. She works with High Priestess Tyrande Whisperwind to monitor novice night elf priests’ growth and spiritual dedication.",al={"who is alathea","temple priest trainer","priestess alathea"},it="identity"},{q="What happens after returning to Darnassus?",a="When you report to Priestess Alathea at the Temple of the Moon, she welcomes you home and gives you your next task, Stars of Elune, which explores the sacred power granted by the goddess.",al={"what comes next","next quest after returning home","followup quest"},it="next_step"},{q="How does this differ from the normal training path?",a="This alternate path guides night elf priests who choose to train in human lands such as Elwynn Forest back to their racial trainers in Darnassus, where they can learn their race-specific priestly abilities.",al={"do all priests do this","is this quest mandatory","elwynn priest quest"}},{q="How did the messenger find an acolyte all the way in Elwynn Forest?",a="A Sister of Elune travels from Darnassus to the Eastern Kingdoms and leaves word with Alliance trainers such as Priestess Josetta in Goldshire. Josetta watches for the traveling novice and directs them home.",al={"how did they know i was here","who tracked me to goldshire"}},{q="Why does Priestess Josetta want you to return to Darnassus?",a="Priestess Josetta is not directing your training herself; she is passing along an urgent summons from your own people. A priestess from Darnassus came searching specifically for you in Goldshire, asking that you report back to Priestess Alathea at the Temple of the Moon. Josetta recognizes how far you have journeyed from home at an early age, but as a fellow servant of the divine, she knows that advanced spiritual instruction from your mentors takes precedence over wandering foreign lands.",al={"why does josetta send you back","priestess josetta motive","why return to darnassus"},it="motive",add="50552740"}},ang={["class:Priest"]="Every priest order has deep roots in tradition. As a kaldorei acolyte, you can advance in the lunar rites only with the senior priestesses’ approval at the Temple of the Moon.",["race:NightElf"]="As a night elf, you may travel far across the sea to the lands of the younger races, but Teldrassil and Elune’s blessings draw you back to your sacred sanctuaries.",["faction:Alliance"]="As an Alliance member, you can see growing cooperation between the Church of the Holy Light in Elwynn and the Sisterhood of Elune in Darnassus. Their hospitality strengthens the bonds between Alliance races."},kw={"darnassus","elune","goldshire","priestess alathea","priestess josetta","returning home","stars of elune","temple of the moon"},rel={"quest:5627","npc:priestess-alathea","npc:priestess-josetta","subzone:temple-of-the-moon","zone:darnassus","topic:elune","quest:2519"},m={start="Priestess Josetta",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5628},src={"Returning Home (Elwynn Forest)"}}
E["quest:5629"] = {t="quest",n="Returning Home",z="darnassus",s="In Darnassus, Returning Home brings young night elf priests before the leaders of their faith. After proving themselves in Teldrassil’s wilds, they are summoned to the Temple of the Moon to meet Priestess Alathea and High Priestess Tyrande Whisperwind.",h="In Darnassus, Returning Home brings young night elf priests before the leaders of their faith.",sec={{t="A Summons from Darnassus",b="Priests tending the wounded and cleansing corruption around Dolanaar draw the Sisterhood of Elune’s notice. Trainer Laurna Morninglight intercepts promising initiates with word that Priestess Alathea has asked to meet them. Aid to local settlements matters, but each devotee must also deepen their communion with the Moon Mother and answer the faith’s higher calling.",sp=0},{t="Within the Temple of the Moon",b="The road leads from Teldrassil’s boughs to the Temple of the Moon in Darnassus. The sanctuary rises above the city in Elune’s gentle glow. It is the kaldorei’s chief house of worship and spiritual capital. An invitation into its halls means an initiate is recognized by the priesthood’s leaders, no longer treated only as a young student.",sp=0},{t="The Favor of Tyrande and Alathea",b="Priestess Alathea greets returning initiates warmly. She says she and High Priestess Tyrande Whisperwind take pride when initiates venture into the uncertain world and return unharmed. This homecoming begins deeper sacred trials under Alathea’s direct guidance.",sp=0}},faq={{q="Who offers the quest Returning Home?",a="Laurna Morninglight, the priest trainer in Dolanaar, summons young night elf priests after they gain enough training and experience.",al={"who gives returning home","returning home quest giver","laurna morninglight quest"},gp=true},{q="Where is Priestess Alathea located?",a="Priestess Alathea is in the Temple of the Moon in Darnassus, near the center of the night elf capital on Teldrassil.",al={"where is alathea","priestess alathea location","temple of the moon priestess"},gp=true},{q="Why does Priestess Alathea want to see me?",a="The Sisterhood of Elune’s elders have noticed your service in Teldrassil’s wilderness. Alathea believes you are ready for advanced instruction and greater spiritual duties.",al={"why summoned to darnassus","why go to temple of the moon"},it="why_wanted"},{q="Can any class take this quest?",a="No. Only night elf priests receive this summons as part of their early training and initiation into the Sisterhood’s higher duties.",al={"is returning home for all classes","can druids do returning home","priest only quest"},gp=true},{q="What quest follows Returning Home?",a="After you report to Priestess Alathea, she gives you Stars of Elune to undertake next.",al={"what comes after returning home","returning home followup","next quest"},it="next_step",gp=true},{q="What is the Temple of the Moon's significance to night elves?",a="The Temple of the Moon is Elune’s chief house of worship. High Priestess Tyrande Whisperwind guides the Sisterhood and the kaldorei nation from there.",al={"temple of the moon lore","darnassus moon temple"},it="place"},{q="Why does Laurna Morninglight send you back to Darnassus?",a="Laurna Morninglight is not sending you away on an urgent crisis, but rather acting as a mentor guiding your growth. Priestess Alathea sent word specifically requesting your presence at the Temple of the Moon. The priesthood's elders have noticed your dedication and service to the night elven people across Teldrassil, and they believe you have grown strong enough to undertake greater spiritual duties in service of Elune.",al={"why does laurna send me back","laurna morninglight returning home motive","why return to darnassus"},it="motive",rc="Night Elf",add="1b068d1d"},{q="Why does Priestess Alathea specifically summon you?",a="You are summoned because of your own proven devotion and training. Priestess Alathea and High Priestess Tyrande take personal interest in the development of young acolytes who venture out to aid their people. Having demonstrated your capabilities and spiritual maturity in the field, the leadership at the Temple of the Moon considers you ready to receive more advanced sacred responsibilities that ordinary acolytes or temple guards cannot fulfill.",al={"why does alathea want me","why me returning home","why summon my priest"},it="why_me",rc="Night Elf",add="d7077bd4"}},ang={["class:Priest"]="As a priest, you are answering a summons that marks your passage from forest acolyte to servant of the Sisterhood of Elune, called to Darnassus.",["race:NightElf"]="As a kaldorei, you answer the Temple of the Moon’s call and renew your ties to your people’s traditions under the watch of High Priestess Tyrande Whisperwind."},kw={"darnassus","dolanaar","elune","laurna morninglight","priestess alathea","returning home","sisterhood of elune","teldrassil","temple of the moon","tyrande"},rel={"npc:laurna-morninglight","npc:priestess-alathea","subzone:temple-of-the-moon","zone:darnassus","quest:5627","topic:elune","quest:2519","quest:92472"},m={start="Laurna Morninglight",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5629},src={"Returning Home (Teldrassil)"}}
E["quest:5630"] = {t="quest",n="Returning Home",z="darnassus",s="A summons reaches wandering night elf priests in Dun Morogh, calling them back to Darnassus. Maxan Anvol, the dwarven priest trainer, directs them to report to Priestess Alathea at the Temple of the Moon.",h="A summons reaches wandering night elf priests in Dun Morogh, calling them back to Darnassus.",sec={{t="A Summons Across the Sea",b="In Kharanos, Maxan Anvol takes note of the night elf's fortitude amid Dun Morogh's bitter cold, far from Teldrassil's serene forests. The dwarven priest trainer brings urgent word: a priestess of Elune passed through looking for the elf, carrying orders from Darnassus that demand an immediate return.",sp=0},{t="The Temple of the Moon",b="The road leads across the sea to the Temple of the Moon in Darnassus, among Teldrassil's sacred boughs. Priestess Alathea welcomes the traveler back to the Sisterhood of Elune, relieved to see another devotee return unscathed from foreign lands. She swiftly prepares the priest for the next rites of devotion, beginning with the Stars of Elune.",sp=0}},faq={{q="Who sends me on this quest?",a="Maxan Anvol, the dwarven priest trainer in Kharanos, delivers the message. He says another night elf priestess recently passed through Dun Morogh seeking you.",al={"quest giver","who starts returning home","maxan anvol"},it="identity"},{q="Where do I need to go to complete it?",a="Return to Darnassus, on Teldrassil in northern Kalimdor. Priestess Alathea awaits inside the Temple of the Moon.",al={"turn in location","where is priestess alathea","where do i go"},it="place",gp=true},{q="Why is the Temple of the Moon calling me back?",a="Priestess Alathea and High Priestess Tyrande Whisperwind monitor the development of young initiates. Alathea wants to confirm your safety, hear of your travels under Elune's grace, and begin your next stage of spiritual training with the Stars of Elune.",al={"why returning home","priest summons reason"},it="purpose"},{q="What happens after speaking with Priestess Alathea?",a="When you report your return, Priestess Alathea offers Stars of Elune, continuing your foundational rites as a Kaldorei priest.",al={"next quest","what comes next"},it="next_step"},{q="Why would a night elf be in Dun Morogh at level 10?",a="Night elf adventurers can sail from Darkshore to Menethil Harbor in the Eastern Kingdoms. There, they explore Alliance lands or adventure alongside dwarf and gnome comrades.",al={"why dun morogh","night elf in ironforge"},it="arrival"},{q="Is this quest available to other races?",a="No. This is for night elf priests training in dwarven lands, and it directs them back to their cultural and spiritual home in Darnassus.",al={"can dwarves do returning home","who can take this quest"},gp=true},{q="Why does Maxan Anvol want me to return to Darnassus?",a="Maxan Anvol has no personal stake in the affairs of the Temple of the Moon. He is simply passing along an urgent summons. A night elf priestess recently passed through Dun Morogh looking specifically for you, requesting that you report back to Priestess Alathea in Darnassus on vital business. As a friendly priest trainer who admires your resilience in the bitter dwarf snows, Maxan is merely doing a traveling sister a courtesy by ensuring the message reaches your ears.",al={"why does maxan send me","maxan anvol motive","why return to darnassus"},it="motive",add="39744d7e"}},ang={["class:Priest"]="As a priest, you return from distant lands to the leadership of the Sisterhood of Elune, keeping your devotion to the Moon Goddess steadfast.",["race:NightElf"]="As a Kaldorei braving Dun Morogh's frigid winds, you receive a welcome call back to Teldrassil's familiar sanctuaries and ancestral forests."},kw={"darnassus","dun morogh","kharanos","maxan anvol","priestess alathea","returning home","stars of elune","teldrassil","temple of the moon"},rel={"npc:maxan-anvol","npc:priestess-alathea","quest:5627","subzone:temple-of-the-moon","zone:darnassus","topic:elune","quest:5628","quest:2519"},m={start="Maxan Anvol",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5630},src={"Returning Home (Dun Morogh)"}}
E["quest:5631"] = {t="quest",n="Returning Home",z="darnassus",s="In human lands, a night elf priest receives a summons to return to Teldrassil. Brother Joshua delivers the message from Priestess Alathea, who calls the young priest to the Temple of the Moon in Darnassus for advanced guidance in Elune’s mysteries.",h="In human lands, a night elf priest receives a summons to return to Teldrassil.",sec={{t="A Summons Across Seas",b="Night elf priests sometimes travel to human lands such as Stormwind to share spiritual fellowship with the Church of the Holy Light. Their deepest ties remain with the Sisterhood of Elune. Brother Joshua tells an acolyte that a night elf emissary has come searching for them. Their early travels are over, and their home temple calls them back for deeper training with High Priestess Tyrande Whisperwind’s inner circle.",sp=0},{t="The Temple of the Moon",b="Across the sea, Darnassus welcomes the returning priest at the Temple of the Moon. Priestess Alathea greets the acolyte warmly and celebrates their safe passage through a troubled world. Their return brings joy to Alathea and Tyrande, while more demanding spiritual trials await.",sp=0}},faq={{q="Why is Brother Joshua giving instructions to a night elf priest?",a="Brother Joshua serves the Church of the Holy Light in human lands, where young Alliance priests often train together. A sister of Elune came to his halls with a message recalling you to Darnassus, and Joshua passes on the summons.",al={"why brother joshua","brother joshua night elf","who sends me home"},it="motive"},{q="Who is Priestess Alathea?",a="Priestess Alathea is a senior member of the Sisterhood of Elune at the Temple of the Moon in Darnassus. She works with High Priestess Tyrande Whisperwind and oversees the training and advancement of promising night elf priests.",al={"priestess alathea","alathea darnassus","who is alathea"},it="identity"},{q="What happens after reaching the Temple of the Moon?",a="At the Temple of the Moon, Priestess Alathea welcomes you home and begins your next rite of passage. Stars of Elune deepens your communion with the Moon Goddess.",al={"quest after returning home","what is next","stars of elune quest"},it="next_step"},{q="Can any Alliance race do this quest?",a="This summons is for night elf priests who have traveled far from Kalimdor during their early training. It calls you home to study the traditions of your people’s priesthood with the Sisterhood of Elune.",al={"is this night elf only","can humans do returning home","who can pick up returning home"},gp=true},{q="Where is the Temple of the Moon located?",a="The Temple of the Moon is in Darnassus’s southern district, atop the boughs of Teldrassil. It is the spiritual heart of night elf culture and the seat of power for High Priestess Tyrande Whisperwind.",al={"temple of the moon location","where is the temple","where is alathea"},it="place",gp=true},{q="Why does Alathea mention Tyrande Whisperwind?",a="Tyrande Whisperwind is the High Priestess of Elune and spiritual leader of the night elves. Senior priestesses such as Alathea act on her behalf, tracking and guiding novices who represent their faith abroad according to Tyrande’s standards.",al={"why tyrande mentioned","tyrande whisperwind priestess","alathea and tyrande"},it="ties"},{q="Why is Priestess Alathea calling for me specifically?",a="Priestess Alathea and the priesthood of Elune helped train you before you set out across Azeroth. A night elf envoy was dispatched specifically to track you down among your human allies in Stormwind and relay the urgent summons. Now that you have grown in power and experience, Alathea and Tyrande Whisperwind have specific tasks and holy duties in Kalimdor that require a proven Sister of the Moon rather than a fresh initiate.",al={"why does alathea want me","why me returning home","why priestess alathea summon me"},it="why_me",rc="Night Elf",add="76c2bc63"}},ang={["class:Priest"]="As a priest, you return from fellowship with the Church of the Holy Light to the Sisterhood of Elune, where you can master Kaldorei rites.",["race:NightElf"]="As a night elf priest who has walked among humans or dwarves across the sea, you make a sacred return to the sanctuaries of Teldrassil.",["faction:Alliance"]="Brother Joshua in the Eastern Kingdoms and the priestesses in Darnassus work together, reflecting the spiritual ties that unite the Alliance."},kw={"brother joshua","darnassus","priest","priestess alathea","returning home","stars of elune","teldrassil","temple of the moon","tyrande"},rel={"quest:5627","npc:priestess-alathea","npc:brother-joshua","subzone:temple-of-the-moon","zone:darnassus","topic:elune","topic:light","quest:2519"},m={start="Brother Joshua",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5631},src={"Returning Home (Brother Joshua)"}}
E["quest:5632"] = {t="quest",n="Returning Home",z="darnassus",s="Priestess Alathea calls promising night elf priests back to Darnassus. The summons brings them to the Temple of the Moon to be recognized by the Sisterhood of Elune and receive advanced guidance.",h="Priestess Alathea calls promising night elf priests back to Darnassus.",sec={{t="A Messenger from the Sisterhood",b="A messenger from the Sisterhood reaches you while you visit Nara Meideros in Stormwind's Park. You have served your people abroad, and the order's leaders now require you in Darnassus. They have watched your spiritual growth and call you back for an evaluation and a rite of recognition. The journey marks your passage from a new initiate to an active servant of the Mother Moon.",sp=0},{t="Audience at the Temple of the Moon",b="The summons sends you to Priestess Alathea at the Temple of the Moon, Darnassus's highest sanctuary. High Priestess Tyrande Whisperwind oversees the Sisterhood, which watches over its members wherever they serve. Your safe return to the temple honors your community and Elune. It also shows that the goddess's grace has guided and preserved you through your early trials in the wild.",sp=0}},faq={{q="Why is the priestess summoning me back to Darnassus?",a="The Sisterhood of Elune has watched your spiritual growth, and Priestess Alathea summons you to the Temple of the Moon because you have progressed quickly in the order. There, you can receive deeper training and a sacred blessing.",al={"why returning home","reason for summons","why visit alathea"},it="purpose"},{q="Who is Priestess Alathea?",a="Priestess Alathea is a mentor in the Sisterhood of Elune, stationed at the Temple of the Moon. She works under High Priestess Tyrande Whisperwind, training promising night elf priests and guiding them through sacred rites.",al={"who is alathea","alathea lore","priestess alathea identity"},it="identity"},{q="Where does this summons lead next?",a="Priestess Alathea sends you next to Stars of Elune, an ancient trial where you learn to channel the goddess's celestial power in defense of your people.",al={"what quest is after returning home","next step in returning home","stars of elune lead in"},it="next_step"},{q="Who sends the message through Nara Meideros?",a="A messenger sent by the Sisterhood of Elune brought word to Nara Meideros. The order keeps in touch with priestesses serving abroad, including Nara in Stormwind's Park, to follow the progress of their initiates.",al={"who sent nara","messenger of the sisterhood"},it="origin"},{q="Do other races or classes receive this summons?",a="No. The summons belongs to the night elf priesthood and the Sisterhood of Elune. Other races and faiths look to their own spiritual mentors and holy orders for guidance.",al={"can non night elves do this","is this priest only"},it="for_you"},{q="Why does Alathea mention Tyrande Whisperwind?",a="Tyrande Whisperwind leads the Sisterhood of Elune and the night elf government as High Priestess of Elune. Alathea serves under her at the Temple of the Moon, carrying Tyrande's will and spiritual guidance to each initiate.",al={"tyrande connection","tyrande alathea relation"},it="ties"},{q="Why does Nara Meideros send you back to Darnassus?",a="Nara Meideros is simply fulfilling her duty to the Sisterhood of Elune. A messenger specifically arrived seeking you on behalf of the order's leadership in the Temple of the Moon. Seeing your rapid progress in the spiritual and martial ways of the priesthood, Nara is passing along the summons so you can receive guidance directly from Priestess Alathea and further your devotion to Elune.",al={"why does nara meideros want this done","nara meideros motive","why send me back to darnassus"},it="motive",add="f171321e"}},ang={["class:Priest"]="This summons marks an important step in your priesthood. Your early service brings you before the Sisterhood of Elune for further discipline and guidance.",["race:NightElf"]="For the kaldorei, your safe return to the Temple of the Moon is a homecoming that affirms Elune's clergy as a lasting source of cultural and spiritual leadership.",["faction:Alliance"]="The Sisterhood of Elune is the spiritual heart of the night elves in the Alliance. Its healers and divine warriors prepare to face threats across Kalimdor."},kw={"darnassus","nara meideros","priest quest","priestess alathea","returning home","sisterhood of elune","stars of elune","temple of the moon","tyrande whisperwind"},rel={"quest:5627","npc:priestess-alathea","npc:nara-meideros","subzone:temple-of-the-moon","zone:darnassus","topic:elune","quest:2519","quest:5628"},m={start="Nara Meideros",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5632},src={"Returning Home (Nara Meideros)"}}
E["quest:5633"] = {t="quest",n="Returning Home",z="darnassus",s="Night elf priests in Ironforge are called back to the Temple of the Moon in Darnassus. A Sisterhood emissary seeks out acolytes abroad and sends them to Priestess Alathea for urgent training and sacred duties.",h="Night elf priests in Ironforge are called back to the Temple of the Moon in Darnassus.",sec={{t="Summoned from the Mountain City",b="In Ironforge, night elf priests remain tied to the Sisterhood of Elune, though they are far from Teldrassil. Braenna Flintcrag, a dwarven priest trainer in the Mystic Ward, carries a message from a visiting night elf priestess. The messenger sought young disciples traveling abroad and said their mentors needed them back in the capital at once.",sp=0},{t="The Temple of the Moon",b="At the Temple of the Moon in Darnassus, returning acolytes report to Priestess Alathea. Beneath the watchful gaze of High Priestess Tyrande Whisperwind, Alathea welcomes her student and is relieved they crossed the seas safely. Their return begins further devotion and sacred duties, including the Stars of Elune.",sp=0}},faq={{q="Who starts this quest?",a="Braenna Flintcrag, the dwarf priest trainer in Ironforge's Mystic Ward, gives the summons.",al={"who gives returning home","quest giver returning home","braenna flintcrag location"},gp=true},{q="Who do I report to in Darnassus?",a="Report to Priestess Alathea inside the Temple of the Moon in Darnassus.",al={"where to turn in returning home","priestess alathea location","turn in returning home"},gp=true},{q="Why is the Sisterhood calling priests back?",a="The Sisterhood of Elune recalls its acolytes from abroad for advanced training and sacred rites such as the Stars of Elune.",al={"why returning home","why go back to darnassus"},it="purpose"},{q="Is this quest available to other classes?",a="No. The summons is for night elf priests who have traveled to Dun Morogh and Ironforge early in their travels.",al={"can warriors do returning home","priest only quest"},gp=true},{q="What happens after turning in this quest?",a="Priestess Alathea welcomes you back to Darnassus and offers the Stars of Elune, which teaches more of the goddess's ways.",al={"returning home next quest","followup to returning home"},it="next_step"},{q="How does Braenna know to look for you?",a="A priestess from the Temple of the Moon came through Ironforge seeking acolytes. She left instructions with local trainers such as Braenna to send wandering night elves home.",al={"why does braenna know me","ironforge priestess message"}},{q="Why does Braenna Flintcrag want this done?",a="Braenna has no personal stake in the temple's business; she is simply relaying an urgent message out of courtesy and respect. A night elf priestess came to Ironforge specifically searching for you, asking that you return to Darnassus without delay. Seeing that the matter sounded pressing, Braenna promised to pass the summons along the moment you arrived in the great dwarven halls.",al={"why does braenna want this done","braenna flintcrag motive","why send me back to darnassus"},it="motive",add="cd40b4be"}},ang={["class:Priest"]="As a priest, you travel from early adventures among Alliance allies back to the night elf priesthood's spiritual home at the Temple of the Moon.",["race:NightElf"]="As a night elf, you make a rare journey from Kalimdor to the Eastern Kingdoms, while Elune's guidance and Tyrande's priesthood reach across the Great Sea.",["faction:Alliance"]="As an Alliance adventurer, you see dwarven clerics in Ironforge and the Sisterhood of Elune in Darnassus coordinating to aid travelers."},kw={"braenna flintcrag","darnassus","priest quest","priestess alathea","returning home","stars of elune","temple of the moon"},rel={"npc:priestess-alathea","npc:braenna-flintcrag","subzone:temple-of-the-moon","quest:5627","quest:5628","zone:darnassus","topic:elune","quest:2519"},m={start="Braenna Flintcrag",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5633},src={"Returning Home (Ironforge)"}}
E["quest:5640"] = {t="quest",n="Desperate Prayer",z="darnassus",s="In Darnassus, young human and dwarven priests find guidance in another faith. Priestess Alathea teaches the ways of Elune, while followers of the Holy Light are directed to Stormwind. There, High Priestess Laurena welcomes the returning acolyte to the Cathedral of Light.",h="In Darnassus, young human and dwarven priests find guidance in another faith.",sec={{t="Two Paths of Faith",b="Alliance priests follow different sacred paths. In Darnassus, the priesthood tends to Elune, channeling the moon goddess's radiance and wrath. Priestess Alathea honors Elune and respects the Holy Light, but cannot teach another race the deeper prayers bound to a different devotion. Human and dwarven acolytes who seek those prayers must look elsewhere.",sp=0},{t="Return to the Cathedral",b="Initiates of the Holy Light return home to learn its rites, including the prayer for divine aid in a moment of peril. High Priestess Laurena guides returning priests in Stormwind's Cathedral of Light, beneath its marble arches.",sp=0}},faq={{q="Why does a Darnassus priest send me to Stormwind?",a="Priestess Alathea teaches the ways of Elune. She respects the Holy Light, but cannot teach its prayers to humans and dwarves, who seek guidance from High Priestess Laurena in Stormwind.",al={"why go to stormwind","why alathea sends me away","darnassus to stormwind priest quest"},it="purpose"},{q="Who is Priestess Alathea?",a="Priestess Alathea is a night elf priestess at Darnassus's Temple of the Moon. She mentors aspiring followers of Elune and offers respectful guidance to visiting priests of other faiths.",al={"alathea lore","who is alathea"},it="identity"},{q="Who is High Priestess Laurena?",a="High Priestess Laurena is a human spiritual leader in Stormwind's Cathedral of Light. She instructs servants of the Holy Light in advanced prayers and their responsibilities.",al={"who is laurena","high priestess laurena stormwind"},it="target"},{q="What is Desperate Prayer in the lore?",a="Desperate Prayer calls for divine aid when a priest is near death or in mortal peril. It is an invocation of the Holy Light that can bring immediate restoration.",al={"what is desperate prayer","desperate prayer ability lore"},it="power"},{q="Can night elves teach the Holy Light?",a="No. Night elves revere Elune almost exclusively and channel her lunar power. They respect the Holy Light, but do not preach it or teach its prayers; those belong to human and dwarven priests.",al={"do night elves know the light","elune vs holy light"},it="conflict"},{q="Where can I find High Priestess Laurena?",a="High Priestess Laurena resides in Cathedral Square in Stormwind City, inside the Cathedral of Light among clergy and paladins of the Silver Hand.",al={"laurena location","where is laurena"},gp=true},{q="Why does Priestess Alathea want me to seek out High Priestess Laurena?",a="Priestess Alathea recognizes that while both of your orders are bound by faith, night elf priestesses draw their power directly from Elune, whereas you walk the path of the Holy Light. She knows her own teachings in the Temple of the Moon can only take you so far. Out of respect for your distinct traditions, she directs you back to your own spiritual leaders in Stormwind so you can properly master the sacred arts of your faith.",al={"why does alathea send me away","alathea motive","why go to laurena"},it="motive",add="6bd09142"}},ang={["class:Priest"]="As a priest, you see the Alliance's holy magic divided between worship of Elune and devotion to the Holy Light.",["race:Human"]="As a human priest far from home, you are reminded that your spiritual home and training await in Stormwind's Cathedral of Light.",["race:Dwarf"]="As a dwarven priest, you share close ties with Stormwind's cathedral and learn high rites alongside your human brethren.",["race:NightElf"]="As a night elf, you acknowledge foreign faiths with courtesy while remaining devoted to the Mother Moon alone."},kw={"alathea","cathedral of light","darnassus","desperate prayer","elune","holy light","laurena","stormwind"},rel={"npc:priestess-alathea","npc:high-priestess-laurena","topic:light","topic:elune","zone:darnassus","topic:stormwind-kingdom"},m={start="Priestess Alathea",["end"]="High Priestess Laurena",level="10",faction="Alliance",id=5640},src={"Desperate Prayer (Darnassus)"}}
E["quest:5672"] = {t="quest",n="Elune's Grace",z="darnassus",s="In Darnassus, young night elf priests answer a call from the Sisterhood of Elune. Their early journeys prepare them for deeper instruction from Priestess Alathea.",h="In Darnassus, young night elf priests answer a call from the Sisterhood of Elune.",sec={{t="A Sacred Calling",b="The Sisterhood of Elune guides young acolytes in the Temple of the Moon, from their first prayers toward mastery of lunar magic. Night elves place their faith in the Mother Moon, Elune, unlike humans and dwarves, whose priests follow the Holy Light. When a novice priest reaches a milestone in devotion, senior mentors take notice and mark the disciple as ready to bear greater divine power.",sp=0},{t="Blessings of the Moon Goddess",b="Priestess Alathea brings the Sisterhood's summons to the acolyte. She recognizes their dedication and welcomes them into traditions preserved across millennia. By accepting the rite, the priest seals a bond to Elune and gains access to protective wards and lunar invocations unique to the kaldorei faith.",sp=0}},faq={{q="What is the purpose of this quest?",a="The rite marks a spiritual milestone for night elf priests. It calls an acolyte back to Darnassus, where Priestess Alathea recognizes their growth and grants them higher teachings from the Sisterhood of Elune.",al={"why do elunes grace","what does elunes grace do","purpose of quest"},it="purpose"},{q="Who is Priestess Alathea?",a="Priestess Alathea is a respected trainer of the Sisterhood of Elune in Darnassus. She guides developing kaldorei priests as they deepen their communion with the Moon Goddess.",al={"alathea role","who gives quest","who is alathea"},it="identity"},{q="Why is this gift specific to night elves?",a="Night elf priests venerate Elune directly, while human and dwarven priests draw upon the Holy Light. The Sisterhood's invocations, including Elune's Grace, reflect lunar protection and defensive enchantments cultivated by the kaldorei over thousands of years.",al={"why only night elves","racial ability lore","elune priest difference"},it="origin"},{q="Where does this ceremony take place?",a="The summons is answered in Darnassus, at the Temple of the Moon, where the city's priesthood gathers and teaches.",al={"where is alathea","quest location","darnassus temple"},it="place"},{q="Do other Alliance priests receive a similar calling?",a="Each culture approaches the priesthood differently. Humans and dwarves study the tenets of the Holy Light under their own mentors in Stormwind and Ironforge, gaining racial disciplines distinct from the moon magic practiced by night elves.",al={"do humans get this","dwarf priest equivalent","other races"},it="allies"},{q="What state of devotion is Alathea referring to?",a="Alathea means the spiritual fortitude and maturity gained through trials in the wider world. Survival, discipline, and steadfast adherence to Elune's virtues show that an acolyte can channel stronger lunar blessings safely.",al={"attained a state","alathea dialogue","what devotion"}},{q="Why does Priestess Alathea want to grant this gift?",a="Priestess Alathea oversees the spiritual progress of Darnassus's priesthood. As a servant of the Temple of the Moon, it is her sacred duty and ancient tradition to recognize when an acolyte has proven exceptional devotion to Elune and the kaldorei people. By conferring Elune's Grace, she ensures that worthy night elf priests are entrusted with the Moon Goddess's deeper blessings to better protect their kin.",al={"why does alathea teach elunes grace","alathea motive","why elunes grace now"},it="motive",rc="Night Elf",add="853b2ba0"}},ang={["class:Priest"]="As a priest, you follow a kaldorei faith distinct from the Light-based doctrines of humans and dwarves, with your craft rooted in Elune's protection.",["race:NightElf"]="As a night elf, you inherit Elune's Grace through ancient traditions preserved by the Sisterhood of Elune."},kw={"alathea","darnassus","elune","elune's grace","priest quest","priestess alathea","sisterhood of elune","temple of the moon"},rel={"npc:priestess-alathea","topic:elune","zone:darnassus","topic:night-elf"},m={start="Priestess Alathea",level="20",faction="Alliance",id=5672},src={"Elune's Grace (Darnassus)"}}
E["quest:5674"] = {t="quest",n="Elune's Grace",z="darnassus",s="From Dolanaar, night elf priests return to Darnassus for Elune's Grace. The rite marks their readiness to wield divine talents unique to their people.",h="From Dolanaar, night elf priests return to Darnassus for Elune's Grace.",sec={{t="A Sacred Milestone",b="A priest's path in the Sisterhood of Elune calls for more than skill in prayers of mending and smiting. As acolytes gain experience, they reach a threshold where they may receive blessings granted only to the kaldorei. Local mentors such as Laurna Morninglight in Dolanaar cannot bestow these deeper arts, so they send promising disciples to the spiritual heart of their order.",sp=0},{t="Audience at the Temple",b="Initiates cross Teldrassil to the Temple of the Moon in Darnassus. Beneath the gaze of the high priesthood, Priestess Alathea judges whether each petitioner is ready to bear the goddess's defensive mantle. Elune's Grace is taught there as a divine talent reserved for the kaldorei.",sp=0}},faq={{q="What is the purpose of this quest?",a="After gaining enough practical experience, night elf priests return to Darnassus for a rite of passage. At the Temple of the Moon, Priestess Alathea tests them and teaches the defensive art of Elune's Grace.",al={"what does this quest do","elunes grace quest purpose","why visit alathea"},it="purpose"},{q="Who is Priestess Alathea?",a="Priestess Alathea is a high-ranking priest trainer at the Temple of the Moon in Darnassus. She oversees the formal training and advancement of night elf acolytes, judging whether they have the spiritual focus for advanced racial prayers.",al={"priestess alathea lore","who is alathea","alathea darnassus"},it="identity"},{q="Why can't local mentors teach this ability?",a="Outpost mentors such as Laurna Morninglight guide novices through foundational teachings, but the Sisterhood reserves sacred blessings unique to the kaldorei for formal conferral. Acolytes travel to the order's central seat of devotion in Darnassus for evaluation before learning these deeper gifts.",al={"why not train in dolanaar","why go to darnassus"},it="why_me"},{q="What does Elune's Grace actually represent in kaldorei faith?",a="Elune's Grace represents the Moon Goddess's direct protection. Woven through prayer, it diminishes the force of incoming attacks and reflects Elune's sheltering presence over her faithful when danger draws close.",al={"what is elunes grace","elunes grace lore"},it="power"},{q="Can priests of other races receive this blessing?",a="No. Elune's Grace belongs to the ancestral faith and worship of the kaldorei. Only night elf priests who commune directly with the Moon Goddess are taught its invocation.",al={"can humans learn elunes grace","is elunes grace night elf only"},it="people"},{q="Where does this journey begin and end?",a="Laurna Morninglight summons the acolyte from Dolanaar on Teldrassil to the Temple of the Moon in Darnassus.",al={"quest start and end","where to go"},it="place",gp=true},{q="Why does Laurna Morninglight send you to Darnassus?",a="Laurna Morninglight marks this as a momentous milestone in your spiritual calling. You have grown experienced enough to receive sacred blessings known solely to kaldorei clergy, but tradition and ritual dictate that such vital teachings cannot be imparted in a humble woodland outpost like Dolanaar. Her duty is to guide you back to the high priesthood at the Temple of the Moon, ensuring your readiness is properly tested and sanctioned before you are entrusted with the Moon Goddess's deeper mysteries.",al={"why does laurna morninglight want this done","laurna morninglight motive","why send to priestess alathea"},it="motive",add="dd9d0779"}},ang={["class:Priest"]="As a night elf priest, this rite grounds you in the Sisterhood of Elune's celestial magic rather than universal holy practices.",["race:NightElf"]="As a night elf, the pilgrimage to the Temple of the Moon reflects Elune's central place in kaldorei society, bringing distant acolytes to the heart of Darnassus."},kw={"darnassus","dolanaar","elune's grace","laurna morninglight","priestess alathea","sisterhood of elune","teldrassil","temple of the moon"},rel={"npc:priestess-alathea","npc:laurna-morninglight","subzone:temple-of-the-moon","quest:5672","quest:2519","topic:elune","topic:night-elf","zone:darnassus"},m={start="Laurna Morninglight",["end"]="Priestess Alathea",level="20",faction="Alliance",id=5674},src={"Elune's Grace (Dolanaar)"}}
E["quest:5678"] = {t="quest",n="Arcane Feedback",z="darnassus",s="In Darnassus, Arcane Feedback sends human priests back to Stormwind. Priestess Alathea at the Temple of the Moon reluctantly honors the Alliance summons. There, High Priestess Laurena prepares the acolyte for deeper instruction.",h="In Darnassus, Arcane Feedback sends human priests back to Stormwind.",sec={{t="A Reluctant Summons",b="Priestess Alathea oversees visiting priests in the Temple of the Moon in Darnassus. She recognizes the formal alliance between the kaldorei and Stormwind, yet distrusts human magical and spiritual practices. Night elves see arcane power as volatile and dangerous, a view shaped by ten millennia of grief since the War of the Ancients. Even human divine rites trouble the night elf clergy when they blur radiant faith with arcane workings.",sp=0},{t="Return to the Cathedral",b="Alathea honors the bond between the Alliance races and sends you to answer a recall from the Cathedral of Light. High Priestess Laurena has sent couriers across the seas to gather human priests for advanced training. In Stormwind, you leave Elune's moonlit groves behind for the grand stone sanctuaries and golden radiance of the Holy Light.",sp=0}},faq={{q="Why does Priestess Alathea want me to leave Darnassus?",a="Priestess Alathea sends you home at the request of your superiors in Stormwind, though human theology also makes her uneasy. She distrusts arcane magic, even when tied to divine practice, and is glad to send human acolytes back to their own cathedrals.",al={"why alathea sends me away","why return to stormwind","alathea arcane feedback"},it="motive"},{q="Why do night elves distrust human priestly magic?",a="Night elves distrust human priestly magic because their culture bears the grief of the Sundering, caused by reckless arcane spellcraft ten thousand years ago. Kaldorei worship centers on Elune, and its priestesses mistrust traditions that border on or use arcane power, even among allies who follow the Holy Light.",al={"why night elves hate arcane","night elf arcane distrust","elune vs holy light"},it="conflict"},{q="Who is High Priestess Laurena?",a="High Priestess Laurena leads the faithful at Stormwind's Cathedral of Light. She trains emerging human priests in the Holy Light as their power grows.",al={"who is laurena","high priestess laurena stormwind"},it="target"},{q="What does this quest lead into?",a="Reporting to High Priestess Laurena begins your advanced training as a human priest in Stormwind, where you learn the discipline and blessings of human adherents of the Holy Light.",al={"what comes after arcane feedback","arcane feedback reward lore"},it="next_step"}},ang={["class:Priest"]="As a priest, your return marks a threshold in your spiritual path and reveals the sharp divide between Elune's sisterhood and the teachings of the Holy Light.",["race:Human"]="As a human, you return to Stormwind, home of the Church of the Holy Light, after leaving the cloistered, skeptical kaldorei priesthood.",["race:NightElf"]="As a night elf, you see Priestess Alathea's wariness reflect the kaldorei fear that arcane tampering by younger mortal races could bring another disaster."},kw={"arcane feedback","cathedral of light","darnassus","high priestess laurena","holy light","priest quest","priestess alathea","stormwind"},rel={"npc:priestess-alathea","npc:high-priestess-laurena","subzone:cathedral-of-light","topic:stormwind-kingdom","topic:light"},m={start="Priestess Alathea",["end"]="High Priestess Laurena",level="20",faction="Alliance",id=5678},src={"Arcane Feedback (Darnassus)"}}
E["quest:5921"] = {t="quest",n="Moonglade",z="darnassus",s="In Darnassus, young night elf druids learn to reach Moonglade. Mathrengyl Bearwalker teaches novices a spell to carry themselves across the world into Moonglade, where they meet Dendrite Starblaze in Nighthaven. There begins their path toward mastering bear form.",h="In Darnassus, young night elf druids learn to reach Moonglade.",sec={{t="A Sacred Refuge",b="Moonglade is an ancient sanctuary apart from the rest of Azeroth, devoted to the teachings of Cenarius. Keeper Remulos watches over its groves, where druids find peace and communion with nature. Young druids learn a spell that lets them carry themselves across the world into Moonglade, reaching a heart of druidic wisdom beyond mortal distances.",sp=0},{t="Politics of the Circle",b="Moonglade welcomes all who follow the wild, though the Cenarion Circle knows its share of tension. In Darnassus, Arch Druid Fandral Staghelm and Keeper Remulos disagree over nature’s care and the creation of Teldrassil. Their differences do not close Nighthaven to young acolytes, who are welcomed to pursue their studies.",sp=0},{t="The Path of the Bear",b="In Nighthaven, Dendrite Starblaze guides young druids in the ways of the Claw. Before an initiate can take up the bear’s mantle, the trials teach the bear’s endurance, fury, and defense of the wild. Starblaze welcomes each student in reverence to Father Cenarius as the trials of the Great Bear Spirit begin.",sp=0}},faq={{q="Why do druids learn to teleport to Moonglade?",a="The spell gives druids a way to return to Moonglade, where training, communion with spirits, and high-level council take place in Nighthaven. Its instant passage lets each practitioner return to study and replenish spiritual energies.",al={"why teleport moonglade","teleport moonglade purpose","why go to moonglade"},it="purpose"},{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is an elder druid on the upper floor of a major lodge in Nighthaven. He oversees arriving initiates and begins their trials in animal perspectives, starting with the bear.",al={"dendrite starblaze role","who is dendrite","dendrite starblaze"},it="identity"},{q="What tensions exist between Fandral Staghelm and Keeper Remulos?",a="Arch Druid Fandral Staghelm led the planting of Teldrassil without the Dragon Aspects’ blessing and pursued a more aggressive, nationalistic path for the night elves. Keeper Remulos and Moonglade’s traditionalists hold to Cenarius’s ancient, neutral ways, bringing ideological friction to the Cenarion Circle.",al={"staghelm remulos tension","fandral vs remulos","circle division"},it="conflict"},{q="Can Horde druids visit Moonglade as well?",a="Yes. Moonglade is a neutral haven under Keeper Remulos and the Cenarion Circle. Night elf and tauren druids study the wild ways together there, setting aside factional hostility within Cenarius’s peace.",al={"horde moonglade","are tauren allowed in moonglade","is moonglade neutral"}},{q="What happens after reaching Dendrite Starblaze?",a="After you reach Dendrite Starblaze, he guides you into the ritual trial of the Great Bear Spirit. The spiritual confrontation tests your resolve and understanding before you can wield the bear’s power.",al={"after moonglade quest","next step bear form","bear quest next"},it="next_step"},{q="Where in Nighthaven is Dendrite located?",a="Dendrite Starblaze is inside the main night elf lodge near the center of Nighthaven, on its second-floor balcony overlooking the village.",al={"find dendrite starblaze","dendrite starblaze location","where is dendrite"},gp=true},{q="Why does Mathrengyl Bearwalker send you to Moonglade?",a="Mathrengyl Bearwalker is guiding your initiation into the ways of the Claw. While basic instruction begins under Teldrassil's boughs, true mastery of the bear aspect requires communion with the Cenarion Circle's ancient sanctuary. Mathrengyl sends you to Nighthaven so you may learn directly from senior druids like Dendrite Starblaze, setting aside Darnassus's political divisions to ground your spirit in the sacred heartland of all druidic tradition.",al={"why send to moonglade","mathrengyl bearwalker motive","why does mathrengyl want this done"},it="motive",add="127ac65b"}},ang={["class:Druid"]="As a druid, this journey awakens you to a wider druidic heritage and gives you an eternal lifeline to the tranquil heart of the Cenarion Circle.",["race:NightElf"]="As a night elf, leaving Teldrassil’s boughs for ancient Moonglade connects you with the ancestral homeland preserved before the Great Sundering.",["faction:Alliance"]="As an Alliance member, entering Moonglade reminds you that night elf druids answer to an older calling beyond worldly factions."},kw={"bear","cenarion","dendrite","mathrengyl","moonglade","nighthaven","remulos","starblaze","teleport"},rel={"npc:dendrite-starblaze","subzone:nighthaven","npc:remulos","topic:cenarion-circle","topic:druid","topic:cenarius"},m={start="Mathrengyl Bearwalker",["end"]="Dendrite Starblaze",level="10",faction="Alliance",id=5921},src={"Moonglade (Alliance)"}}
E["quest:5923"] = {t="quest",n="Heeding the Call",z="darnassus",s="Heeding the Call marks the moment an apprentice night elf druid catches the attention of the Cenarion Circle's senior leadership. Summoned to Darnassus to meet Mathrengyl Bearwalker, the young initiate begins the sacred path toward mastering their first animal aspect, the bear.",h="Heeding the Call marks the moment an apprentice night elf druid catches the attention of the Cenarion...",sec={{t="A Summons from the Enclave",b="Novice druids honing their craft across Teldrassil—or studying abroad in far-off realms like Stormwind—eventually receive a personal summons. Instructors such as Kal in Dolanaar, Denatharion in Darnassus, or Theridran across the Great Sea carry word that Mathrengyl Bearwalker wishes to oversee their training personally. As the direct assistant to Arch Druid Fandral Staghelm, Mathrengyl is one of the most respected and knowledgeable mentors among the night elves, and his attention is an unmistakable sign that an apprentice is ready for genuine trials.",sp=0},{t="The Path of the Bear",b="Reaching Mathrengyl on the upper level of Fandral Staghelm's towering residence in the Cenarion Enclave opens the door to deeper mysteries. To serve nature properly, a druid must learn to embody its living creatures rather than merely observing them. Mathrengyl welcomes candidates with the news that their first great undertaking will be embracing the strength, endurance, and spirit of the bear—a journey that will take them far beyond Teldrassil to sacred ancestral grounds.",sp=0}},faq={{q="Who sends me on this quest?",a="You can receive this summons from several druid trainers once you have reached sufficient experience: Kal in Dolanaar, Denatharion in Darnassus, or Theridran in the Park district of Stormwind City.",al={"quest giver","who starts this","where do i get this quest"},it="people"},{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is a senior night elf druid and the direct assistant to Arch Druid Fandral Staghelm. He resides in the Cenarion Enclave of Darnassus and serves as a premier instructor for initiates seeking to master animal forms.",al={"mathrengyl","who is mathrengyl","bearwalker"},it="identity"},{q="Where can I find Mathrengyl Bearwalker in Darnassus?",a="He is located in the Cenarion Enclave, in the northwest quarter of Darnassus. You will find him waiting on the second floor of the large living tree that serves as Arch Druid Fandral Staghelm's sanctuary.",al={"mathrengyl location","where is mathrengyl","cenarion enclave location"},it="place",gp=true},{q="What training does this quest lead to?",a="Reporting to Mathrengyl begins the sacred trial of the Bear Form. He will direct you across Kalimdor to the sacred haven of Moonglade to learn the strengths of body and heart required to commune with the Great Bear Spirit.",al={"what comes next","what do i get","next quest"},it="next_step"},{q="Why can I get this quest in Stormwind?",a="Night elf emissaries and druids, such as Theridran, maintain a sanctuary in the Park of Stormwind to assist Alliance allies. If a young druid is adventuring across the sea in Elwynn Forest, Theridran can relay the summons back home to Teldrassil.",al={"stormwind quest","theridran","can i get this in stormwind"},it="why_here"},{q="Why is the bear form the first animal aspect taught?",a="Druids hold that nature requires both guardians and caretakers. The bear represents raw resilience, physical power, and the courage to shield the balance from harm, making it the foundational aspect for surviving dangerous wilderness trials.",al={"why bear form","druid bear lore"},it="origin"},{q="Why am I being sent to Mathrengyl Bearwalker?",a="Your druidic instructors recognise that your basic apprenticeship is complete and you are ready for advanced instruction. Mathrengyl Bearwalker serves directly beneath Arch Druid Fandral Staghelm and oversees the critical rite of communion with the great bear spirit. The trainers direct you to him so you may begin learning shapeshifting, unlocking the strength of body and heart required to protect the balance of nature.",al={"why mathrengyl","why heed the call","reason for heeding the call","why does denatharion send me"},it="motive",add="7976a971"},{q="Why does Mathrengyl Bearwalker want me instead of someone else?",a="This is not an errand of state or military defense, but a personal rite of passage unique to your path as an aspiring druid. Mathrengyl Bearwalker seeks out young druids who possess the potential to channel the spirit of the wild. Only you can commune with the patron spirits and undergo the spiritual tests required to master your first animal aspect.",al={"why me heeding the call","why choose me","why does mathrengyl need me"},it="why_me",add="fad6f2dc"}},ang={["class:Druid"]="This quest represents your formal transition from a mere novice weaving root and wrath spells into a true shapeshifter learning the spirits of Kalimdor.",["race:NightElf"]="Heeding the summons calls you into the heart of Darnassus's Cenarion Enclave, honoring millennia of Kaldorei tradition under the watchful eye of Fandral Staghelm's circle.",["faction:Alliance"]="The ability to pick up this quest from Theridran in Stormwind shows the growing coordination between the kaldorei of Teldrassil and their eastern human allies."},kw={"bear form","cenarion enclave","darnassus","denatharion","druid quest","fandral staghelm","heeding the call","kal","mathrengyl bearwalker","theridran"},rel={"npc:mathrengyl-bearwalker","subzone:cenarion-enclave","zone:darnassus","topic:druid","npc:fandral-staghelm","subzone:dolanaar","zone:elwynn","topic:cenarius"},m={start="DenatharionKalTheridran",["end"]="Mathrengyl Bearwalker",level="10",faction="Alliance",id=5923},src={"Heeding the Call (Alliance)"}}
E["quest:5931"] = {t="quest",n="Back to Darnassus",z="darnassus",s="After meeting the Great Bear Spirit, a young night elf druid returns to Darnassus. The initiate has left Moonglade and now reports to Mathrengyl Bearwalker in the Cenarion Enclave for practical shapeshifting trials.",h="After meeting the Great Bear Spirit, a young night elf druid returns to Darnassus.",sec={{t="A Journey Between Sanctuaries",b="Dendrite Starblaze sends the initiate from Nighthaven back to Darnassus after the meeting with the Great Bear Spirit in Moonglade. The journey joins two sanctuaries: Moonglade, where the young druid has communed with the spirit, and the unsettled world beyond. In Darnassus, local mentors watch over Teldrassil and guide the next stage of training.",sp=0},{t="The Path of the Claw",b="Mathrengyl Bearwalker waits in the Cenarion Enclave, where he guards nature even as its balance falters. The Great Bear Spirit's blessing is only the first step. Mathrengyl prepares the initiate for trials of body and heart, to give physical form to the spirit's fierce ancestral wisdom.",sp=0}},faq={{q="Why do I need to return to Darnassus?",a="Moonglade is where you commune with the Great Bear Spirit, while your mentor, Mathrengyl Bearwalker, waits in Darnassus's Cenarion Enclave. He guides the practical tests that help you master your new power.",al={"why return to darnassus","why leave moonglade","where does dendrite send me"},it="purpose"},{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is a seasoned night elf druid trainer in Darnassus's Cenarion Enclave. He guides young initiates along the Way of the Claw and in mastering bear form.",al={"who is mathrengyl","mathrengyl bearwalker lore","bearwalker"},it="identity"},{q="How do I get back to Darnassus from Moonglade?",a="Silva Fil'naveth, the hippogryph master in southwestern Nighthaven, can fly you across the sea to Rut'theran Village. From there, a portal leads up into Darnassus.",al={"how to leave nighthaven","moonglade flight back","silva fil'naveth"},gp=true},{q="What happens after I speak to Mathrengyl?",a="Mathrengyl gives you your first true test of purpose: face Lunaclaw at the Moonkin Stone east of Auberdine in Darkshore. The trial proves whether your body and heart are ready to wield bear form.",al={"next quest after back to darnassus","what comes next"},it="next_step"},{q="What is the Path of the Claw?",a="The Path of the Claw is a druidic tradition that channels the bear's ferocity, resilience, and strength through communion with ancient primal spirits.",al={"path of the claw","druid claw lore"},it="power"},{q="Why does Dendrite mention balance faltering near Darnassus?",a="Teldrassil is young and lacks the Dragon Aspects' blessing, leaving its boughs vulnerable to strange corruptions, furbolg madness, and encroaching darkness. Druids in the Cenarion Enclave fight these threats.",al={"balance faltered darnassus","teldrassil corrupted"},it="threat"},{q="Why does Dendrite Starblaze want me to return to Mathrengyl?",a="Dendrite Starblaze has guided you through your initial communion with the Great Bear Spirit in Moonglade, but Moonglade is a place of sanctuary and study, not practical trial. Mathrengyl Bearwalker originally sent you on this spiritual journey and is charged with overseeing your actual training. Dendrite sends you back so Mathrengyl can test your newfound connection to the bear spirit and guide you through the demanding trials required to walk the Path of the Claw.",al={"why send me back dendrite","dendrite starblaze motive","why return to darnassus dendrite"},it="motive",add="8983e9c4"}},ang={["class:Druid"]="For a young druid, this journey marks the passage from spiritual communion to physical shapeshifting.",["race:NightElf"]="As a night elf, you travel between Moonglade, an ancient sanctuary, and Teldrassil, the newly planted World Tree. The journey joins millennia of kaldorei heritage with your duties today."},kw={"bear spirit","bearwalker","cenarion enclave","darnassus","dendrite","mathrengyl","moonglade","shapeshifting","starblaze"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","subzone:cenarion-enclave","subzone:nighthaven","zone:darnassus","topic:druid"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="10",faction="Alliance",id=5931},src={"Back to Darnassus"}}
E["quest:6001"] = {t="quest",n="Body and Heart",z="darnassus",s="In Darnassus, a young night elf druid nears the end of initiation into the path of the claw. Mathrengyl Bearwalker sends the initiate into Darkshore to summon Lunaclaw and prove strength of body and heart before taking the form of the bear.",h="In Darnassus, a young night elf druid nears the end of initiation into the path of the claw.",sec={{t="The Trial of Lunaclaw",b="Mathrengyl Bearwalker sends night elf druid initiates east of Auberdine, the coastal settlement in Darkshore. A natural cavern there shelters wild moonkin and an ancient Moonkin Stone. Anointing the sacred stone with Cenarion Moondust awakens Lunaclaw, its ancient defender. The guardian challenges any initiate who seeks the sacred strength of the claw.",sp=0},{t="Strength of Body and Heart",b="The Great Bear Spirit teaches the first lessons of nature’s ferocity. Taking the form of the bear calls for more than brute force; Lunaclaw’s trial tests an initiate’s fortitude of heart. By defeating the guardian and heeding the spirit’s lingering wisdom, a druid proves ready to wield the bear form without losing themselves to beastly instinct.",sp=1}},faq={{q="Who is Lunaclaw?",a="Lunaclaw is an ancient moonkin guardian in a cavern east of Auberdine in Darkshore. It defends the sacred Moonkin Stone and awakens when an initiate anoints the stone with Cenarion Moondust.",al={"what is lunaclaw","lunaclaw lore","moonkin boss auberdine"},it="target"},{q="What is the purpose of this trial?",a="The trial is the final test for a night elf initiate seeking to join the Druids of the Claw. Defeating Lunaclaw proves the initiate has the physical resilience and mental composure to take on the spirit and shape of the bear.",al={"why do body and heart","what does this quest do","bear form quest lore"},it="purpose"},{q="Who gives this quest?",a="Mathrengyl Bearwalker, an elder druid trainer in Darnassus’s Cenarion Enclave, gives initiates this trial after they have communed with the Great Bear Spirit.",al={"quest giver body and heart","who gives bear form quest"},it="in_charge"},{q="What is Cenarion Moondust?",a="Cenarion Moondust is a consecrated ritual powder given to initiates by their elders. Its magical properties awaken Lunaclaw when it is cast upon the Moonkin Stone, beginning the ritual combat.",al={"what is moondust","cenarion moondust lore"},it="item"},{q="Where does this trial take place?",a="The trial takes place in a cavern east of Auberdine in Darkshore. Wild moonkin live around an ancient carved Moonkin Stone there.",al={"where is moonkin stone","moonkin cave auberdine"},it="place",gp=true},{q="What happens after Lunaclaw is defeated?",a="After Lunaclaw is defeated, the Spirit of Lunaclaw appears above its physical shell and bestows a blessing, recognizing the druid’s strength of heart and body before they return to Darnassus.",al={"what happens after killing lunaclaw","spirit of lunaclaw"},sp=1,it="next_step"},{q="Why does Mathrengyl Bearwalker send you to face Lunaclaw?",a="Mathrengyl Bearwalker serves as your mentor in Darnassus and must test whether you are worthy to walk the path of the Druid of the Claw. Before he can unlock the secrets of the bear form for you, he requires proof that you possess not just physical might, but also the strength of heart needed to wield the primal power without losing yourself.",al={"why mathrengyl bearwalker trial","mathrengyl bearwalker motive","why body and heart"},it="motive",add="26f3a5de"},{q="Why must you complete this trial yourself?",a="This is a sacred rite of passage that tests a druid's inner spirit. No sentinel, guard, or mentor can take the trial for you, as the strength of body and heart must be proven by your own resolve. To commune with the spirit and master the forms of the wild, you must face Lunaclaw and earn its blessing in personal combat.",al={"why cant guards fight lunaclaw","why me body and heart","why druid alone"},it="why_me",add="d295d16d"}},ang={["class:Druid"]="For a druid, this rite marks a defining threshold in early training. It transforms a novice spellcaster into a shapeshifting protector able to take the mighty bear form.",["race:NightElf"]="As a night elf, you renew ties to Cenarion customs established millennia ago by communing with ancient beast spirits and honoring sacred stones in Darkshore."},kw={"auberdine","bear form","body and heart","cenarion moondust","druid of the claw","lunaclaw","mathrengyl bearwalker","moonkin stone"},rel={"npc:mathrengyl-bearwalker","quest:5931","quest:2561","subzone:auberdine","zone:darnassus","topic:druid"},m={start="Mathrengyl Bearwalker",level="10",faction="Alliance",id=6001},src={"Body and Heart (Alliance)"}}
E["quest:6121"] = {t="quest",n="Lessons Anew",z="darnassus",s="Mathrengyl Bearwalker sends Alliance druids from Darnassus to Moonglade for training. There, Dendrite Starblaze begins their instruction in cleansing venom and toxins.",h="Mathrengyl Bearwalker sends Alliance druids from Darnassus to Moonglade for training.",sec={{t="A Gift from Cenarius",b="Druids learn from Cenarius, the demigod whose teachings and blessings bind them to the living world. His gifts include the power to cleanse venom with a simple incantation. Such power is not given lightly. Before young druids can wield it, they must learn the hard, ordinary work of fighting toxins without nature's magic.",sp=0},{t="Summons to Nighthaven",b="Mathrengyl Bearwalker trains druids in Darnassus's Cenarion Enclave. He sends his student past local practice and on to Moonglade. In Nighthaven, Dendrite Starblaze coordinates the Cenarion Circle's wider efforts and has practical work for the novice.",sp=0},{t="A Real-World Crisis",b="In Nighthaven, initiates face a real crisis rather than a staged trial or ritual. Auberdine, on the Darkshore coast, suffers a wave of animal poisonings that its people cannot stop. Dendrite Starblaze sends the novice to investigate and aid Darkshore, where lives are at stake.",sp=1}},faq={{q="Who offers the quest Lessons Anew?",a="Mathrengyl Bearwalker, the night elf druid trainer in Darnassus's Cenarion Enclave, offers it.",al={"who gives lessons anew","lessons anew quest giver","mathrengyl bearwalker quest"},it="identity",gp=true},{q="Where do I need to go to complete this quest?",a="Travel to Moonglade and report to Dendrite Starblaze in Nighthaven.",al={"where do i go","where is dendrite starblaze","lessons anew turn in"},it="place",gp=true},{q="Why must druids learn to cure poisons like a layman first?",a="Druid mentors believe that Cenarius's gift of curing venom with an incantation can breed complacency. Studying ordinary ways to confront venom first teaches initiates to respect the burden and suffering poison causes.",al={"why layman","why cure poison without magic","cenarius poison lesson"},it="motive"},{q="What problem is taking place in Auberdine?",a="Auberdine suffers severe animal poisonings along the Darkshore coast. The local night elves cannot cure them and have asked the Cenarion Circle in Moonglade for help.",al={"auberdine poison problem","what is happening in auberdine","darkshore animal poisonings"},it="threat"},{q="What ability does this quest chain eventually grant?",a="It begins the Power over Poison chain, which teaches druids Cure Poison, a spell that magically cleanses toxins from allies.",al={"what reward do i get","cure poison quest","power over poison chain"},it="power",gp=true},{q="Is this quest available to Horde druids?",a="No. Lessons Anew begins in Darnassus for Alliance druids. Tauren druids receive a parallel beginning in Thunder Bluff, which also sends them to Moonglade to learn to cure poison.",al={"horde lessons anew","can tauren do this","tauren lessons anew"},it="side",gp=true},{q="Why does Mathrengyl Bearwalker send you to Moonglade?",a="As your mentor in Darnassus, Mathrengyl Bearwalker recognizes that your druidic training has reached the point where you can wield Cenarius's blessing over venom. He cannot bestow this sacred art casually; druidic tradition demands you study under Dendrite Starblaze in Moonglade, ensuring you understand the grave burden of poison before mastering the gift to purge it.",al={"why does mathrengyl send me","why go to moonglade druid","why me lessons anew"},it="why_me",add="cb6ddbb8"}},ang={["class:Druid"]="As a druid, you move beyond basic shapeshifting and survival toward caring for the wilds, learning to lift lethal blights and venoms from nature.",["race:NightElf"]="From Darnassus's Cenarion Enclave, you are sent toward the deeper ancestral responsibilities tied to Moonglade and Darkshore.",["faction:Alliance"]="As an Alliance member, you see how vital druidic aid is to the fragile northern settlements in Darkshore, including Auberdine."},kw={"auberdine","cenarius","cure poison","dendrite starblaze","lessons anew","mathrengyl bearwalker","moonglade","nighthaven","power over poison"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","quest:6125","subzone:nighthaven","subzone:auberdine","topic:cenarius","topic:druid","quest:5921"},m={start="Mathrengyl Bearwalker",["end"]="Dendrite Starblaze",level="14",faction="Alliance",id=6121},src={"Lessons Anew (Alliance)"}}
E["quest:6125"] = {t="quest",n="Power over Poison",z="darnassus",s="In Darnassus, a young druid returns to complete Power over Poison. The Cenarion Circle's trial began in Darkshore, where the initiate learned to brew a remedy by hand.",h="In Darnassus, a young druid returns to complete Power over Poison.",sec={{t="The Student's Humility",b="In Darkshore, Alanndarian Nightsong asks young druids to gather Earthroot and Lunar Fungus by hand. They brew a salve to heal stricken wildlife. Before granting the magic to purge toxins, the Cenarion Circle wants initiates to know the hardship of treating poison without spiritual aid. The work teaches them what common folk face when venom strikes, and why a druid must meet their suffering with care.",sp=0},{t="Return to the Enclave",b="After the remedy proves effective in Auberdine, Starblaze sends the druid across the sea to Darnassus. Mathrengyl Bearwalker awaits in the Cenarion Enclave. Pleased with the initiate's grace under pressure, he teaches the art of cleansing toxins through nature's power. But virulent poisons in the wilds around Auberdine trouble him, for they point to an unnatural blight disturbing the land's balance.",sp=0}},faq={{q="What is the purpose of this quest?",a="The trial teaches a druid to cure poison with magic after first preparing a salve by hand. The student returns from Darkshore to Mathrengyl Bearwalker in Darnassus to learn Cure Poison.",al={"why do power over poison","power over poison objective","cure poison quest"},it="purpose"},{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is an elder druid at Nighthaven in Moonglade. He guides initiates through spiritual trials, testing their patience and dedication to nature before sending them to their home trainers.",al={"dendrite starblaze role","who gives power over poison"},it="people"},{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is a master druid trainer in the Cenarion Enclave in Darnassus. He trains night elf druids in forms, restorative arts, and the duties of the Cenarion Circle beneath Teldrassil's boughs.",al={"mathrengyl bearwalker lore","bearwalker darnassus"},it="people"},{q="Why was the druid required to make a cure by hand first?",a="Dendrite Starblaze teaches that druids should understand poison's physical toll and the work of treating it without magic. Gathering ordinary ingredients and tending the sick by hand teaches humility and appreciation for the natural gifts they are about to receive.",al={"why make herbal cure","lesson of power over poison"}},{q="What concerns Mathrengyl about the situation in Auberdine?",a="Mathrengyl finds the lethal toxins in the Darkshore wilds around Auberdine unnatural. Their effect on native wildlife and plants threatens the land's balance and suggests a corrupting influence along the coast.",al={"auberdine poison lore","mathrengyl concern"},it="threat"},{q="Why does Dendrite Starblaze send you back to Darnassus?",a="Dendrite Starblaze wants you to finish your rite of passage. Having forced you to gather herbs and cure the sick in Auberdine by hand, he has ensured you appreciate the toil ordinary mortals face when battling venom. Now that you understand the stakes and humility required of a guardian of nature, he sends you back so Mathrengyl Bearwalker can bestow the true druidic spell upon you.",al={"why send to mathrengyl","dendrite starblaze motive","why return to darnassus"},it="motive",add="92345f63"}},ang={["class:Druid"]="As a druid, you begin with humble herbal work before receiving nature's magic to cleanse venom.",["race:NightElf"]="As a night elf, you undertake this trial in Darnassus's Cenarion Enclave, where it reflects Kaldorei reverence for balance and stewardship of their ancient forests."},kw={"auberdine","cenarion enclave","cure poison","darnassus","dendrite starblaze","mathrengyl bearwalker","moonglade","power over poison"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","subzone:cenarion-enclave","zone:darnassus","topic:druid","subzone:auberdine"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="14",faction="Alliance",id=6125},src={"Power over Poison (Alliance)"}}
E["quest:6344"] = {t="quest",n="Nessa Shadowsong",z="darnassus",s="In Darnassus, Mydrannul sends a courier to meet Nessa Shadowsong below the World Tree. The delivery runs from Rut'theran Village to Darkshore, linking the canopy city with the shore.",h="In Darnassus, Mydrannul sends a courier to meet Nessa Shadowsong below the World Tree.",sec={{t="A Errand Beyond the Canopy",b="Mydrannul watches over travelers seeking work and purpose in Darnassus. Fishing merchant Nessa Shadowsong needs a package carried across the sea to Darkshore, so Mydrannul directs able couriers toward the coast. Many young night elves begin their journeys among Teldrassil's boughs; this delivery takes them beyond the tree.",sp=0},{t="Descending to the Docks",b="From the Temple Gardens, the western portal in Darnassus leads down through the World Tree to Rut'theran Village. At the ocean-level roots, fishing docks and hippogryph perches connect Teldrassil with the rest of Kalimdor. Nessa Shadowsong tends her trade there and prepares shipments for Auberdine.",sp=0}},faq={{q="Who starts this quest?",a="Mydrannul offers the delivery in Darnassus, in the Warrior's Terrace.",al={"quest giver","where to get nessa shadowsong quest","mydrannul location"},gp=true},{q="How do I get to Rut'theran Village?",a="Go west from the Temple Gardens and step through the large, glowing tree portal. It carries you down to Rut'theran Village at the base of Teldrassil.",al={"how to reach ruttheran","rut'theran portal","exit darnassus"},gp=true},{q="Who is Nessa Shadowsong?",a="Nessa Shadowsong is a fishing supplier at the docks of Rut'theran Village. She oversees goods and parcels moving between Teldrassil and Darkshore.",al={"nessa shadowsong role","what does nessa do","nessa shadowsong npc"},it="identity"},{q="Where does this quest chain lead?",a="Speaking with Nessa leads to 'The Bounty of Teldrassil'. It introduces the flight master and provides your first flight across the water to Auberdine.",al={"what comes after nessa shadowsong","next quest in chain","teldrassil flight chain"},it="next_step"},{q="Is Nessa related to Maiev Shadowsong?",a="Nessa and Maiev Shadowsong share a surname, but no personal connection between them is recorded. Nessa is a dockside fishing merchant, while Maiev is a legendary warden.",al={"nessa maiev relation","shadowsong family","is nessa related to maiev"},it="ties"},{q="Why is this errand important for young adventurers?",a="This journey teaches young adventurers how to leave the crown of Teldrassil, reach the docks below, and use hippogryph flight paths to reach mainland Kalimdor.",al={"why do this quest","significance of quest"},it="purpose"},{q="Why does Mydrannul want this done?",a="Mydrannul is simply doing a favor for a friend. Nessa Shadowsong works down at Rut'theran Village as a fishing supplier and needs a reliable courier to carry a parcel across the sea to Darkshore. Mydrannul uses his post in Darnassus to keep an eye out for capable travelers willing to head down the boughs and lend her a hand.",al={"why help nessa","mydrannul reason","why send to nessa shadowsong"},it="motive",add="feb9b9a4"}},ang={["race:NightElf"]="As a night elf, you leave Darnassus's heights for the coastal routes linking your home with Darkshore's ancient shores.",["faction:Alliance"]="As an Alliance adventurer, you learn how Teldrassil connects with the other Alliance territories on Kalimdor."},kw={"auberdine","courier","darkshore","darnassus","mydrannul","nessa shadowsong","portal","rut'theran village","temple gardens"},rel={"quest:6341","quest:6342","quest:6343","subzone:rut-theran-village","zone:darnassus","subzone:temple-gardens","npc:mydrannul","zone:darkshore"},m={start="Mydrannul",["end"]="Nessa Shadowsong",level="10",faction="Alliance",id=6344},src={"Nessa Shadowsong (quest)"}}
E["quest:730"] = {t="quest",n="Trouble in Darkshore?",z="darnassus",s="In Darnassus, Chief Archaeologist Greywhisker seeks help for his missing crew. His introductory appeal sends travelers across the sea to Auberdine, where the dwarven expedition met Darkshore's wild, shadowy coast.",h="In Darnassus, Chief Archaeologist Greywhisker seeks help for his missing crew.",sec={{t="A Silent Expedition",b="Darnassus, the grand night elven capital, is home to dwarven researchers from Ironforge studying Kalimdor's ancient mysteries. Chief Archaeologist Greywhisker sent an excavation party across the water to Darkshore to unearth artifacts of antiquity. Weeks have passed without a message or progress report, and Greywhisker fears his field crew has met dangers they could not survive alone.",sp=0},{t="Threats Unburied",b="Greywhisker laments that many in the Alliance dismiss dwarven archaeology as an eccentric hobby. Findings in Khaz Modan have convinced his colleagues that an ancient, terrifying force threatens Azeroth from Lordaeron to Kalimdor. The work in Darkshore's ruins is more than scholarship: it seeks to understand historic cataclysms and the deep-seated menaces buried beneath ancient soil.",sp=0},{t="Contact at Auberdine",b="Sail across the channel from Teldrassil to Auberdine, the coastal haven, where Archaeologist Hollee waits in town. Relieved that Greywhisker sent help, Hollee says the expedition is in dire straits. The crew ran into trouble farther down the coast while searching for ancient relics.",sp=1}},faq={{q="Who starts the quest Trouble in Darkshore?",a="Chief Archaeologist Greywhisker offers this introductory appeal in Darnassus, seeking travelers to check on his missing crew.",al={"who gives trouble in darkshore","quest giver trouble in darkshore","where to get trouble in darkshore"},it="identity",gp=true},{q="Where do I need to go to complete this quest?",a="Travel from Darnassus across the sea to Auberdine in Darkshore, where Archaeologist Hollee is waiting.",al={"where do i go","turn in location","who do i turn this in to"},it="place",gp=true},{q="Why are dwarven archaeologists in Darnassus and Darkshore?",a="After discoveries in Khaz Modan, dwarven researchers began investigating ancient sites across Kalimdor for clues about ancient forces threatening Azeroth.",al={"why are dwarves in darnassus","dwarves in darkshore","dwarven archaeology kalimdor"},it="purpose"},{q="What happens after finding Archaeologist Hollee?",a="Speaking with Archaeologist Hollee in Auberdine leads into 'The Absent Minded Prospector', which asks you to search Darkshore's wilderness for Prospector Remtravel.",al={"what comes next","follow up quest","next quest"},it="next_step",gp=true},{q="Why hasn't the excavation crew reported back?",a="The crew met unexpected dangers and setbacks in the field in Darkshore. Its members became separated and cut off from communication with Darnassus.",al={"what happened to the dig","why did they disappear","crew missing"},it="conflict"},{q="What looming threat is Greywhisker referring to?",a="Greywhisker points to discoveries in Khaz Modan that suggest an ancient, pervasive danger lies deep within Azeroth's historic ruins.",al={"what ancient threat","greywhisker warning","khaz modan threat"},it="threat"},{q="Why does Chief Archaeologist Greywhisker want this done?",a="Chief Archaeologist Greywhisker has not heard from his excavation crew in Darkshore for weeks. Following ominous discoveries back in Khaz Modan that reveal a great and ancient force threatening all of Azeroth, he cannot afford to lose contact with his researchers, especially when their work is vital to uncovering these looming dangers.",al={"greywhisker motive","why send to darkshore","why find excavation team"},it="motive",add="0c1ca2fe"}},ang={["race:Dwarf"]="As a dwarf, you see the Explorer's League tradition of studying titan lore and ancient history carried to new continents.",["race:NightElf"]="As a night elf, you may regard dwarven excavators arriving in your ancestral coastal ruins with cautious amusement or quiet concern.",["faction:Alliance"]="As an Alliance traveler, you see cooperation growing between Ironforge and Darnassus, linking Teldrassil with mainland Kalimdor."},kw={"archaeologist","auberdine","darkshore","darnassus","explorers league","greywhisker","hollee","trouble in darkshore"},rel={"npc:chief-archaeologist-greywhisker","npc:archaeologist-hollee","quest:729","zone:darkshore","subzone:auberdine","topic:alliance","topic:lordaeron"},m={start="Chief Archaeologist Greywhisker",["end"]="Archaeologist Hollee",level="14",faction="Alliance",id=730},src={"Trouble in Darkshore?"}}
E["quest:8718"] = {t="quest",n="Bladeswift the Elder",z="darnassus",s="During the Lunar Festival, Bladeswift the Elder's ancient spirit is honored in Darnassus. In the Cenarion Enclave, travelers seek his wisdom beneath the stars and a blessing tied to night elven tradition.",h="During the Lunar Festival, Bladeswift the Elder's ancient spirit is honored in Darnassus.",sec={{t="A Spirit of the Boughs",b="During the Lunar Festival, revered ancestral spirits appear across Azeroth to share wisdom and bless travelers. In Darnassus, Bladeswift the Elder appears among the boughs of the Cenarion Enclave. This ancient spirit turns his gaze to the night sky and its mysteries, while the living face the trials of the present.",sp=0},{t="Starlight and Ancient Truths",b="Night elves have long looked to the heavens as reflections of Elune and signs of deeper truths. Bladeswift urges the wise and fortunate to seek answers among the stars. Those who honor him receive a Coin of Ancestry and join a ceremony that links the living with spirits of the past.",sp=0}},faq={{q="Who is Elder Bladeswift?",a="Elder Bladeswift is an ancestral night elf spirit honored during the Lunar Festival. In Darnassus, he offers guidance and blessings to travelers who honor their forebears.",al={"who is bladeswift","elder bladeswift lore","bladeswift identity"}},{q="Where can Elder Bladeswift be found?",a="Elder Bladeswift can be found in the Cenarion Enclave in Darnassus, the night elf capital. He stands among its ponds and wooden walkways.",al={"bladeswift location","where is elder bladeswift","bladeswift darnassus"}},{q="What is the purpose of seeking out the elders?",a="Visiting the elders is a core tradition of the Lunar Festival. Paying respects to these ancient spirits across the world honors the wisdom of the past and earns Coins of Ancestry and seasonal goodwill.",al={"why find elders","lunar festival elders purpose","visiting elders"}},{q="What does Bladeswift teach those who speak with him?",a="Bladeswift teaches seekers to look to the heavens. He says the countless stars hold truths and answers to earthly mysteries for those patient and wise enough to observe them.",al={"bladeswift message","what does bladeswift say"}},{q="Can members of the Horde visit Elder Bladeswift?",a="Bladeswift resides deep inside Darnassus, an Alliance capital guarded by vigilant Sentinels. He welcomes any respectful traveler, though Horde visitors must brave hostile guards to reach him.",al={"can horde talk to bladeswift","horde bladeswift elder","bladeswift alliance only"}},{q="Why is an elder present on Teldrassil if it is a new World Tree?",a="Teldrassil was grown only recently after the Third War, yet the spirits of Kaldorei ancestors are drawn to the living heart of their people. They appear near their kin to observe the festival.",al={"why is bladeswift in darnassus","teldrassil elder lore"}}},ang={["race:NightElf"]="As a night elf, standing before Elder Bladeswift in Darnassus brings you close to your people's celestial heritage and devotion to the heavens.",["class:Druid"]="As a druid, you share a deep cultural and spiritual duty to honor ancient spirits like Bladeswift as a steward of nature aligned with the Cenarion Circle.",["faction:Alliance"]="As an Alliance hero, you can make a safe, easy, and peaceful pilgrimage to Elder Bladeswift inside Darnassus during the Lunar Festival."},kw={"ancestors","bladeswift","coin of ancestry","cenarion enclave","darnassus","elder bladeswift","lunar festival","teldrassil"},m={id=8718},src={"Bladeswift the Elder"}}
E["quest:922"] = {t="quest",n="Rellian Greenspyre",z="darnassus",s="At Denalan's lakeside retreat in Teldrassil, you carry a timberling seed to Rellian Greenspyre in Darnassus. The handoff brings news of trouble spreading through the World Tree's boughs.",h="At Denalan's lakeside retreat in Teldrassil, you carry a timberling seed to Rellian Greenspyre in Darnassus.",sec={{t="A Courier to the Capital",b="Denalan has studied the plants and elemental life around Lake Al'Ameth. After gathering seeds from the local timberlings, he sends you to Darnassus with a sample for his colleague, Rellian Greenspyre. Rellian is a druid who walks the Cenarion Enclave's terraces. He had shown interest in Denalan's research and hopes to grow a timberling of his own.",sp=0},{t="Tainted Growth",b="Rellian receives the seed and brings grim news. His recent studies show that timberlings across Teldrassil are falling to a widespread, aggressive corruption. Seeds from tainted timberlings carry the blight of their parents. Rellian cannot cleanse them with his own skill, and sees Denalan's bond with living things as their best hope.",sp=1}},faq={{q="Who is Rellian Greenspyre?",a="Rellian Greenspyre is a night elf druid who walks the pathways of Darnassus's Cenarion Enclave. He and Denalan share an interest in Teldrassil's ecology and elemental spirits.",al={"rellian greenspyre lore","who is rellian","rellian greenspyre location"},it="identity"},{q="Why does Denalan send a timberling seed to Rellian?",a="Denalan gathered timberling seeds at Lake Al'Ameth with your help. Rellian had shared his interest in timberling life and his own ideas, so Denalan sends him a seed to try growing in the capital.",al={"why send timberling seed","denalan's errand"},it="motive"},{q="What problem does Rellian discover?",a="Rellian finds that corruption has infected the timberlings. Their seeds carry their parents' blight, so healthy sprouts cannot grow until someone finds a cure.",al={"what is wrong with the timberling seed","timberling corruption"},it="threat"},{q="Where does this task lead next?",a="Rellian cannot cure the seeds himself. He sends you to Wellspring Lake in northern Teldrassil to cut down the most tainted timberlings and bring back their mossy tumors to burn.",al={"what comes after rellian greenspyre","next quest after rellian"},sp=1,it="next_step"},{q="Where can Rellian Greenspyre be found?",a="Rellian walks the open pathways of the Cenarion Enclave in Darnassus's northwestern corner.",al={"where is rellian","rellian map location"},it="place",gp=true},{q="Why can't Rellian cleanse the seeds himself?",a="The corruption runs too deep for Rellian's skills. He trusts Denalan's talent for botany and growing living things, and believes his friend is the best hope for curing future generations of timberlings.",al={"why cant rellian cure them","rellian druid powers"},it="power"},{q="Why does Denalan ask an adventurer to deliver the seed instead of going himself?",a="Denalan remains deeply occupied with his research at Lake Al'Ameth, cultivating sprouts and monitoring the afflicted timberlings firsthand. Traveling to the Cenarion Enclave in Darnassus would take him away from his living specimens, so he relies on travelers who have already proven dependable to carry seeds to his druid peers.",al={"why send me rellian","why doesnt denalan deliver it","why me rellian greenspyre"},it="why_me",add="0120e426"}},ang={["class:Druid"]="As a druid of the Cenarion, you see how deeply an unknown sickness has reached into Teldrassil's young life. Native elemental life needs protection.",["race:NightElf"]="As a night elf, you know timberlings were meant to flourish with Teldrassil. Their inherited corruption bodes ill for the kaldorei's new homeland."},kw={"cenarion enclave","corruption","darnassus","denalan","rellian greenspyre","teldrassil","timberling seed"},rel={"npc:denalan","quest:923","zone:darnassus","topic:druid"},m={start="Denalan",["end"]="Rellian Greenspyre",level="7",faction="Alliance",id=922},src={"Rellian Greenspyre (Classic)"}}
E["quest:923"] = {t="quest",n="Tumors",z="darnassus",s="In Darnassus, the Cenarion Circle seeks to contain the sickness spreading through Teldrassil. You are sent to Wellspring Lake to gather mossy tumors from afflicted timberlings, so druids can study the poison and burn the growths safely.",h="In Darnassus, the Cenarion Circle seeks to contain the sickness spreading through Teldrassil.",sec={{t="Blight upon the Timberlings",b="Teldrassil’s native plants and animals are being twisted by a strange affliction. Its timberlings, usually placid nature spirits with bark for skin, have grown hostile and erratic. Grotesque mossy tumors spread across their living wood, pulsing with unnatural poison. Cenarion scholars Denalan and Rellian Greenspyre search for the cause, while timberlings already lost to the sickness must be culled to protect the rest of the boughs.",sp=0},{t="Containment at Wellspring Lake",b="Wellspring Lake in northern Teldrassil has become a focal point of the outbreak, and its timberlings are among the most tainted on the World Tree. Rellian Greenspyre asks you to kill these corrupted guardians and cut away their tumors. Bring the growths to the druids in Darnassus, where they can be burned safely. The night elves hope this will slow the contagion while they search for the disease’s source.",sp=0}},faq={{q="Why are the timberlings growing tumors?",a="A mysterious sickness has taken root in Teldrassil’s wild spirits. The tumors are outward signs of a toxic taint coursing through the timberlings, twisting their natural protective instincts into blind aggression.",al={"what is wrong with timberlings","timberling disease","why timberlings sick"},it="origin"},{q="Who is Rellian Greenspyre?",a="Rellian Greenspyre is a night elf researcher of the Cenarion Circle, stationed in Darnassus. He works with botanists such as Denalan to study the strange corruptions affecting Teldrassil’s living things.",al={"rellian greenspyre lore","who is greenspyre","rellian greenspyre"},it="identity"},{q="Why must the tumors be burned?",a="The tumors are filled with poison that must be cleansed from Teldrassil. Rellian Greenspyre asks you to bring him the growths so they can be burned.",al={"burn tumors","why burn the tumors","destroying mossy tumors"},it="why_wanted"},{q="Where is Wellspring Lake?",a="Wellspring Lake lies in northern Teldrassil, fed by the bough’s pristine waterways. The timberlings along its shores are more diseased than those found elsewhere.",al={"wellspring lake location","where to find timberlings","where are mossy tumors"},it="place",gp=true},{q="Can the timberlings be cured instead of killed?",a="The Cenarion Circle searches for a cure or the blight’s origin, but the timberlings wandering Wellspring Lake are already beyond help. Until the source is found, killing the most aggressive spirits is the only way to safeguard the forest.",al={"can timberlings be saved","curing timberlings"},it="conflict"},{q="What happens after bringing the tumors to Darnassus?",a="After Rellian secures and destroys the tumors, he directs you back to field botanist Denalan near Lake Al’Ameth to continue investigating the corruption spreading through Teldrassil’s flora.",al={"after tumors quest","what next tumors"},it="next_step"},{q="Why does Rellian Greenspyre want this done?",a="A dark malevolence has begun warping Teldrassil's wildlife, and Rellian Greenspyre fears for the safety of the entire bough. While the Cenarion Circle searches for the corruption's root cause, creatures that are already beyond redemption must be purged before their rot spreads across the new world tree.",al={"rellian greenspyre motive","why cull the timberlings","why kill timberlings"},it="motive",add="ab07798c"},{q="What is the Mossy Tumor for?",a="The mossy tumors are physical manifestations of the malevolence sickening the timberlings. Filled with foul poison, they are gathered as proof of the blight's extent and delivered to Rellian Greenspyre in Darnassus so he can safely burn and dispose of them before the rot can spread.",al={"mossy tumor use","what are mossy tumors","mossy tumor purpose"},it="item",add="6d82dc19"},{q="What are the timberlings at Wellspring Lake?",a="Timberlings are plantlike woodland creatures native to Teldrassil. Those dwelling around Wellspring Lake in the north have fallen heavily under an unknown malevolence, turning aggressively hostile and sprouting sickly mossy growths that signal they are too far gone to be spared.",al={"wellspring lake timberlings","what are timberlings","timberling targets"},it="target",add="3565cc38"}},ang={["class:Druid"]="As a druid of the Cenarion Circle, you face the tragic but necessary duty of destroying corrupted nature spirits to protect Teldrassil’s fragile balance from total collapse.",["race:NightElf"]="As a night elf, you see disease appear rapidly in the newly grown World Tree, an alarming sign that challenges Fandral Staghelm’s promise of an untouched haven.",["profession:Herbalism"]="As an herbalist, you may be unsettled to see living wood and moss warp into venomous, malignant tumors instead of healthy foliage. Botanists face the same sight."},kw={"cenarion circle","corruption","darnassus","denalan","mossy tumor","rellian greenspyre","teldrassil","timberling","tumors","wellspring lake"},rel={"quest:922","quest:2498","subzone:wellspring-lake","zone:darnassus","quest:940"},m={start="Rellian Greenspyre",level="9",faction="Alliance",id=923,ri={"Mossy Tumor"}},src={"Tumors"}}
E["quest:9262"] = {t="quest",n="Investigate the Scourge of Darnassus",z="darnassus",s="Lieutenant Beitha calls for help as the Scourge encampments press close to Darnassus. The Argent Dawn needs defenders to strike the undead and learn what the runes outside the gates are for.",h="Lieutenant Beitha calls for help as the Scourge encampments press close to Darnassus.",sec={{t="A Plague on the World Tree",b="The Scourge has reached Teldrassil, and floating necropolises loom above the invasion camps near Darnassus. Ghouls, skeletons, and other undead horrors spill from them. Lieutenant Beitha of the Argent Dawn coordinates the city's defense, calling on volunteers to slow the attack and gather information before the undead overwhelm the night elven homeland.",sp=0},{t="Whispers in the Runes",b="The undead are not the only concern near the Scourge camps. Lieutenant Beitha asks defenders to collect dim necrotic stones from slain Scourge and inspect the glowing runic circles on the ground. Their whispers reach anyone who steps close. The circles carry messages, but Beitha does not know whom the Scourge are contacting.",sp=1}},faq={{q="Who is Lieutenant Beitha?",a="Lieutenant Beitha is an Argent Dawn officer stationed at Darnassus. She organizes resistance to the Scourge and asks defenders to thin their numbers and study their necromantic devices.",al={"who gives investigate the scourge of darnassus","beitha quest giver","lieutenant beitha lore"},it="identity"},{q="Why is the Scourge attacking Darnassus?",a="Scourge forces are camped outside Darnassus beneath a necropolis. Lieutenant Beitha asks defenders to reduce their numbers and investigate nearby runic circles.",al={"why are undead in darnassus","teldrassil invasion","lich king attacking night elves"},it="threat"},{q="What are the glowing runic circles outside the city?",a="The glowing runic circles lie near the Scourge forces. Lieutenant Beitha asks you to investigate their purpose.",al={"scourge runes darnassus","runic circles outside darnassus","what are the invasion runes"},it="place"},{q="What are Dim Necrotic Stones?",a="Dim Necrotic Stones come from Scourge invaders. Defenders bring them to the Argent Dawn as proof of slain undead.",al={"necrotic stones","what do necrotic stones do","dim necrotic stone lore"},it="item"},{q="Who is funding or leading the response in Darnassus?",a="The Argent Dawn coordinates the investigation through Lieutenant Beitha. The order is devoted to opposing the Scourge.",al={"who leads defense of darnassus","argent dawn darnassus"},it="in_charge"},{q="Can listening to the runic circles harm you?",a="No one knows their exact effects. Beitha asks defenders to investigate the strange energy around the circles.",al={"runic circles whispers","runic circle voices danger"},it="danger"},{q="Why does Lieutenant Beitha want this done?",a="The Lich King has sent an undead invasion directly to Teldrassil's doorstep, anchored by a looming Necropolis above Darnassus. Lieutenant Beitha and the Argent Dawn refuse to sit idle while aberrations gather outside the city gates. She needs you to thin their ranks to ease the pressure on the capital, bring proof of their destruction, and uncover the dark purpose behind the glowing runic circles empowering their encampment.",al={"beitha motive","why investigate the scourge","why does beitha need this done"},it="motive",add="39b377fd"},{q="Who are you sent to fight outside Darnassus?",a="You are dispatched against the invading Scourge forces that have set up an encampment just outside Darnassus. These undead thralls and aberrations were deployed directly by the Lich King under the shadow of a hovering Necropolis, seeking to establish a foothold and threaten the night elf capital.",al={"who am i fighting","what are the scourge outside darnassus","who are the invaders"},it="target",add="a5f671f0"}},ang={["race:NightElf"]="As a Kaldorei, you see the necropolises and undead near Teldrassil's holy ground as a violation that must be purged.",["faction:Alliance"]="As an Alliance member, you join Darnassus's defense against the Lich King's invasion force.",["class:Priest"]="As a priest, you face corrupted necromantic runes and the whispers passing through the Scourge's dark network.",["class:Druid"]="As a druid, you see necromancy and decaying flesh on Teldrassil as a blight you are sworn to eradicate."},kw={"argent dawn","beitha","darnassus","lich king","necropolis","necrotic stone","runic circle","scourge","teldrassil","undead"},rel={"zone:darnassus","topic:argent-dawn","topic:scourge","topic:lich-king"},m={start="Lieutenant Beitha",level="10",faction="Alliance",id=9262},src={"Investigate the Scourge of Darnassus"}}
E["quest:952"] = {t="quest",n="Grove of the Ancients",z="darnassus",s="A dispatch carries you from Darnassus to Darkshore, where Onu waits in the Grove of the Ancients. Arch Druid Fandral Staghelm sends you across the sea with correspondence for the Ancient of Lore, who lives south of Auberdine.",h="A dispatch carries you from Darnassus to Darkshore, where Onu waits in the Grove of the Ancients.",sec={{t="Leaving the Boughs",b="After you help with matters at the Oracle Glade atop Teldrassil, Arch Druid Fandral Staghelm summons you for another duty. He sends you across the sea to Darkshore with an urgent dispatch for Onu. From Darnassus, you can book a flight aboard a hippogryph.",sp=0},{t="A Contrast in Patience",b="South of Auberdine, you reach the Grove of the Ancients and deliver the missive to Onu. The towering Ancient of Lore accepts it quietly and remarks on Staghelm's impatience. Onu and the forest's ancient keepers believe all things unfold in their proper time. Shan'do Malfurion Stormrage embodied that patient wisdom, while Staghelm lacks it.",sp=0}},faq={{q="Who starts the quest Grove of the Ancients?",a="Arch Druid Fandral Staghelm sends you from the Cenarion Enclave in Darnassus after you complete his earlier errand concerning the Oracle Glade.",al={"quest giver grove of the ancients","who gives grove of ancients","fandral staghelm quest"},gp=true},{q="Where is the Grove of the Ancients located?",a="The Grove of the Ancients lies on the mainland in Darkshore, directly south of the coastal port of Auberdine.",al={"grove of the ancients location","where is grove of ancients","onu location"},it="place",gp=true},{q="Who is Onu?",a="Onu is a wise and venerable Ancient of Lore in Darkshore. He protects and records natural wisdom, and receives correspondence from Darnassus's druidic leadership.",al={"who is onu","onu darkshore","ancient of lore onu"},it="identity"},{q="How do you reach Darkshore from Teldrassil?",a="From Darnassus, travel to Rut'theran Village and take a hippogryph across the water to Auberdine, Darkshore's port settlement.",al={"how to get to darkshore","travel to auberdine","hippogryph to darkshore"},gp=true},{q="Why does Onu mention Shan'do Stormrage?",a="Onu remarks on Arch Druid Staghelm's restless haste after receiving the missive. He says the forest moves at its own pace, with a patience Shan'do Malfurion Stormrage understood and respected.",al={"onu malfurion comment","shan'do stormrage reference","why mention shando"},it="ties"},{q="What quests come before this one?",a="This is the last step in a short sequence of three parts. It begins with The Enchanted Glade, continues with Teldrassil, then sends you out to Darkshore.",al={"prerequisites grove of the ancients","grove of the ancients chain","quests before onu"},it="history",gp=true},{q="Why does Arch Druid Fandral Staghelm want this message delivered to Onu?",a="Fandral Staghelm is eager to maintain close communication with the ancient protectors across the sea in Kalimdor. Onu, an Ancient of Lore rooted in Darkshore, has been awaiting word from the Arch Druid regarding affairs on Teldrassil. Now that Fandral has received the latest reports from the Oracle Glade, he is impatient to transmit his findings and instructions without delay, pressing forward with his plans for the night elves.",al={"why send message to onu","fandral motive grove of the ancients","why does fandral need this delivered"},it="motive",add="00893f03"},{q="Why does Fandral Staghelm choose you to deliver his message?",a="Having seen you carry word from the Oracle Glade to Darnassus, Fandral figures you are already capable of running sensitive errands across distances. Rather than diverting seasoned Cenarion emissaries or Sentinels from their duties, he simply presses a proven courier into service to ferry his missive to Darkshore.",al={"why me fandral message","why send player to onu","why not send a sentinel"},it="why_me",add="658e120a"}},ang={["race:NightElf"]="As a Night Elf, you leave Teldrassil's sheltered cradle for the wider wilds of mainland Kalimdor. The journey shows the contrast between Fandral Staghelm and Malfurion Stormrage's teachings.",["class:Druid"]="As a druid, you carry a missive between Darnassus's Arch Druid and Onu. Their different temperaments show Staghelm's drive beside an Ancient of Lore's quiet patience.",["faction:Alliance"]="As an Alliance champion, you leave your business in Darnassus with reason to secure hippogryph routes and explore Darkshore's coast."},kw={"ancient of lore","auberdine","cenarion circle","darkshore","darnassus","fandral staghelm","grove of the ancients","onu","oracle glade"},rel={"quest:940","quest:937","zone:darkshore","subzone:auberdine","topic:druid","subzone:oracle-glade","topic:shan-do"},m={start="Arch Druid Fandral Staghelm",["end"]="Onu",level="11",faction="Alliance",id=952},src={"Grove of the Ancients (quest)"}}
E["quest:98397"] = {t="quest",n="To Darnassus",z="darnassus",s="In Darnassus, your trial with the Great Cat Spirit brings you back to the Cenarion Enclave. After proving yourself to Dendrite Starblaze in Moonglade, you return to Mathrengyl Bearwalker to learn cat form.",h="In Darnassus, your trial with the Great Cat Spirit brings you back to the Cenarion Enclave.",sec={{t="Return to the Enclave",b="You return to Teldrassil after communing with the Great Cat Spirit under Dendrite Starblaze's guidance in Moonglade. Starblaze sees that you have proved yourself a worthy student and sends you to your primary instructor, Mathrengyl Bearwalker. He waits beneath the boughs of the Cenarion Enclave in Darnassus.",sp=0},{t="The Nature of the Cat",b="In Darnassus, Mathrengyl Bearwalker recognizes the wisdom you have gained from the Great Cat Spirit. Every generation of druids faces a trial shaped by this ancient spirit, playful yet deadly. Your bond is established and your spirit prepared; Mathrengyl teaches you the final rites for taking the cat's form.",sp=0}},faq={{q="What is the purpose of this quest?",a="This is the final part of your trial with the Great Cat Spirit. After your time with Dendrite Starblaze in Moonglade, you return to Mathrengyl Bearwalker in Darnassus, who teaches you to take cat form.",al={"why do this quest","to darnassus purpose","cat form quest"},it="purpose"},{q="Who sends you back to Darnassus?",a="Dendrite Starblaze, a senior druid who lives in Nighthaven in Moonglade, sends you back after you receive the Great Cat Spirit's blessing.",al={"who starts this quest","quest giver"},it="identity"},{q="Where can I find Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker waits in the Cenarion Enclave, in Darnassus's northwestern quarter on Teldrassil.",al={"mathrengyl location","where is bearwalker"},it="target",gp=true},{q="What is the significance of the Great Cat Spirit?",a="The Great Cat Spirit is an ancient, feral spirit of nature tied to agile, deadly predators. Druids must earn its favor and understand its playful yet lethal nature before they can channel its shape.",al={"cat spirit lore","what is great cat spirit"},it="history"},{q="Do all druids complete the exact same trial?",a="Mathrengyl Bearwalker says all druids must pass a trial granted by the Great Cat Spirit to master its form, though the trials vary across generations.",al={"are druid trials the same","generation trials"}},{q="Can non-night elves take this quest?",a="This path is for Alliance night elf druids returning to Darnassus. Tauren druids follow their own path and report to their trainers in Thunder Bluff after visiting Moonglade.",al={"is this alliance only","can tauren do this"},gp=true},{q="Why does Dendrite Starblaze send you back to Darnassus?",a="You have proved your worth before the Great Cat Spirit in Moonglade, and your trials under Dendrite Starblaze are complete. Dendrite's duty was to oversee your communion with the ancient spirit; now, your initial trainer, Mathrengyl Bearwalker, awaits your return in Darnassus to help you apply those spiritual lessons and finally master the shapeshifting art of the cat.",al={"why send to darnassus","dendrite starblaze motive","why return to mathrengyl"},it="motive",add="5fd4c60a"}},ang={["class:Druid"]="As a druid, Cat Form lets you channel the Great Cat Spirit directly.",["race:NightElf"]="As a night elf, your return to Darnassus honors the traditions the Cenarion Circle keeps beneath Teldrassil.",["faction:Alliance"]="As an Alliance druid, you return from neutral Moonglade to Darnassus, strengthening your homeland's magical defenses."},kw={"cat form","cenarion enclave","dendrite starblaze","great cat spirit","mathrengyl bearwalker","moonglade","teldrassil","to darnassus"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","subzone:cenarion-enclave","zone:darnassus","topic:druid"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="20",faction="Alliance",id=98397},src={"To Darnassus (Forever)"},fv=true}
E["subzone:cenarion-enclave"] = {t="subzone",n="Cenarion Enclave",z="darnassus",s="The Cenarion Circle gathers in Darnassus beneath Fandral Staghelm’s leadership of the night elven druids. The Cenarion Enclave is their central gathering place and seat of power in the capital, among its great hollows and living boughs.",h="The Cenarion Circle gathers in Darnassus beneath Fandral Staghelm’s leadership of the night elven druids.",sec={{t="Heart of the Circle",b="High above the Temple Gardens, the Cenarion Enclave gathers the Cenarion Circle beneath ancient oaks and ashes marked with runic bark. Its halls take shape from living wood and stone. With Malfurion Stormrage absent in the Emerald Dream, Archdruid Fandral Staghelm oversees affairs here and presses his ambitious vision for Teldrassil despite political friction with High Priestess Tyrande Whisperwind. Druids meditate by the streams, while the capital’s elven hunters gather here too. At the stables, skilled riders learn to tame Darnassian nightsabers.",sp=0},{t="Shadows in the Boughs",b="The Cenarion Enclave is known as a tranquil sanctuary, yet quiet business takes place beneath its westernmost bough. A refuge lies under the hollowed roots, where Darnassus’s clandestine rogues work shielded by the canopy above.",sp=0}},faq={{q="Who leads the Cenarion Enclave?",a="Archdruid Fandral Staghelm leads the grove and the night elven druids residing in Darnassus. Malfurion Stormrage, the supreme leader of the Cenarion Circle, remains trapped in a deep, unexplained slumber within the Emerald Dream, leaving Staghelm as the de facto authority.",al={"who is in charge here","cenarion enclave leader","fandral staghelm"},it="residents"},{q="What classes train here?",a="The Cenarion Enclave is the primary home of Darnassus’s druid trainers, who teach novices among the living trees. Hunter trainers work in the eastern boughs, while rogue trainers have a quiet den in the root warrens beneath the western bough.",al={"trainers in cenarion enclave","druid trainer darnassus","hunter trainer darnassus"},it="purpose",gp=true},{q="Where can I buy a nightsaber mount?",a="Riding trainers and breeders who tend Darnassus’s saber cats wait at the base of the eastern tree near the grove’s entrance. They offer riding training and nightsaber mounts to eligible Alliance travelers.",al={"nightsaber trainer","night elf mount trainer","darnassus riding trainer"},gp=true},{q="What is the Cenarion Circle's stance toward the Alliance?",a="The Cenarion Circle is dedicated to safeguarding the natural order rather than fighting factional wars, though its enclave lies in an Alliance capital. Archdruid Fandral Staghelm leads the enclave and is staunchly nationalist, aligning it strongly with night elven regional interests.",al={"is cenarion circle alliance","are druids alliance only"},it="ties"},{q="What is the Cenarion Enclave?",a="The Cenarion Enclave is a lush grove and district nestled in the northwestern boughs of Darnassus. Characterized by ancient oaks and ashes etched with mystical runes, it serves as the city's heart of druidic life and thought. While the Temple of the Moon guides the priesthood, the Enclave gathers the scholars, healers, and tenders of nature to deliberate, teach, and hone their spiritual arts.",al={"cenarion enclave darnassus","what is cenarion enclave","about cenarion enclave"},it="place",add="cda262fb"},{q="What happened at the Cenarion Enclave?",a="The Enclave developed alongside Darnassus as a gathering place for the capital's druids. Its sanctuaries combine living wood and shaped stone. Archdruid Fandral Staghelm resides in the largest of these structures and leads the druids while Malfurion Stormrage remains absent in the Emerald Dream.",al={"cenarion enclave history","history of cenarion enclave","what happened here"},it="history",add="fed5260a"},{q="Is the Cenarion Enclave dangerous?",a="No. The Enclave is one of the most serene and heavily guarded districts in Darnassus, filled with veteran druids, skilled hunters, and watchful treant protectors. Unless you harbor hostility toward the night elves and the Alliance, you will find it a peaceful sanctuary of meditation and study.",al={"is cenarion enclave safe","cenarion enclave danger","cenarion enclave hostile"},it="danger",add="1a9fb52b"},{q="Why is it called the Cenarion Enclave?",a="It takes its name from the Cenarion Circle, the druidic order dedicated to preserving nature and honoring Cenarius, the demigod and patron lord of all druids. As the primary seat for the Circle's practitioners within the night elf capital, it stands as an enclave set apart specifically for their ancient craft and commune with nature.",al={"why is it called cenarion enclave","cenarion enclave name origin","who named cenarion enclave"},it="name",add="88e7d09b"}},ang={["class:Druid"]="As a night elf druid, you find the civil center of your order on Teldrassil here, with training and guidance under Archdruid Fandral Staghelm’s stern direction.",["class:Hunter"]="As a hunter, you hone your marksmanship and wilderness lore in the enclave’s eastern boughs, alongside beastmasters who rear Darnassus’s nightsabers."},kw={"cenarion circle","cenarion enclave","darnassus","druid","fandral staghelm","nightsaber","teldrassil"},rel={"npc:fandral-staghelm","zone:darnassus","topic:druid","topic:emerald-dream","npc:malfurion-stormrage","npc:tyrande-whisperwind","subzone:temple-gardens","quest:929"},src={"Cenarion Enclave"}}
E["subzone:craftsmen-s-terrace"] = {t="subzone",n="Craftsmen's Terrace",z="darnassus",s="Craftsmen's Terrace gathers Darnassus's trades along the city's northern edge. Its workshops, trainers, inn, and Argent Dawn embassy draw artisans and visitors alike.",h="Craftsmen's Terrace gathers Darnassus's trades along the city's northern edge.",sec={{t="The Artisan Heart of Darnassus",b="Woodworkers, leathercrafters, alchemists, and other artisans work along the northern edge of Darnassus. Their shops bring together many of the trades that keep the city running, using night elven methods for practical crafts. You can also find an inn, a guild master, and guild petition vendors here. Bridges lead west to the Cenarion Enclave and south to the Warrior's Terrace.",sp=0},{t="Outside Ties and Forgotten Lore",b="The Argent Dawn keeps an embassy in the Craftsmen's Terrace, coordinating with northern allies against the Scourge. The district's workshops also hold scattered scholarly volumes. Among them are histories of the War of the Ancients, chronicles of the Second War, and treatises on the Old Gods.",sp=0}},faq={{q="What services are found in the Craftsmen's Terrace?",a="The Craftsmen's Terrace has trade profession trainers, craft supply merchants, an inn, and guild registry services. Travelers come here to learn or practice practical skills in Darnassus.",al={"craftsmen services","what is in craftsmens terrace","darnassus trainers"},it="purpose",gp=true},{q="Why is the Argent Dawn present in the Craftsmen's Terrace?",a="The Argent Dawn keeps an embassy in the Craftsmen's Terrace to liaise with the night elves and recruit aid against the Scourge. It connects the Alliance forces in the west with the war-torn lands of Lordaeron.",al={"argent dawn darnassus","argent dawn embassy","why argent dawn here"},it="ties"},{q="How do you reach the Craftsmen's Terrace?",a="The Craftsmen's Terrace occupies Darnassus's northern section. Bridges lead north from the Warrior's Terrace and east from the Cenarion Enclave.",al={"how to get to craftsmen terrace","craftsmen terrace location","finding craftsmen terrace"},it="arrival",gp=true},{q="What notable books can be found around the workshops?",a="Scholarly volumes in the workshops include histories of the War of the Ancients, accounts of the aftermath of the Second War, and a study of the Old Gods in the Argent Dawn's quarters.",al={"craftsmen terrace books","lore books darnassus","books in craftsmens terrace"}},{q="What is the Craftsmen's Terrace?",a="The Craftsmen's Terrace is a bustling northern district within Darnassus, the capital city of the night elves on Teldrassil. It serves as the primary trade and artisan hub for the Kaldorei, gathering trainers, merchants, and workshops under the boughs of the World Tree. Here, travelers and citizens find skilled craftspeople practicing their trades, guild services, a welcoming inn, and an official embassy maintained by the Argent Dawn.",al={"what is craftsmens terrace","craftsmen terrace darnassus","about craftsmens terrace"},it="place",add="7384ca35"},{q="Why is it called the Craftsmen's Terrace?",a="The district takes its name from its role as the center of industry and trade in Darnassus. It houses the city's profession trainers, supply vendors, and artisan workshops, making it the gathering place for the night elves' craftsmen, builders, and tradesfolk.",al={"why is it called craftsmens terrace","craftsmens terrace name meaning","craftsmens terrace name"},it="name",add="ef9e89a7"},{q="Is the Craftsmen's Terrace dangerous?",a="No. The Craftsmen's Terrace is a secure civilian district inside the night elven capital of Darnassus. Protected by the Sentinels and watched over by local artisans and the Argent Dawn, it is entirely peaceful and free of hostile threats for members of the Alliance.",al={"is craftsmens terrace safe","danger craftsmens terrace","craftsmens terrace threats"},it="danger",add="1dc55189"}},ang={["race:NightElf"]="As a kaldorei, you can see the terrace's self-reliance on Teldrassil, where ancient craftsmanship meets the daily needs of the new capital.",["faction:Alliance"]="As an Alliance visitor, you find trade supplies, guild services, and lodging in one of Darnassus's most welcoming quarters, alongside foreign representatives."},kw={"argent dawn","artisans","craftsmen's terrace","craftsmens terrace","darnassus","teldrassil","trainers"},rel={"zone:darnassus","subzone:cenarion-enclave","subzone:warrior-s-terrace","topic:argent-dawn","topic:night-elf","topic:war-of-the-ancients","topic:old-god","topic:second-war"},src={"Craftsmen's Terrace"}}
E["subzone:temple-gardens"] = {t="subzone",n="Temple Gardens",z="darnassus",s="Temple Gardens gather the waters and bridges at Darnassus's heart, with the city bank on their main island. The Temple of the Moon borders them to the south, and a glowing tree portal carries travelers to Teldrassil's base.",h="Temple Gardens gather the waters and bridges at Darnassus's heart, with the city bank on their main island.",sec={{t="Heart of the Elven Capital",b="Water and wooden bridges cross the center of Darnassus, linking the Temple Gardens' islets to the Cenarion Enclave in the north, the terraces to the east, and the Temple of the Moon to the south. Night elves tend the flowing waters and foliage, making a quiet place of rest for travelers and priestesses.",sp=0},{t="Gateway to Teldrassil",b="The main island holds Darnassus's central vault and bank. On the western bank, a massive glowing pink tree portal carries travelers through the boughs to Rut'theran Village at Teldrassil's base. From there, the coastal docks and flight paths connect the World Tree to other destinations.",sp=0}},faq={{q="What is the glowing pink portal in the gardens?",a="The glowing tree portal on the gardens' western edge carries travelers between Teldrassil's crown and its base. It takes them to Rut'theran Village, where ships and hippogryphs connect the night elves to darkshore and the wider world.",al={"tree portal darnassus","pink tree portal","teleporter darnassus"}},{q="Where is the Darnassus bank located?",a="Darnassus's main bank occupies an open elven pavilion on the Temple Gardens' largest central island.",al={"darnassus bank location","where is bank","banker darnassus"},gp=true},{q="Why are they called the Temple Gardens?",a="The gardens take their name from the Temple of the Moon, which borders them to the south.",al={"temple gardens name origin","why temple gardens"},it="name"},{q="Which districts connect to the Temple Gardens?",a="Bridges cross the water from the Temple Gardens to the Cenarion Enclave in the north, the Craftsmen's, Warrior's, and Tradesmen's Terraces to the east, and the Temple of the Moon to the south.",al={"where do temple gardens lead","bridges from temple gardens"},it="place",gp=true},{q="What is the Temple Gardens?",a="The Temple Gardens form the verdant, tranquil heart of Darnassus. Spread across a central lake, this scenic district features lush islets, winding wooden bridges, and manicured flora sustained through night elven nature magic. The area hosts the city bank on its central island and serves as a natural crossroads linking the capital's surrounding terraces with the Temple of the Moon.",al={"temple gardens darnassus","what is temple gardens","temple garden lore"},it="place",add="15ee89a5"},{q="What happened at the Temple Gardens?",a="The gardens were grown and shaped alongside the rest of Darnassus following the Third War, crafted atop the boughs of Teldrassil to provide a place of beauty and peaceful contemplation. Night elven caretakers carefully guided the waters and cultivated delicate flora to create a serene sanctuary that priests, leaders, and visitors use for reflection.",al={"history of temple gardens","temple gardens history","what happened in temple gardens"},it="history",add="a5d2a9ad"},{q="Is the Temple Gardens dangerous?",a="Not at all. The gardens sit securely in the interior of Darnassus, guarded by Sentinels and shielded by the capital's defenses. It is one of the most peaceful and heavily trafficked districts in the city, entirely free of wild beasts or hostile threats.",al={"is temple gardens safe","danger in temple gardens","are temple gardens dangerous"},it="danger",add="6a127887"}},ang={["race:NightElf"]="As a night elf, you find the gardens where wilderness and civic architecture meet, a place for quiet reflection amid Darnassus's daily affairs.",["faction:Alliance"]="As an Alliance visitor arriving by ship, you pass through the Rut'theran portal to reach the city's tranquil waters and the rest of Darnassus."},kw={"bank","darnassus","portal","rut'theran","teldrassil","temple gardens","temple of the moon"},rel={"zone:darnassus","subzone:temple-of-the-moon","subzone:rut-theran-village","subzone:cenarion-enclave","subzone:tradesmen-s-terrace","quest:940","quest:2519"},src={"Temple Gardens"}}
E["subzone:temple-of-the-moon"] = {t="subzone",n="Temple of the Moon",z="darnassus",s="High Priestess Tyrande Whisperwind guides her people from the Temple of the Moon in Darnassus. The sanctuary is the seat of government on Teldrassil and home to the Sisterhood of Elune, whose priestesses tend a sacred moonwell.",h="High Priestess Tyrande Whisperwind guides her people from the Temple of the Moon in Darnassus.",sec={{t="Sanctuary of the Moon Goddess",b="Built soon after the Third War, the Temple of the Moon rose as the night elves settled Teldrassil. It is among the largest stone structures made by modern kaldorei hands. Its marble came from quarries on the Kalimdor mainland and crossed the sea by magical means. At the heart of the temple, a broad moonwell rests beneath the statue of Haidene. Pilgrims come to worship and reflect beside its consecrated waters. The temple also holds Darnassus's highest seat of government, where High Priestess Tyrande Whisperwind guides her people through a new age.",sp=0},{t="The Sisterhood's Bastion",b="The priestesses of the Sisterhood of Elune serve their goddess from the temple's terraces, in worship and in the field. Emissaries and dispatched sisters travel across northern Kalimdor to investigate threats or aid local sentinels. Priestess Gwennyth Bly'Leggonde, for example, makes inquiries along the Darkshore coastline. Novices and veteran priestesses gather beneath the starry vaulted ceiling to learn divine spellwork, tend the wounded, and guard the sanctum from outside corruption.",sp=0}},faq={{q="Who leads the Temple of the Moon?",a="High Priestess Tyrande Whisperwind presides over the Temple of the Moon. She leads the Sisterhood of Elune and heads the kaldorei government, guiding Darnassus in spiritual and military affairs.",al={"temple of the moon leader","who is in the temple","tyrande location"},it="residents"},{q="How was the temple built on Teldrassil?",a="Teldrassil grew from boughs across the ocean, but the Temple of the Moon was built of stone. Its marble and masonry came from the Kalimdor mainland and reached the world tree's summit by magical means.",al={"how was temple of the moon built","stone temple darnassus origins"}},{q="What is the pool in the center of the temple?",a="The pool at the temple's center is a sacred moonwell beneath the statue of Haidene. The Sisterhood uses its consecrated waters for cleansing rites, meditation, and restorative magic, and reveres them as a blessing of Elune.",al={"temple moonwell","water in temple of the moon"}},{q="What services can players find here?",a="Priests train at the Temple of the Moon in Darnassus. High Priestess Tyrande Whisperwind also gives guidance there, and the Sisterhood sends adventurers on assignments.",al={"what is in temple of elune","temple trainers darnassus"},gp=true},{q="What is the Temple of the Moon?",a="The Temple of the Moon is the grand sanctuary of Elune and the spiritual heart of the night elves. Standing as one of the largest stone structures on Teldrassil, it serves as the sacred dwelling for the Sisters of Elune and the de facto seat of governance for Darnassus, housing High Priestess Tyrande Whisperwind.",al={"temple of the moon darnassus","what is this temple","temple of elune darnassus"},it="place",add="18c3233a"},{q="What happened at the Temple of the Moon?",a="Constructed alongside Darnassus in the wake of the Third War, the temple was built from stone magically brought over from the mainland. Since its creation, it has served as the command center where High Priestess Tyrande Whisperwind and the Sisterhood of Elune oversee the affairs and spiritual guidance of the kaldorei.",al={"temple of the moon history","what happened here","temple of elune history"},it="history",add="fde18cfb"},{q="Is the Temple of the Moon dangerous?",a="Not at all for allies of the night elves. It is one of the most secure, tranquil sanctuaries in all of Teldrassil, watched over by seasoned priestesses, Sentinels, and the High Priestess herself. However, any who dare bring hostility or corruption into Elune's sanctum will face swift and lethal retribution.",al={"is temple of the moon dangerous","is it safe here","temple of elune danger"},it="danger",add="7506a07b"},{q="Why is it called the Temple of the Moon?",a="The sanctuary is dedicated to Elune, the revered moon goddess of the kaldorei. The night elves view her as the mother of their people and the source of sacred light, naming their grandest halls and sanctums in honor of her shining presence.",al={"why temple of the moon","temple name origin","why named temple of the moon"},it="name",add="7361c49d"}},ang={["class:Priest"]="For an Alliance priest, especially a night elf, the Temple of the Moon is the foremost source of Elune's divine mandate and home to the highest priestly trainers.",["race:NightElf"]="For a night elf, the Temple of the Moon brings together kaldorei civic and spiritual life, the Sisterhood of Elune, and Teldrassil's government."},kw={"darnassus","haidene","moonwell","sisterhood of elune","teldrassil","temple of elune","temple of the moon","tyrande whisperwind"},rel={"zone:darnassus","npc:tyrande-whisperwind","topic:elune","quest:2519","quest:3524","npc:gwennyth-bly-leggonde","npc:malfurion-stormrage","topic:third-war"},src={"Temple of the Moon"}}
E["subzone:tradesmen-s-terrace"] = {t="subzone",n="Tradesmen's Terrace",z="darnassus",s="Tradesmen's Terrace gathers Darnassus's merchants and craftspeople along the city's southern edge. Its auction house and shops connect travelers with goods from Teldrassil and beyond.",h="Tradesmen's Terrace gathers Darnassus's merchants and craftspeople along the city's southern edge.",sec={{t="The Commercial Hub of Darnassus",b="Tradesmen's Terrace fills the southern stretch of Darnassus with shops and merchants. Here, kaldorei and travelers from the wider Alliance find provisions, crafting supplies, and the city's central auction house. Paths lead north to the Warrior's Terrace and west toward the Temple Gardens and the Temple of the Moon. For journeys into the wilds, this is where travelers gather what they need.",sp=0},{t="Artisans and Traders",b="Kaldorei shops favor quiet stone, timber, and woven goods, shaped to live in harmony with nature. The terrace has none of the roaring furnaces or smog found in dwarven and human workshops. Adventurers seeking trade contracts, repairs, or materials gathered from Teldrassil's boughs find the principal center of business in northern Kalimdor here.",sp=0}},faq={{q="What is Tradesmen's Terrace?",a="Tradesmen's Terrace is Darnassus's southern marketplace, with merchants, craftspeople, and the city's central auction house.",al={"what is this place","tradesmens terrace info","tradesmen terrace darnassus"},it="place"},{q="Where is the auction house in Darnassus?",a="Darnassus's auction house stands in Tradesmen's Terrace, where travelers, traders, and locals can take part in citywide and Alliance commerce.",al={"darnassus auction house","ah location darnassus","where is ah"},gp=true},{q="How do I reach the other districts from here?",a="Paths lead north from Tradesmen's Terrace to the Warrior's Terrace and west toward the Temple Gardens and the Temple of the Moon.",al={"exits from tradesmens terrace","where does this terrace lead","how to leave tradesmens terrace"},gp=true},{q="What kinds of vendors are found in this district?",a="Tradesmen's Terrace has general merchants, trade supplies, and craftspeople offering everyday goods, repairs, and goods made across Teldrassil.",al={"vendors tradesmens terrace","what can i buy here","tradesmen shops"},gp=true},{q="Is Tradesmen's Terrace dangerous?",a="Not at all. Tradesmen's Terrace is one of the safest and most heavily populated sectors in Darnassus. As the bustling commercial heart of the night elf capital, it is constantly patrolled by city sentinels and filled with merchants, artisans, and fellow Alliance travelers conducting peaceful business.",al={"is tradesmens terrace safe","danger tradesmens terrace","tradesmens terrace safe"},it="danger",add="f0c60839"},{q="Why is it called Tradesmen's Terrace?",a="The district takes its name directly from its role as Darnassus's primary hub of trade and craftsmanship. It serves as the designated commercial terrace of the capital, hosting the city's guild artisans, shopkeepers, general suppliers, and central auction house.",al={"why tradesmens terrace","name tradesmens terrace","why is it named tradesmens terrace"},it="name",add="a7d49f79"}},ang={["race:NightElf"]="As a night elf, you find dense commerce in Tradesmen's Terrace, shaped to preserve Darnassus's peaceful canopy without the disruptive industry of other races.",["faction:Alliance"]="As an Alliance traveler arriving through Rut'theran Village, you can find banking, auctioneers, and trade supplies in Tradesmen's Terrace before heading deeper into Kalimdor."},kw={"auction house","darnassus","kaldorei","merchants","shops","teldrassil","tradesmen's terrace","vendors"},rel={"zone:darnassus","subzone:warrior-s-terrace","subzone:temple-gardens","subzone:temple-of-the-moon","topic:night-elf","quest:940"},src={"Tradesmen's Terrace"}}
E["subzone:warrior-s-terrace"] = {t="subzone",n="Warrior's Terrace",z="darnassus",s="At Darnassus's eastern edge, Sentinels patrol the Warrior's Terrace and its fortified gate. The district houses battlemasters and warrior trainers, with open plazas for drills and duels overlooking the road into greater Teldrassil.",h="At Darnassus's eastern edge, Sentinels patrol the Warrior's Terrace and its fortified gate.",sec={{t="Shield of Darnassus",b="Sentinels guard Darnassus at the Warrior's Terrace, also called the Hall of Justice. Mounted on nightsabers, they watch the high arched gates for travelers coming from the Teldrassil wilds. In the open-air plazas, aspiring combatants drill beside seasoned veterans on dueling grounds and target ranges. Weapon smiths and armorers meet practical military needs, while battlemasters coordinate night elf forces across the wider world.",sp=0}},faq={{q="What is the purpose of the Warrior's Terrace?",a="The Warrior's Terrace is Darnassus's military heart and its main defensive gateway. Martial trainers and battlemasters work there, combatants use the dueling grounds and target ranges, and Sentinels guard the eastern gate toward greater Teldrassil.",al={"what is warrior's terrace","warriors terrace purpose","why warriors terrace"},it="purpose"},{q="Where does the road through the eastern gate lead?",a="The road through the eastern gates leaves Darnassus and reaches the forest paths of greater Teldrassil. Those paths connect the capital to settlement hubs such as Dolanaar and Rut'theran Village below.",al={"where does gate go","warriors terrace gate","east gate darnassus"}},{q="Who guards the district?",a="Sentinels guard the Warrior's Terrace and its perimeter gates. Many patrol the terraces and gateways on armored nightsabers.",al={"who protects warriors terrace","sentinels at warriors terrace","darnassus guards"},it="in_charge"},{q="Which other districts connect to the Warrior's Terrace?",a="Bridges and walkways connect the Warrior's Terrace to the Craftsmen's Terrace to the north, the Tradesmen's Terrace to the south, and the Temple Gardens toward the city's center to the west.",al={"connections warriors terrace","how to get to warriors terrace","what connects to warriors terrace"}},{q="What is the Warrior's Terrace?",a="The Warrior's Terrace is the easternmost district of Darnassus, guarding the great gates that lead out into the wilds of Teldrassil. Serving as the primary military hub of the night elven capital, it houses dueling grounds, target ranges, and barracks where Sentinels, warrior trainers, and battlemasters gather to drill and defend the realm.",al={"what is warrior terrace","warriors terrace info","about warriors terrace"},it="place",add="162de6c0"},{q="Why is it called the Warrior's Terrace?",a="The terrace earned its name as the martial heart of Darnassus. It is the dedicated staging ground and training area for night elven warriors, Sentinels, and battlemasters honing their combat prowess, while also standing as the city's first line of defense against any assault upon its gates.",al={"why is it called warriors terrace","warrior terrace name meaning","why warriors terrace"},it="name",add="4e3ffca6"},{q="Is the Warrior's Terrace dangerous?",a="For visitors of the Alliance, the terrace is entirely safe. It serves as Darnassus's most heavily guarded stronghold, protected day and night by vigilant Sentinels mounted on nightsabers. Unless you provoke a sparring match on the dueling grounds or dare cross into the city as an enemy of the kaldorei, you face no peril here.",al={"is warriors terrace dangerous","warrior terrace safety","threats in warriors terrace"},it="danger",add="d3913307"}},ang={["class:Warrior"]="As a warrior training in the night elf capital, you can find martial instructors, dueling areas, and battlemasters at the Warrior's Terrace.",["profession:Blacksmithing"]="At the Warrior's Terrace, you can find blacksmithing trainers and forge facilities for crafting armor and weapons alongside the garrison."},kw={"battlemasters","darnassus","dueling grounds","east gate","hall of justice","sentinels","teldrassil","warrior's terrace"},rel={"zone:darnassus","quest:940","subzone:craftsmen-s-terrace","subzone:tradesmen-s-terrace","subzone:temple-gardens","topic:sentinels","topic:night-elf"},src={"Warrior's Terrace"}}
E["zone:darnassus"] = {t="city",n="Darnassus",z="darnassus",s="Darnassus shelters the night elves high among Teldrassil’s branches. Tyrande Whisperwind and the druids guide the city, where an ancient people face life without immortality and seek ties with the Alliance.",h="Darnassus shelters the night elves high among Teldrassil’s branches.",sec={{t="A Crown High in the Branches",b="Darnassus spreads across Teldrassil’s upper canopy, off northern Kalimdor’s coast. Wooden buildings and winding paths circle a quiet central lake. Bridges join terraces for tradesmen, craftsmen, Sentinels, and druids, leaving the wilderness close to the city’s daily life.",sp=0},{t="Refuge of a Mortal People",b="Darnassus is young beside the civilization of the kaldorei. After the Third War and the sacrifice of Nordrassil at Mount Hyjal, the night elves faced aging and sickness. With Archdruid Malfurion Stormrage lost in the Emerald Dream, Archdruid Fandral Staghelm and his followers planted Teldrassil in hope of renewing their lost vitality. The city grew among its boughs as refuge and monument to their survival, though malaise already stirs among the tree’s roots.",sp=0},{t="A Divided Hearth",b="Darnassus holds two centers of authority. High Priestess Tyrande Whisperwind guides the spiritual life and defense of her people from the Temple of the Moon, with the Sentinels at her command. Across the waterways, Archdruid Fandral Staghelm leads the druids in Malfurion’s absence. Both leaders present a united face to their new Alliance partners, yet friction between the priestesses and the druidic circle lingers.",sp=0}},faq={{q="How do you travel to Darnassus from the mainland?",a="Teldrassil lies off Kalimdor’s northwest coast, and travelers reach Rut'theran Village at the tree’s foot by boat or flight. A glowing magical portal at the village docks carries them up to Darnassus.",al={"how to get to darnassus","travel to darnassus","darnassus entrance"},it="arrival",gp=true},{q="Who rules Darnassus?",a="High Priestess Tyrande Whisperwind rules Darnassus and the kaldorei from the Temple of the Moon. Archdruid Fandral Staghelm leads the druids from the Cenarion Enclave while Malfurion Stormrage remains lost in the Emerald Dream.",al={"darnassus leader","who is in charge","ruler of darnassus"},it="in_charge",nx={10,11}},{q="Why was the city founded so recently?",a="Darnassus was founded shortly after the Third War. The night elves sacrificed their immortality to defeat Archimonde at Mount Hyjal, and Fandral Staghelm urged them to grow Teldrassil in hope of reclaiming their former state. They made Darnassus among the tree’s boughs as a new refuge.",al={"why is darnassus new","when was darnassus built","darnassus history"},it="history"},{q="Where is Archdruid Malfurion Stormrage?",a="Malfurion Stormrage is missing in the Emerald Dream, where his spirit is trapped. Archdruid Fandral Staghelm governs the druids of Teldrassil in his absence, while Tyrande Whisperwind seeks a way to awaken and recover her beloved mate.",al={"where is malfurion","is malfurion in darnassus","malfurion location"},it="identity"},{q="Where are the profession trainers and shops located?",a="Darnassus’s terraces house its trainers and shops. The Craftsmen's Terrace has gathering and tailoring trainers and an inn; the Tradesmen's Terrace holds trade stalls and the Auction House. Blacksmithing and martial trainers are on the Warrior's Terrace, and the bank sits on the central island of the Temple Gardens.",al={"darnassus professions","auction house darnassus","darnassus bank"},it="place",gp=true},{q="Why did the night elves join the Alliance?",a="After the Third War, the night elves faced growing pressure from the Horde, especially orcish logging in Ashenvale. Darnassus opened diplomatic ties and joined the Grand Alliance to find allies against those incursions and other rising threats across Kalimdor.",al={"why are night elves alliance","night elf alliance ties","alliance darnassus"},it="allies"},{q="What is Darnassus?",a="Darnassus is the capital city of the night elves, nestled high within the boughs of the great World Tree Teldrassil. Founded recently in the wake of the Third War, it serves as a peaceful sanctuary and refuge. Its open terraces, bridges, and tranquil groves surround a large central lake, reflecting the night elves' deep reverence for nature and Elune.",al={"what is this city","tell me about darnassus","darnassus lore"},it="place",add="c2a87a41",nx={8,9}},{q="Who built Darnassus?",a="The city was established by the night elves following the Third War under the direction of Archdruid Fandral Staghelm and the druids who planted Teldrassil. It was built around delicate wood lodges, shaped stone, and living boughs to honor the survival of the kaldorei after their sacrifice at Mount Hyjal.",al={"who created darnassus","who founded darnassus"},it="origin",add="a1b472ac"},{q="Why is Darnassus up in a tree?",a="After the destruction of Nordrassil at Mount Hyjal stripped the night elves of their immortality, Fandral Staghelm and fellow druids planted Teldrassil off northern Kalimdor hoping to restore their eternal life. Darnassus was raised directly within its vast, towering crown to serve as a secluded haven away from mainland perils.",al={"why is it in a tree","why teldrassil"},it="place",add="9187c5ce"},{q="Where is Tyrande Whisperwind?",a="High Priestess Tyrande Whisperwind resides within the Temple of the Moon on the southern side of Darnassus. From this moonlit sanctum, she oversees the Sisters of Elune and governs kaldorei society.",al={"where is tyrande","find tyrande"},it="leader",add="03a6f12c"},{q="Who is Fandral Staghelm?",a="Fandral Staghelm is the acting Archdruid leading the Cenarion Circle in Darnassus while Malfurion Stormrage is missing. He championed the planting of Teldrassil and holds aggressive, expansionist views for the kaldorei that frequently clash with High Priestess Tyrande Whisperwind.",al={"archdruid fandral staghelm","who is fandral"},it="identity",add="bbc7c157"},{q="What is the Temple of the Moon?",a="The Temple of the Moon is the grand center of spiritual worship in Darnassus and the official seat of kaldorei governance. Home to the Sisterhood of Elune and High Priestess Tyrande Whisperwind, it was constructed from stone brought magically from the mainland following the Third War.",al={"temple of elune darnassus","what is the moon temple"},it="place",add="2b5108ff",nx={13,14}},{q="Who is Elune?",a="Elune is the revered moon goddess of the night elves, associated with peace, healing, and the night sky. The kaldorei center their spiritual lives around her worship, guided by her high priestess and the Sisterhood of Elune.",al={"goddess elune","what is elune"},it="other",add="4096dbf8"},{q="Why is there a fountain inside the Temple of the Moon?",a="At the center of the temple lies a sacred moonwell beneath the statue of Haidene. Its blessed waters are considered the touch of Elune herself, utilized by the Sisterhood of Elune for bathing, recuperation, and holy rites.",al={"temple of the moon pool","fountain of elune darnassus"},it="place",add="e87e3fa7"},{q="What is the Cenarion Enclave?",a="The Cenarion Enclave is a lush grove in northwestern Darnassus where the city's druids meet and train. Lined with ancient trees bearing mystic runes, it houses the living wood sanctum of Archdruid Fandral Staghelm and serves as the gathering place for the Cenarion Circle.",al={"cenarion enclave darnassus","where are druids in darnassus"},it="place",add="0e74b3a4"},{q="Why is Fandral Staghelm the Arch Druid and not Malfurion?",a="Archdruid Malfurion Stormrage mysteriously disappeared into the Emerald Dream following the Third War. In his absence, Fandral Staghelm stepped forward to take command of the druids and spearhead the planting of Teldrassil.",al={"why is fandral leading","why isn't malfurion archdruid"},it="in_charge",add="e546b5d1"},{q="Is Darnassus dangerous?",a="Darnassus itself is tranquil and heavily secured by night elf Sentinels, towering Ancient Protectors, and Ancients of War. The city remains a peaceful haven for the Alliance, though unrest and corruption simmer in the surrounding wilderness of Teldrassil.",al={"is darnassus safe","threats in darnassus"},it="danger",add="c7c576ca"},{q="How did I end up in Darnassus?",a="If you are a night elf, your journey likely began in Shadowglen, descending down through Dolanaar before following the forest road west across the boughs of Teldrassil to its capital gates. Travelers from abroad instead arrive far below by ship from the mainland, docking at Rut'theran Village at the foot of the World Tree, before stepping through the glowing enchanted portal that transports them straight up into the city.",al={"how did i get here","how did i arrive in darnassus","how did i get to darnassus"},it="arrival",add="6a190c74"},{q="What am I supposed to be doing in Darnassus?",a="Darnassus serves as the political and spiritual heart of the kaldorei. Adventurers come here to seek guidance from the leadership—High Priestess Tyrande Whisperwind in the Temple of the Moon or Archdruid Fandral Staghelm in the Cenarion Enclave—while consulting weapon trainers, class mentors, and craftsmen across its terraces. Whether you are sent into the wilderness to cleanse the taint afflicting Teldrassil or preparing to journey beyond its shores to the troubled mainland, the city provides the supplies, instruction, and decrees you need.",al={"what am i doing here","why am i in darnassus","what should i do in darnassus"},it="purpose",add="2586ce4f"}},ang={["race:NightElf"]="As a night elf, you have Darnassus as the heart and sanctuary of your people while you face the trials of mortal life.",["class:Druid"]="The Cenarion Enclave is the center of druidic training in Teldrassil, under Archdruid Fandral Staghelm’s demanding and uncompromising eye.",["class:Priest"]="The Temple of the Moon is the holy center of the Sisters of Elune, led by High Priestess Tyrande Whisperwind.",["faction:Alliance"]="Darnassus is the Alliance’s westernmost stronghold, offering naval and strategic shelter on Kalimdor."},kw={"cenarion enclave","darnassus","fandral","night elf capital","rut'theran","staghelm","teldrassil","temple of the moon","tyrande","whisperwind"},rel={"subzone:temple-of-the-moon","subzone:cenarion-enclave","subzone:rut-theran-village","npc:tyrande-whisperwind","npc:fandral-staghelm","topic:night-elf","quest:940","zone:ashenvale"},src={"Darnassus"}}
